window.GUA_DATABASE_V3 = [{"卦序":1,"卦名":"乾","卦符":"䷀","全名":"乾為天","上卦":"乾","下卦":"乾","卦辞":"乾，元亨，利貞。","彖传":"《彖》曰：大哉乾元，萬物資始，乃統天。雲行雨施，品物流形。大明終始，六位時成，時乘六龍以御天。乾道變化，各正性命，保合太和，乃利貞。首出庶物，萬國咸寧。","大象":"《象》曰：天行健，君子以自強不息。","互卦":"01 乾䷀","错卦":"02 坤䷁","综卦":"01 乾䷀","爻":[{"爻位":"初九","原文":"潛龍勿用。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 潜：潜藏。龙：乾卦取象之核心，象征刚健而有变化能力的阳性生命。勿用：不是永久不用，而是时机未至，不宜显露、强行施为。","译文":"潜藏的龙，不宜有所施展。","解说1_经义":"初九是乾卦阳气初生的阶段。能力、志向已经存在，但尚在最下位，条件与社会位置都未成熟。此时真正的“乾健”不是急于表现，而是蓄积、学习、等待可以承担后果的时机；“勿用”因此是一种主动的克制。","解说2_时位":"从时位看，本爻处在全卦发端，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：潛龍勿用，陽在下也。","象传译文":"《象传》说：“潜龙勿用”，是因为阳气尚处在最下方。","象传解说":"小象把爻辞的关键落在“在下”。不是否定阳刚，而是说明同一种力量处在不同位置，使用方式必须不同；这正是《易》重“时位”的典型例子。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **44 姤䷫**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"見龍在田，利見大人。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 大人：有德有位、有能力担当大事之人；不宜简单等同现代某一具体身份。 利：适宜、有利。 见，读xiàn，通“现”，出现。田：地上、人间活动空间。“利见大人”中的“见”读jiàn，可理解为见到、接近或显现大人之德。九二虽为阳爻居阴位，但处下卦中位，得中。","译文":"龙已经显现在田野之上，适宜见到有德有位的大人，也适宜使自己的大人之德被看见。","解说1_经义":"与初九的“潜”相比，九二已经由隐藏进入显现。它强调的不是骤然跃居最高位，而是在现实社会中使德能产生影响，并通过合宜的人际与制度关系获得施展空间。“田”是从潜藏走向公共世界的第一层舞台。","解说2_时位":"从时位看，本爻处在下卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：見龍在田，德施普也。","象传译文":"《象传》说：“见龙在田”，是说其德泽已经能够普遍施展。","象传解说":"“德施普”说明九二的价值不只在个人显达，而在能力开始能够惠及他人。得中使这种显现不走极端，所以传统注家往往把九二与九五并列为乾卦较佳的中位。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **13 同人䷌**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"君子終日乾乾，夕惕若，厲，無咎。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 乾乾：健行不息、反复努力。惕：警惕、戒惧。若：语助。厉：有危险。九三居下卦之终，是内外转换的临界位置。","译文":"君子整天奋发不懈，到了夜晚仍警惕自省；虽处危险之际，可以没有灾咎。","解说1_经义":"九三的难点不是能力不足，而是力量已强、位置又临近转折，最容易因自信而失慎。爻辞用“终日乾乾”与“夕惕”把进取和戒惧同时提出：只有持续做事，同时不断校正自己，才能穿过这个高风险阶段。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：終日乾乾，反復道也。","象传译文":"《象传》说：“终日乾乾”，是反复践行正道。","象传解说":"小象用“反复道”解释乾乾，强调这不是一次性的勤奋，而是持续检验与重复实践。九三所以“多惧”，正在于其处下卦上端，前进一步便进入新的层级。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **10 履䷉**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"或躍在淵，無咎。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 或：不定之辞，表示进退未决。跃：向上跃起。渊：深水、深处。九四为上卦初位，是从内向外、从臣位向更高层次转换的关口。","译文":"龙或向上跃起，或仍处深渊；只要审时进退，便没有灾咎。","解说1_经义":"九四并不要求“必须跃”，而强调“或”。这是一条典型的试探性爻辞：条件成熟可以进，条件不足可以退守。进退之间保留弹性，正是跨越层级时降低风险的方法。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：或躍在淵，進無咎也。","象传译文":"《象传》说：“或跃在渊”，说明向前进取本身并无过失。","象传解说":"小象的重点在“进无咎”而不是“进必吉”。九四允许进，但是否真正上升仍取决于时机与德能；因此它比九五多一层试探性。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **09 小畜䷈**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"飛龍在天，利見大人。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 大人：有德有位、有能力担当大事之人；不宜简单等同现代某一具体身份。 利：适宜、有利。 飞龙：龙完全升腾。天：上层、最高的活动空间。“大人”指能承担重大责任、德位相称者。九五阳居阳位，又居上卦中位，为当位且得中。","译文":"龙飞翔于天，适宜见大人、成就大人之业。","解说1_经义":"九五是乾卦力量最成熟而又尚未过亢的位置。与九二相比，它不仅“显现”，而是已经取得足以承担公共责任的位置。爻辞所赞许的不是权位本身，而是德、能、位三者相称。","解说2_时位":"从时位看，本爻处在上卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：飛龍在天，大人造也。","象传译文":"《象传》说：“飞龙在天”，是大人有所作为、成就事业之时。","象传解说":"“大人造”中的“造”可理解为作为、成就。九五之所以成为传统上最受重视的爻位之一，正在于既中且正，力量充分而不过极。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **14 大有䷍**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"亢龍有悔。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔：悔恨，亦指可由反省而改的失误。 亢：过高、穷极。悔：事后可反省的失误与不利。上九处全卦最高位，阳刚发展到极点。","译文":"龙飞得过高，终将产生悔恨。","解说1_经义":"乾卦从潜、见、乾乾、或跃、飞一路上升，到上九出现转折。问题不在“强”，而在“强而不知止”；不再有更高空间时仍继续上冲，就会从优势转为孤立和失衡。此爻是《易》“盛极须戒”的典型。","解说2_时位":"从时位看，本爻处在全卦终位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：亢龍有悔，盈不可久也。","象传译文":"《象传》说：“亢龙有悔”，因为盈满的状态不能长久保持。","象传解说":"“盈不可久”把上九放入变化论来理解：任何极盛状态都含有转化条件。真正的乾德不仅会进，也必须知道何时收敛。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **43 夬䷪**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"用九","原文":"見群龍無首，吉。","注释":"用九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 用九：乾卦特有的特殊辞，用于六爻皆为老阳而全部发动的情形。群龙无首：诸龙并见而不以一龙自居其首。","译文":"出现群龙而没有一个自居为首者，吉祥。","解说1_经义":"“用九”讨论的不是第七爻，而是纯阳如何在全变之际被使用。六阳皆动将转为坤，说明刚健发展到极致时，最重要的是去掉争先、独占与自我中心，使刚健能够转入承载和合作。","解说2_时位":"这一条不是乾卦之上的“第七爻”，而是六个阳爻全部取得老阳九并同时发动时的总用辞。从大衍筮法看，此时本卦乾全部翻转为坤；因此解释重点是“纯刚如何转柔”，即刚健发展到极致后，不再以争首为能，而转入承载、协同与开放。","结构分析":"“用九”属于乾卦特殊用辞，不参与初、二、三、四、五、上六个位次的当位/应比计算。它只在六爻全部为老阳九时出现；六阳同时变阴，乾之坤。","象传":"《象》曰：用九，天德不可為首也。","象传译文":"《象传》说：“用九”，表明天之德不以自居首领为原则。","象传解说":"“不可为首”不是否定组织秩序，而是警戒把乾德误解成争强居首。全阳皆变时，能不固守刚强，才真正符合变化之道。","大衍实占":"大衍筮法若六爻全部得到9（老阳），则乾卦六爻皆动，之卦为坤。此时“用九：见群龙无首，吉”是乾卦专门的总用辞，应与乾卦卦辞、六爻整体过程及之卦坤综合读取。"}],"单爻发动之卦":{"初爻":"44 姤䷫","二爻":"13 同人䷌","三爻":"10 履䷉","四爻":"09 小畜䷈","五爻":"14 大有䷍","上爻":"43 夬䷪"}},{"卦序":2,"卦名":"坤","卦符":"䷁","全名":"坤為地","上卦":"坤","下卦":"坤","卦辞":"坤，元亨，利牝馬之貞。君子有攸往，先迷後得主，利。西南得朋，東北喪朋。安貞吉。","彖传":"《彖》曰：至哉坤元，萬物資生，乃順承天。坤厚載物，德合無疆。含弘光大，品物咸亨。牝馬地類，行地無疆，柔順利貞。君子攸行，先迷失道，後順得常。西南得朋，乃與類行；東北喪朋，乃終有慶。安貞之吉，應地無疆。","大象":"《象》曰：地勢坤，君子以厚德載物。","互卦":"02 坤䷁","错卦":"01 乾䷀","综卦":"02 坤䷁","爻":[{"爻位":"初六","原文":"履霜，堅冰至。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 霜：阴寒初凝之象。坚冰：阴寒积累到极盛的结果。“履霜”是脚下已经出现可察觉的先兆。","译文":"脚下已经踏到霜，就应知道坚冰将逐渐形成。","解说1_经义":"初六强调“见微知著”。危险并非突然从无到有，而是有累积过程；初期的微小征兆若被忽略，最终会发展为难以逆转的局面。用于修身、治理或风险判断，都指向早察、早防。","解说2_时位":"从时位看，本爻处在全卦发端，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：履霜堅冰，陰始凝也；馴致其道，至堅冰也。","象传译文":"《象传》说：踏霜而知坚冰，是因为阴气刚开始凝聚；顺着这个趋势发展，就会到坚冰。","象传解说":"小象把“霜—冰”解释为渐变链条。它体现《易》关注趋势而非只看当下结果的思维。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **24 復䷗**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"直方大，不習無不利。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 直：不曲。方：有规矩、有边界。大：广大。不习：不待反复学习或刻意造作。六二阴居阴位，又居下卦中位，当位得中。","译文":"正直、方正、广大，即使不刻意造作，也没有不利。","解说1_经义":"六二是坤德最纯正的表达之一。“直”是内在诚实，“方”是外在有则，“大”是承载范围广；三者结合，形成柔顺而不失原则的力量。坤的“顺”因此绝非无原则服从。","解说2_时位":"从时位看，本爻处在下卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六二之動，直以方也；不習無不利，地道光也。","象传译文":"《象传》说：六二的行动体现正直与方正；不待学习而无不利，是因为地道本身光大。","象传解说":"得中且当位使六二的柔顺稳定而不偏。小象强调“地道光”，说明柔德同样可以具有明朗、广大的积极性。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **07 師䷆**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"含章可貞；或從王事，無成有終。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 含章：把文采、才德含藏于内。可贞：可以守正。王事：公共事务、君王之事。无成有终：不以功劳自居而把事情完成。","译文":"含藏才华而守正；若参与王事，不抢占功名，却能把事情完成。","解说1_经义":"六三处下卦之终，能力已经形成，却不宜急于争功。坤道在此体现为“成事而不居成”：参与重要工作，可以有贡献，但不把成果据为个人所有。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：含章可貞，以時發也；或從王事，知光大也。","象传译文":"《象传》说：“含章可贞”，是等待时机而后发；参与王事，智慧因此显得光明广大。","象传解说":"“以时发”说明含藏不是永远隐藏，而是为适时而发。坤德的关键不是消极，而是让行动与时机、角色相匹配。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **15 謙䷎**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"括囊，無咎無譽。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 括囊：扎紧袋口，比喻谨慎闭藏。誉：赞誉。六四进入上卦初位，处进退敏感位置。","译文":"把袋口扎紧，不招灾咎，也不求赞誉。","解说1_经义":"六四所处位置不适合张扬。此时最重要的是少言、慎行、守住边界。爻辞同时说“无咎无誉”，说明有些阶段的最优策略不是追求成就感，而是安全地度过风险区。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：括囊無咎，慎不害也。","象传译文":"《象传》说：“括囊无咎”，是谨慎就不会受害。","象传解说":"小象直接把无咎归因于“慎”。这是一种风险管理式的智慧：在信息、权力或局势不明时，克制表达有时比积极表现更重要。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **16 豫䷏**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"黃裳，元吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 黄：居中色。裳：下衣，取坤之在下、柔顺之象。元吉：大吉。六五虽阴居阳位，但居上卦中位，得中。","译文":"穿着黄色下裳，大吉。","解说1_经义":"“黄”象征中，“裳”象征谦下。六五处尊位却以柔德居之，因此吉不在强势控制，而在守中、谦下、以承载方式发挥影响。它是坤卦“柔居尊位”最典型的表达。","解说2_时位":"从时位看，本爻处在上卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：黃裳元吉，文在中也。","象传译文":"《象传》说：“黄裳元吉”，是因为文德居于中位。","象传解说":"小象以“文在中”突出中德。位置虽非阴阳相当，但得中足以调和其不当位，因此传统解释多重视六五的中和。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **08 比䷇**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"龍戰于野，其血玄黃。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 龙战于野：两股强大力量在边界地带冲突。玄黄：传统上以玄属天、黄属地，血色兼玄黄象征阴阳两伤。","译文":"龙在野外交战，流出的血呈玄黄相杂之色。","解说1_经义":"上六是阴柔发展到极端，已经不再只是承顺，而转为与阳刚争强。爻辞以两龙交战提示：当角色失去边界、柔顺走向极端反抗时，冲突常造成双方损伤。","解说2_时位":"从时位看，本爻处在全卦终位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：龍戰于野，其道窮也。","象传译文":"《象传》说：“龙战于野”，是因为阴道已经走到穷尽。","象传解说":"“其道穷”不是说阴本身错误，而是任何一方发展到极端都会失去适宜性。坤卦与乾卦在上爻都出现“极则变”的警告。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **23 剝䷖**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"用六","原文":"利永貞。","注释":"用六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 用六：坤卦特有的特殊辞，用于六爻皆为老阴而全部发动。永贞：长久守持正固。","译文":"适宜长久保持正固。","解说1_经义":"六阴皆动将转为乾。此时坤的用法不是僵化地守柔，而是在变化中保持原则，使承载、柔顺转化为新的主动性。“永贞”强调的是原则可久，而不是形态永远不变。","解说2_时位":"这一条不是坤卦之上的“第七爻”，而是六个阴爻全部取得老阴六并同时发动时的总用辞。从大衍筮法看，此时本卦坤全部翻转为乾；因此解释重点是“纯柔如何转刚”，即长期守正的承载力在时机成熟后转化为主动创造力。","结构分析":"“用六”属于坤卦特殊用辞，不参与初、二、三、四、五、上六个位次的当位/应比计算。它只在六爻全部为老阴六时出现；六阴同时变阳，坤之乾。","象传":"《象》曰：用六永貞，以大終也。","象传译文":"《象传》说：“用六永贞”，意味着坤道以广大而完整的方式告终。","象传解说":"“以大终”说明柔顺若能守正，其完成并非消极结束，而是为下一轮变化准备条件。","大衍实占":"大衍筮法若六爻全部得到6（老阴），则坤卦六爻皆动，之卦为乾。此时“用六：利永贞”是坤卦专门的总用辞，应与坤卦卦辞、六爻整体过程及之卦乾综合读取。"}],"单爻发动之卦":{"初爻":"24 復䷗","二爻":"07 師䷆","三爻":"15 謙䷎","四爻":"16 豫䷏","五爻":"08 比䷇","上爻":"23 剝䷖"}},{"卦序":3,"卦名":"屯","卦符":"䷂","全名":"水雷屯","上卦":"坎","下卦":"震","卦辞":"屯，元亨，利貞。勿用有攸往，利建侯。","彖传":"《彖》曰：屯，剛柔始交而難生，動乎險中，大亨貞。雷雨之動滿盈，天造草昧，宜建侯而不寧。","大象":"《象》曰：雲雷，屯。君子以經綸。","互卦":"23 剝䷖","错卦":"50 鼎䷱","综卦":"04 蒙䷃","爻":[{"爻位":"初九","原文":"磐桓；利居貞，利建侯。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 磐桓：徘徊难进，也含扎根、盘桓之意。居贞：安居而守正。建侯：建立组织、确立领导与秩序。","译文":"局面草创、进展艰难，宜先安定守正，并建立可以组织众人的核心。","解说1_经义":"屯卦是万事初生而多难。初九虽有行动力，却处在困难开端，贸然猛进不如先立基础、定规则、聚人心。“利建侯”说明困难时期首先需要形成秩序中心。","解说2_时位":"从时位看，本爻处在全卦发端，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：雖磐桓，志行正也；以貴下賤，大得民也。","象传译文":"《象传》说：虽然磐桓难进，但志向仍在行正道；能以尊贵而下就卑者，便能得到民众。","象传解说":"小象把初九的吉处放在“志行正”和“以贵下贱”。创业之初，领导力来自扎根与谦下，而不是高高在上。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **08 比䷇**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"屯如邅如，乘馬班如。匪寇婚媾。女子貞不字，十年乃字。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 邅如：行进困难、回旋不前。班如：盘旋、徘徊。匪寇婚媾：来者不是强寇，而是求婚结亲。字：女子许嫁。","译文":"进退艰难，骑马者盘旋而来；来者并非盗寇，而是求婚。女子暂不许嫁，十年之后才许嫁。","解说1_经义":"六二面对的是“看似威胁、实有结合可能”的复杂关系。其要义在于不要因压力仓促决定；即使存在正当结合，也需等待条件成熟。“十年”强调长期等待，不宜拘泥为现代精确年数。","解说2_时位":"从时位看，本爻处在下卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的内卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六二之難，乘剛也；十年乃字，反常也。","象传译文":"《象传》说：六二之所以困难，是因为柔爻乘在初九刚爻之上；十年才许嫁，是最终回归常道。","象传解说":"小象把困难部分归于“乘刚”，把结果归于“反常”。结构上有应于九五，说明长期看存在正当归属，但眼前关系仍有阻滞。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **60 節䷻**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"即鹿無虞，惟入于林中，君子幾不如舍，往吝。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 吝：艰难、遗憾、局促之象。 往：前往、向外发展。 即鹿：追逐鹿。虞：掌山林、熟悉地形的向导。幾：察知微兆。舍：停止。","译文":"追鹿却没有向导，只会深入林中；君子看见苗头不对，不如及时停止，继续前往会有遗憾。","解说1_经义":"六三讲的是信息不足却被目标吸引。困难局势中，如果缺少专业引导和环境判断，行动越积极反而越容易深入险地。“幾不如舍”把识别停止点视为一种能力。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦震（动、发起、震动、雷）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：即鹿無虞，以從禽也；君子舍之，往吝窮也。","象传译文":"《象传》说：追鹿没有向导，是只顾追逐猎物；君子选择停止，是因为继续走下去会陷入困穷。","象传解说":"小象批评的是被目标牵引而忘记条件。没有路径信息时，止损比执着更符合屯难之时。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **63 既濟䷾**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"乘馬班如，求婚媾，往吉，無不利。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 往：前往、向外发展。 婚媾：婚姻结合，亦可泛指正当合作关系。六四与初九相应。","译文":"骑马徘徊，若主动求取正当结合，前往则吉，无所不利。","解说1_经义":"六四已经进入上卦，先前的犹疑需要转为有方向的合作。与初九有应，表明关系基础存在；此时如果因顾虑而不行动，反而错过连接资源与伙伴的机会。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的上卦之始、进入外部阶段位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：求而往，明也。","象传译文":"《象传》说：有所求而前往，是因为已经明白应当怎样行动。","象传解说":"小象以“明”解释其吉，说明六四不是盲目求合，而是识别到正确对应后再行动。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **17 隨䷐**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"屯其膏，小貞吉，大貞凶。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 凶：凶险、不利。 膏：滋养、恩泽。小贞、大贞：可理解为小事守正尚吉，大规模强行则凶。","译文":"处于屯难中，恩泽难以充分施布；小事守正可吉，大事强求则凶。","解说1_经义":"九五虽居尊位且得中，但屯卦总体环境仍困难，资源与政策传导受到阻滞。此时宜做小而确定的改善，不宜凭职位优势发动过大的行动。","解说2_时位":"从时位看，本爻处在上卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：屯其膏，施未光也。","象传译文":"《象传》说：“屯其膏”，是恩泽施布还不够光大。","象传解说":"九五自身位置很好，却不能脱离全卦时势。它提醒：好位置不等于环境已成熟，治理效果还取决于通道是否畅通。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **24 復䷗**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"乘馬班如，泣血漣如。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 泣血：哭泣至血，极言悲困。漣如：泪流不断的样子。","译文":"骑马仍盘旋难进，悲伤得泪血涟涟。","解说1_经义":"上六已到屯难的尽头，却仍未找到出路，说明错失前面可调整、可合作的节点后，困局会累积成情绪和资源双重耗竭。此爻不是鼓励坚持，而是警示不要把困难拖到无路可走。","解说2_时位":"从时位看，本爻处在全卦终位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦坎（险、陷、流行、水）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：泣血漣如，何可長也。","象传译文":"《象传》说：泣血涟涟，这种状态怎么可能长久呢？","象传解说":"“何可长”既是警告，也暗示穷则必变。到极点时，继续维持原状本身已不可行。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **42 益䷩**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"08 比䷇","二爻":"60 節䷻","三爻":"63 既濟䷾","四爻":"17 隨䷐","五爻":"24 復䷗","上爻":"42 益䷩"}},{"卦序":4,"卦名":"蒙","卦符":"䷃","全名":"山水蒙","上卦":"艮","下卦":"坎","卦辞":"蒙，亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告。利貞。","彖传":"《彖》曰：蒙，山下有險，險而止，蒙。蒙亨，以亨行，時中也。匪我求童蒙，童蒙求我，志應也。初筮告，以剛中也。再三瀆，瀆則不告，瀆蒙也。蒙以養正，聖功也。","大象":"《象》曰：山下出泉，蒙。君子以果行育德。","互卦":"24 復䷗","错卦":"49 革䷰","综卦":"03 屯䷂","爻":[{"爻位":"初六","原文":"發蒙，利用刑人，用說桎梏，以往吝。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 利：适宜、有利。 往：前往、向外发展。 发蒙：启发蒙昧。刑人：古义涉及刑罚、规范。说：通“脱”。桎梏：脚镣手铐。以往吝：若一味以刑罚推进则有遗憾。","译文":"启蒙之初，可以借助规则纠正行为、解除束缚；但若把惩戒当成长期办法，继续如此就会有遗憾。","解说1_经义":"初六讨论教育的第一步：无规则不足以立界限，但规则的目的在于使人脱离蒙昧和束缚，而不是持续处罚。若教育停留在强制层面，便违背启蒙本意。","解说2_时位":"从时位看，本爻处在全卦发端，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦坎（险、陷、流行、水）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：利用刑人，以正法也。","象传译文":"《象传》说：使用刑罚或规范，是为了使法则得到端正。","象传解说":"小象把重点放在“正法”，说明惩戒只能作为建立秩序的手段，最终目标仍是使人能够自觉。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **41 損䷨**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"包蒙，吉。納婦，吉；子克家。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 包蒙：包容蒙昧、承担启蒙责任。纳妇：接纳妻室。子克家：子能治家。","译文":"能够包容、教育蒙昧者，吉；娶妻吉，子弟能够承担家业。","解说1_经义":"九二刚中，是蒙卦中主要的教育者。真正的启蒙者不是嫌弃受教者“无知”，而是有能力容纳其尚未成熟的状态，并通过持续教导使之成长。","解说2_时位":"从时位看，本爻处在下卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：子克家，剛柔接也。","象传译文":"《象传》说：“子克家”，说明刚柔能够相接。","象传解说":"九二以刚居阴位虽不当，却得中并能与六五相应；刚而能包柔，正构成教育关系所需要的承接。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **23 剝䷖**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"勿用取女，見金夫，不有躬，無攸利。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 取女：娶女。金夫：有财势、强势之男。不有躬：不能持守自身、失去自主。","译文":"不宜娶这样的女子：她见到有势力的人便失去自守，没有什么利益。","解说1_经义":"六三讲受外在诱惑而失去主体性。蒙昧若没有内在原则，容易把财富、权势当作唯一判断标准；这种关系即使建立，也难以稳定。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：勿用取女，行不順也。","象传译文":"《象传》说：不宜娶此女，是因为她的行为不顺正道。","象传解说":"小象把问题归结为“行不顺”，强调关键不是身份，而是行为失序、不能守正。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **18 蠱䷑**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"困蒙，吝。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 困蒙：被蒙昧困住，缺少启发渠道。","译文":"困在蒙昧之中，令人遗憾。","解说1_经义":"六四上下缺少有效的刚爻援引，象征既没有主动求知，也缺少良师善友。蒙最怕的不是暂时不懂，而是长期封闭在不懂之中而不求改变。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦艮（止、界限、山）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：困蒙之吝，獨遠實也。","象传译文":"《象传》说：困蒙之所以遗憾，是因为独自远离实在的教导。","象传解说":"“独远实”可理解为与真实、可靠的知识或有力的引导相隔。开放求教，是解除困蒙的第一步。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **64 未濟䷿**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"童蒙，吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 童蒙：如童子般尚未成形的蒙昧状态。六五柔中，能够虚心受教。","译文":"像童子一样虚心求教，吉。","解说1_经义":"六五处尊位却不自以为是，正是蒙卦最可贵之处。处高位仍承认自己需要学习，才能与九二这一教育者形成良好回应。","解说2_时位":"从时位看，本爻处在上卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦艮（止、界限、山）的上卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：童蒙之吉，順以巽也。","象传译文":"《象传》说：童蒙之吉，在于能柔顺而谦逊地接受教导。","象传解说":"小象用“顺以巽”强调学习姿态。知识不足不是凶，拒绝学习才会使蒙昧固化。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **59 渙䷺**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"擊蒙；不利為寇，利禦寇。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 击蒙：以强力击破顽蒙。为寇：主动侵害。御寇：防御侵害。","译文":"可以击破顽固的蒙昧；但不宜把自己变成攻击者，宜用于防御侵害。","解说1_经义":"启蒙走到最后，对顽固、危害性的行为有时需要强力制止。但力量的边界必须清楚：目的是止害、纠偏，而不是借教育之名实施压制和报复。","解说2_时位":"从时位看，本爻处在全卦终位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦艮（止、界限、山）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：利用禦寇，上下順也。","象传译文":"《象传》说：适宜防御寇害，是因为上下能够顺应正当秩序。","象传解说":"小象把“御寇”与“上下顺”联系，说明强制只有在维护合理秩序时才具有正当性。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **07 師䷆**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"41 損䷨","二爻":"23 剝䷖","三爻":"18 蠱䷑","四爻":"64 未濟䷿","五爻":"59 渙䷺","上爻":"07 師䷆"}},{"卦序":5,"卦名":"需","卦符":"䷄","全名":"水天需","上卦":"坎","下卦":"乾","卦辞":"需，有孚，光亨，貞吉。利涉大川。","彖传":"《彖》曰：需，須也，險在前也。剛健而不陷，其義不困窮矣。需有孚，光亨，貞吉，位乎天位，以正中也。利涉大川，往有功也。","大象":"《象》曰：雲上于天，需。君子以飲食宴樂。","互卦":"38 睽䷥","错卦":"35 晉䷢","综卦":"06 訟䷅","爻":[{"爻位":"初九","原文":"需于郊，利用恒，無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 需于郊：在远离险境的郊外等待。恒：持续、守常。","译文":"在郊外等待，宜保持恒常，因此没有灾咎。","解说1_经义":"初九离坎险尚远，最好的策略不是提前焦虑或冒进，而是在安全距离上稳定准备。等待并非不作为，而是保持节奏、积蓄资源。","解说2_时位":"从时位看，本爻处在全卦发端，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：需于郊，不犯難行也；利用恒無咎，未失常也。","象传译文":"《象传》说：在郊外等待，是尚未冒险前行；保持恒常而无咎，是没有失去常道。","象传解说":"“未犯难行”说明风险管理的第一原则是不要无谓接近危险。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **48 井䷯**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"需于沙，小有言，終吉。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 沙：水边之沙，已接近险水。小有言：有些议论、摩擦。","译文":"等待已到沙边，会有一些言语纷扰，但最终吉。","解说1_经义":"九二离危险更近，但仍得中。外界可能出现催促、质疑或小冲突，此时不必因噪音改变基本节奏；稳住中道即可。","解说2_时位":"从时位看，本爻处在下卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：需于沙，衍在中也；雖小有言，以終吉也。","象传译文":"《象传》说：需于沙，是宽缓地处在中位；虽有小的言语纷争，最终仍吉。","象传解说":"得中是本爻稳定性的来源。越接近风险区，越需要不被舆论和情绪牵动。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **63 既濟䷾**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"需于泥，致寇至。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 泥：临近水险的泥泞地带。致寇至：自己的处置使寇患来到。","译文":"等待到了泥泞之地，已经过度靠近危险，容易招来侵扰。","解说1_经义":"九三刚而不中，已经贴近坎险。危险并不完全来自外部；主动把自己置于风险边缘，也是在“致寇”。所以此爻强调自我造成的风险暴露。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：需于泥，災在外也；自我致寇，敬慎不敗也。","象传译文":"《象传》说：需于泥，灾害已在外面；寇患由自己招致，只要敬慎仍可不败。","象传解说":"小象没有把结果写死，它留下了“敬慎不败”的修正空间：认清风险来源后仍可及时收缩。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **60 節䷻**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"需于血，出自穴。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 血：伤害、险境。穴：洞穴，坎险之象。六四已进入上卦坎。","译文":"在血险之中等待，应从险穴中退出来。","解说1_经义":"六四已经身在危险内部，策略由“等待”转向“脱离”。当环境已经造成实质伤害时，再把坚持当美德就不合时宜；顺势退出才是正确动作。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：需于血，順以聽也。","象传译文":"《象传》说：需于血，应当柔顺听从形势。","象传解说":"“顺以听”强调对客观风险的服从。此时不是证明勇敢，而是承认限制并退出危险通道。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **43 夬䷪**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"需于酒食，貞吉。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 酒食：饮食宴享，象征从容等待。九五居尊位且中正。","译文":"在酒食之间从容等待，守正则吉。","解说1_经义":"九五说明最成熟的等待不是焦虑地盯着结果，而是有资源、有秩序地维持日常。真正的耐心来自对条件和节奏的掌握。","解说2_时位":"从时位看，本爻处在上卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦坎（险、陷、流行、水）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：酒食貞吉，以中正也。","象传译文":"《象传》说：酒食而守正之所以吉，是因为居中而正。","象传解说":"中正使九五既不怠惰，也不躁进。需卦到这里，等待成为一种有掌控力的节制。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **11 泰䷊**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"入于穴，有不速之客三人來，敬之終吉。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 不速之客：未经邀请而来的客人。三人：多位来客，不必拘泥实数。","译文":"进入洞穴，有三位不请自来的客人到来；若恭敬相待，最终吉。","解说1_经义":"上六处需之终，局势已经超出原先控制，外部因素突然进入。最有效的做法不是敌视一切意外，而是以礼应对、调整关系，使潜在冲突转为可处理的互动。","解说2_时位":"从时位看，本爻处在全卦终位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不速之客來，敬之終吉，雖不當位，未大失也。","象传译文":"《象传》说：不请自来的客人到来，恭敬相待终吉；虽然位置不当，却没有造成大的失误。","象传解说":"小象承认上六“不当位”，但也说明态度能够修正结构缺陷。礼敬在这里是一种化险机制。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **09 小畜䷈**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"48 井䷯","二爻":"63 既濟䷾","三爻":"60 節䷻","四爻":"43 夬䷪","五爻":"11 泰䷊","上爻":"09 小畜䷈"}},{"卦序":6,"卦名":"訟","卦符":"䷅","全名":"天水訟","上卦":"乾","下卦":"坎","卦辞":"訟，有孚，窒惕，中吉，終凶。利見大人，不利涉大川。","彖传":"《彖》曰：訟，上剛下險，險而健，訟。訟有孚窒惕，中吉，剛來而得中也。終凶，訟不可成也。利見大人，尚中正也。不利涉大川，入于淵也。","大象":"《象》曰：天與水違行，訟。君子以作事謀始。","互卦":"37 家人䷤","错卦":"36 明夷䷣","综卦":"05 需䷄","爻":[{"爻位":"初六","原文":"不永所事，小有言，終吉。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 不永所事：不把争讼长期化。小有言：有小争辩。","译文":"不要把争讼之事拖长；虽会有些言语冲突，最终可吉。","解说1_经义":"讼卦初爻提示：冲突一开始就要控制升级。很多争端的成本并不在最初分歧，而在不断投入情绪、时间和身份认同后变得无法收场。","解说2_时位":"从时位看，本爻处在全卦发端，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不永所事，訟不可長也；雖有小言，其辯明也。","象传译文":"《象传》说：不把事情拖长，是因为争讼不可长久；虽有小争辩，终能辨明。","象传解说":"小象把“止争于初”视为关键。能在早期讲清而退出，比赢得长期对抗更重要。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **10 履䷉**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"不克訟，歸而逋，其邑人三百戶，無眚。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 不克讼：争讼不能取胜。逋：逃避、退走。邑人三百户：小邑之众，表示退守小范围。","译文":"争讼不能取胜，宜退回自己的地方避开；守住小范围可免灾。","解说1_经义":"九二虽刚中，但与九五强者相争，结构上并不适宜。此爻不是讲怯懦，而是讲识别力量差距：不能胜时及时退出，可保存基本盘。","解说2_时位":"从时位看，本爻处在下卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦坎（险、陷、流行、水）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不克訟，歸逋竄也；自下訟上，患至掇也。","象传译文":"《象传》说：争讼不胜而归，是退避；从下位与上位争讼，祸患容易到来。","象传解说":"“自下讼上”点出结构风险。位置关系有时比主观正确感更决定成本。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **12 否䷋**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"食舊德，貞厲，終吉；或從王事，無成。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 食旧德：享用既有德业、俸禄或既成基础。贞厉：守正仍有危险。无成：不居功。","译文":"依靠既有德业而生活，守正虽有风险，最终吉；若参与王事，不把功劳据为己有。","解说1_经义":"六三不适合以争夺方式扩张，更适合守住已有正当所得，并在公共事务中尽责而不争功。讼卦中的柔爻，以不争反而能终吉。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：食舊德，從上吉也。","象传译文":"《象传》说：依靠旧德，是顺从上方而得吉。","象传解说":"小象强调“从上”，说明六三的安全来自遵守合理秩序，而非在不利位置主动争胜。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **44 姤䷫**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"不克訟，復即命，渝，安貞，吉。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 复即命：回到应有的命分、秩序。渝：改变。安贞：安于正道。","译文":"争讼不能取胜，便回到应守的分位，改变争心，安于正道，吉。","解说1_经义":"九四的可贵之处在于会改。刚爻容易坚持己见，但发现诉讼路径不合适后，能够转身回归规则，反而化凶为吉。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：復即命渝，安貞不失也。","象传译文":"《象传》说：回到命分、改变争讼之心，安于正道，就不会失去根本。","象传解说":"“渝”在此不是反复无常，而是知错能改。讼卦最重要的能力之一，是让冲突有退出机制。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **59 渙䷺**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"訟，元吉。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 九五居尊位、中正，是讼卦中能够公平裁断的位置。","译文":"在争讼之事上得到最公正的处理，大吉。","解说1_经义":"九五不是鼓励“好讼”，而是指当争端不可避免时，需要有中正、权威而可信的裁决中心。只有裁决者自身不偏，诉讼制度才可能真正止争。","解说2_时位":"从时位看，本爻处在上卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：訟元吉，以中正也。","象传译文":"《象传》说：“讼元吉”，是因为九五居中而正。","象传解说":"中正既是九五之吉的结构原因，也构成司法、公断的价值要求。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **64 未濟䷿**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"或錫之鞶帶，終朝三褫之。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 锡：赐予。鞶带：大带，象征荣宠。褫：剥夺。终朝：一早晨之间，极言时间短。","译文":"即使因争讼获得华美的赏赐，也可能在一个早晨之内被多次剥夺。","解说1_经义":"上九把讼推到极端：即使通过争夺暂时赢得名位，也缺乏稳定性。以诉讼、争胜作为主要上升手段，所得往往伴随更大的反噬。","解说2_时位":"从时位看，本爻处在全卦终位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：以訟受服，亦不足敬也。","象传译文":"《象传》说：因争讼而得到服饰荣宠，也不足以令人尊敬。","象传解说":"小象将“得”与“敬”分开：赢了争讼并不等于赢得正当性。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **47 困䷮**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"10 履䷉","二爻":"12 否䷋","三爻":"44 姤䷫","四爻":"59 渙䷺","五爻":"64 未濟䷿","上爻":"47 困䷮"}},{"卦序":7,"卦名":"師","卦符":"䷆","全名":"地水師","上卦":"坤","下卦":"坎","卦辞":"師，貞，丈人吉，無咎。","彖传":"《彖》曰：師，眾也；貞，正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下而民從之，吉又何咎矣。","大象":"《象》曰：地中有水，師。君子以容民畜眾。","互卦":"24 復䷗","错卦":"13 同人䷌","综卦":"08 比䷇","爻":[{"爻位":"初六","原文":"師出以律，否臧凶。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 律：纪律、法度。否臧：不善、不合规范；“否”读pǐ或fǒu历有讨论，此处意指不善。","译文":"军队出动必须有纪律；若纪律不良，便有凶险。","解说1_经义":"师卦首先不谈胜负，而谈“律”。集体行动越大，越不能只依赖个人勇气；明确规则、指挥体系与责任边界，是动众之前的第一条件。","解说2_时位":"从时位看，本爻处在全卦发端，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦坎（险、陷、流行、水）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：師出以律，失律凶也。","象传译文":"《象传》说：军队出征必须依律，失去纪律就会有凶险。","象传解说":"初六处行动起点，小象直接把失败原因归于“失律”，说明组织能力先于战术勇猛。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **19 臨䷒**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"在師中吉，無咎；王三錫命。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 在师中：处军中核心。王三锡命：君王屡次授命，表示信任与授权。","译文":"身处军中核心，吉而无咎；君王多次授予命令。","解说1_经义":"九二刚中，是师卦实际执行军事或大型组织任务的主帅位置。它既要有能力，又必须得到上级合法授权；个人英雄主义不足以统御众人。","解说2_时位":"从时位看，本爻处在下卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：在師中吉，承天寵也；王三錫命，懷萬邦也。","象传译文":"《象传》说：在军中居中而吉，是承受天子宠任；屡赐命令，是为了安怀万邦。","象传解说":"九二与六五相应，形成“君—将”关系。制度授权与专业执行相结合，是此爻的核心。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **02 坤䷁**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"師或輿尸，凶。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 舆尸：车载尸体，一说众人主事导致军队失序；传统多取败军载尸之象。","译文":"军队可能载尸而归，凶。","解说1_经义":"六三阴居阳位，又夹在军旅行动中，象征用人不当或指挥混乱。大规模行动若让不胜任者承担关键职责，后果往往不是小错而是系统性失败。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦坎（险、陷、流行、水）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：師或輿尸，大無功也。","象传译文":"《象传》说：“师或舆尸”，说明大事不能成功。","象传解说":"小象以“大无功”评价，强调这是领导与组织结构的问题，而不仅是一场偶然失利。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **46 升䷭**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"師左次，無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 左次：退驻、驻扎；古代尚右，左次多表示退守。","译文":"军队退驻待机，没有灾咎。","解说1_经义":"六四讲战略性退却。师卦并不把持续进攻视为唯一正确；遇到不利态势时保存力量、调整阵地，同样属于合格指挥。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：左次無咎，未失常也。","象传译文":"《象传》说：“左次无咎”，是因为没有违背正常的军事原则。","象传解说":"“未失常”说明退并不等于败。只要退得有序、目的清楚，就是合时的行动。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **40 解䷧**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"田有禽，利執言，無咎。長子帥師，弟子輿尸，貞凶。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 利：适宜、有利。 田有禽：田中有禽兽，比喻有明确可处理的对象。执言：据理声讨。长子：成熟负责的主帅。弟子：资历、能力不足者。","译文":"田中有害物，可以出师声讨，无咎；应由成熟的长者统军，若让不胜任者主事而载尸，虽守正也凶。","解说1_经义":"六五指出战争或强制行动必须有正当对象，同时“谁来执行”同样决定结果。目标正当并不能弥补用人错误。","解说2_时位":"从时位看，本爻处在上卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：長子帥師，以中行也；弟子輿尸，使不當也。","象传译文":"《象传》说：长子统军，是因为能依中道行事；弟子载尸，是任用不当。","象传解说":"小象把“中行”作为主帅标准。成熟不是年龄本身，而是能守中、承担后果。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **29 坎䷜**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"大君有命，開國承家，小人勿用。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 开国承家：分封有功者，使其建立诸侯国或家邑。小人勿用：有功不等于有德，不能因战功任用失德者治理。","译文":"大君颁布命令，论功封国授家；但不可任用小人。","解说1_经义":"师卦结束于战后秩序重建。胜利只是阶段结果，更难的是奖惩与任用：功劳应承认，治理权却不能只按战功分配。","解说2_时位":"从时位看，本爻处在全卦终位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大君有命，以正功也；小人勿用，必亂邦也。","象传译文":"《象传》说：大君有命，是为了端正地论定功劳；小人不可任用，否则必将扰乱邦国。","象传解说":"这条小象把军事伦理推进到政治伦理：战争后的制度安排决定胜利能否转化为长治。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **04 蒙䷃**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"19 臨䷒","二爻":"02 坤䷁","三爻":"46 升䷭","四爻":"40 解䷧","五爻":"29 坎䷜","上爻":"04 蒙䷃"}},{"卦序":8,"卦名":"比","卦符":"䷇","全名":"水地比","上卦":"坎","下卦":"坤","卦辞":"比，吉。原筮元永貞，無咎。不寧方來，後夫凶。","彖传":"《彖》曰：比，吉也；比，輔也，下順從也。原筮元永貞，無咎，以剛中也。不寧方來，上下應也。後夫凶，其道窮也。","大象":"《象》曰：地上有水，比。先王以建萬國，親諸侯。","互卦":"23 剝䷖","错卦":"14 大有䷍","综卦":"07 師䷆","爻":[{"爻位":"初六","原文":"有孚比之，無咎。有孚盈缶，終來有它，吉。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 吉：吉利；在占辞中表示趋向有利。 孚：诚信、信实，也有取得信任之义。 比：亲比、亲附。盈缶：诚信充满朴素容器，强调质朴而真实。","译文":"以诚信与人亲比，没有灾咎；诚信充盈如满缶，最终还会有意外的吉庆。","解说1_经义":"初六说明建立关系的第一资本是可信，而不是技巧。处比卦之初，越质朴、越可验证的诚意，越容易形成长期合作。","解说2_时位":"从时位看，本爻处在全卦发端，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：比之初六，有它吉也。","象传译文":"《象传》说：初六以诚信亲比，所以还会有额外的吉。","象传解说":"“有它吉”表示诚信的收益常超出最初预期。关系网络从可靠的最小单元开始扩展。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **03 屯䷂**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"比之自內，貞吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 自内：从内心、从内部关系出发。六二柔居阴位且得中，并与九五相应。","译文":"从内在真诚出发去亲比，守正则吉。","解说1_经义":"六二强调亲附不能只为外在利益。若自身立场端正、内在认同真实，再与九五形成回应，关系才有稳定基础。","解说2_时位":"从时位看，本爻处在下卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：比之自內，不自失也。","象传译文":"《象传》说：“比之自内”，是不使自己失去本心。","象传解说":"“不自失”是比卦重要界限：亲近别人不能以丢失自我原则为代价。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **29 坎䷜**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"比之匪人。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 匪人：不合正道之人、并非适当的亲比对象。","译文":"与不适当的人亲比。","解说1_经义":"六三没有给出“吉凶”二字，语气本身已带明显警戒。比重在选择关系对象；一旦把信任放错地方，亲密反而放大风险。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：比之匪人，不亦傷乎。","象传译文":"《象传》说：与非其人亲比，岂不可伤！","象传解说":"小象用反问加强警告。关系的价值首先取决于对象是否值得，而不是亲密程度本身。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **39 蹇䷦**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"外比之，貞吉。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 外比：向外亲近、亲附贤者。六四与九五相邻而承刚。","译文":"向外亲近贤者，守正则吉。","解说1_经义":"六四从内部关系走向公共关系。关键不是攀附权势，而是在守正前提下选择值得追随的对象。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦坎（险、陷、流行、水）的上卦之始、进入外部阶段位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：外比于賢，以從上也。","象传译文":"《象传》说：向外亲比贤者，是为了顺从上方的正道。","象传解说":"“从上”在这里以“贤”为前提。亲附如果失去正当性，就会从比变为依附。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **45 萃䷬**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"顯比，王用三驅，失前禽，邑人不誡，吉。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 显比：光明正大的亲比。三驱：古代田猎三面驱赶、留一面使禽可逃，象征取舍有度。失前禽：不追杀前方逃禽。不诫：不惊惧。","译文":"以光明方式亲比；君王田猎三驱，任前禽逃去，邑人也不必戒惧，吉。","解说1_经义":"九五中正，是比卦核心。好的凝聚不是全面控制，而是给人选择和退出空间；正因为不强迫，人们反而更愿意归附。","解说2_时位":"从时位看，本爻处在上卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：顯比之吉，位正中也；舍逆取順，失前禽也；邑人不誡，上使中也。","象传译文":"《象传》说：显比之吉，在于位置中正；舍逆取顺而不穷追前禽；邑人不戒，是上位者使中道得行。","象传解说":"此爻把领导力表现为“开放而有原则”。越需要凝聚众人，越不能依赖强制。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **02 坤䷁**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"比之無首，凶。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 无首：没有良好开端、没有可以归附的首领或原则。","译文":"亲比却没有一个好的开端或核心，凶。","解说1_经义":"上六处比之终，如果关系从一开始就没有原则、中心与信任基础，越到后期越难补救。组织、合作、亲密关系都需要明确的起点。","解说2_时位":"从时位看，本爻处在全卦终位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦坎（险、陷、流行、水）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：比之無首，無所終也。","象传译文":"《象传》说：“比之无首”，是因为没有好的终结。","象传解说":"小象把“首”与“终”相连：开端失序往往决定结局难成，这与《易》重视始终之变相一致。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **20 觀䷓**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"03 屯䷂","二爻":"29 坎䷜","三爻":"39 蹇䷦","四爻":"45 萃䷬","五爻":"02 坤䷁","上爻":"20 觀䷓"}},{"卦序":9,"卦名":"小畜","卦符":"䷈","全名":"風天小畜","上卦":"巽","下卦":"乾","卦辞":"小畜，亨。密雲不雨，自我西郊。","彖传":"《彖》曰：小畜，柔得位而上下應之，曰小畜。健而巽，剛中而志行，乃亨。密雲不雨，尚往也；自我西郊，施未行也。","大象":"《象》曰：風行天上，小畜。君子以懿文德。","互卦":"38 睽䷥","错卦":"16 豫䷏","综卦":"10 履䷉","爻":[{"爻位":"初九","原文":"復自道，何其咎？吉。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 复自道：返回自己的正道。何其咎：哪会有灾咎。初九阳居阳位，与六四相应。","译文":"回到自身应走的正道，哪里会有灾咎？吉。","解说1_经义":"小畜的力量尚小，初九不宜被外在牵制带偏。最稳妥的做法是回到自身可持续的节奏与原则。这里的“复”不是退缩，而是校正方向。","解说2_时位":"从时位看，本爻处在全卦发端，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：復自道，其義吉也。","象传译文":"《象传》说：返回自己的正道，其义当然是吉。","象传解说":"“其义吉”说明吉来自方向正确，而非偶然好运。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **57 巽䷸**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"牽復，吉。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 牵复：被牵引而返回，也有相互牵连、共同回归正道之意。九二居中。","译文":"受到牵引而回到正道，吉。","解说1_经义":"九二得中，能在关系和环境的牵引下及时回归适度。与初九相比，它强调不是孤立自守，而是在互动中被正确力量带回。","解说2_时位":"从时位看，本爻处在下卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：牽復在中，亦不自失也。","象传译文":"《象传》说：被牵引而复位，因居中而没有失去自己。","象传解说":"小象以“不自失”说明：顺势不等于失去主体，关键是仍守中。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **37 家人䷤**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"輿說輻，夫妻反目。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 说，通“脱”。辐，一作“輹”，车轴与车身关联部件。夫妻反目：关系失和。","译文":"车轮的构件脱落，夫妻彼此反目。","解说1_经义":"九三刚而过进，处小畜受制之时，却不愿受柔力节制，结果首先表现为行动工具失效，其次是亲密关系冲突。能力强而不受约束，反会破坏合作。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：夫妻反目，不能正室也。","象传译文":"《象传》说：夫妻反目，是因为不能端正家庭内部的秩序。","象传解说":"小象把外在故障转入关系秩序理解，说明“不受畜”不仅影响行动，也影响相处。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **61 中孚䷼**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"有孚，血去惕出，無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 孚：诚信、信实，也有取得信任之义。 血去：伤害消除，一说“恤去”，忧惧消除。惕出：戒惧解除。有孚：以诚信相交。","译文":"有诚信，伤害和忧惧得以消除，没有灾咎。","解说1_经义":"六四是全卦唯一阴爻，也是“小畜”能够蓄止群阳的关键。它不靠强力压制，而靠可信关系化解冲突；柔而有孚，能让本来对立的力量合作。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：有孚惕出，上合志也。","象传译文":"《象传》说：有诚信而忧惧消除，是因为与上方志向相合。","象传解说":"“上合志”说明六四的效力来自关系协调，而非单独权力。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **01 乾䷀**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"有孚攣如，富以其鄰。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 孚：诚信、信实，也有取得信任之义。 攣如：紧密相连。富以其邻：自身富足并与邻近者共享、相互成就。","译文":"诚信把彼此紧密联结，能够与邻者共同富足。","解说1_经义":"九五居中居尊，以诚信凝聚周边。小畜的“蓄”到这里由限制转成资源整合：真正可持续的积累不是独占，而是形成相互信任的网络。","解说2_时位":"从时位看，本爻处在上卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：有孚攣如，不獨富也。","象传译文":"《象传》说：诚信相连，是因为不独自占有富足。","象传解说":"小象把“不独富”作为领导伦理：资源越多，越要通过共享巩固关系。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **26 大畜䷙**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"既雨既處，尚德載，婦貞厲。月幾望，君子征凶。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 凶：凶险、不利。 征：前往、出行、采取进取行动。 既雨既处：云雨已降、蓄积已成。尚德载：重视德的积累承载。月几望：月将满。征凶：继续冒进则凶。","译文":"雨已降下，蓄积已成；应尊重长期积累。妇人守正虽有危险；月近满时，君子若继续进取则凶。","解说1_经义":"上九表示小畜已经到“蓄成”的临界点。此时继续扩张会把完成推向过满。月将望而未全满，是最典型的“将盈当戒”之象。","解说2_时位":"从时位看，本爻处在全卦终位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：既雨既處，德積載也；君子征凶，有所疑也。","象传译文":"《象传》说：既雨既处，是德的积累已经能够承载；君子继续出征之所以凶，是因为形势已有可疑之处。","象传解说":"“有所疑”提醒：达到阶段目标后要重新评估，而不能沿用此前的进取惯性。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **05 需䷄**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"57 巽䷸","二爻":"37 家人䷤","三爻":"61 中孚䷼","四爻":"01 乾䷀","五爻":"26 大畜䷙","上爻":"05 需䷄"}},{"卦序":10,"卦名":"履","卦符":"䷉","全名":"天澤履","上卦":"乾","下卦":"兌","卦辞":"履，履虎尾，不咥人，亨。","彖传":"《彖》曰：履，柔履剛也。說而應乎乾，是以履虎尾，不咥人，亨。剛中正，履帝位而不疚，光明也。","大象":"《象》曰：上天下澤，履。君子以辨上下，定民志。","互卦":"37 家人䷤","错卦":"15 謙䷎","综卦":"09 小畜䷈","爻":[{"爻位":"初九","原文":"素履往，無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 素履：以朴素、本分的方式践履。往：前行。","译文":"按照朴素本分的方式前行，没有灾咎。","解说1_经义":"履卦处处讲在危险秩序中如何行走。初九刚开始行动，越少虚饰、越按本分做事，越不容易踩到边界。","解说2_时位":"从时位看，本爻处在全卦发端，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦兌（说悦、交流、泽）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：素履之往，獨行願也。","象传译文":"《象传》说：素履而往，是独自行其所愿。","象传解说":"这里的“独行愿”不是任性，而是不借外饰、按内在正当愿望行事。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **06 訟䷅**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"履道坦坦，幽人貞吉。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 坦坦：平坦宽广。幽人：安静自守、不竞逐者。","译文":"所行之道平坦宽广，幽静自守的人守正则吉。","解说1_经义":"九二得中，履道而不躁。越是在讲规则和风险的履卦里，心态平和、不争显露，越能走得稳定。","解说2_时位":"从时位看，本爻处在下卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦兌（说悦、交流、泽）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：幽人貞吉，中不自亂也。","象传译文":"《象传》说：幽人守正而吉，是因为居中而内心不乱。","象传解说":"“中不自乱”把外在坦途与内在稳定联系起来。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **25 無妄䷘**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"眇能視，跛能履，履虎尾，咥人，凶。武人為于大君。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 眇：一目失明。跛：腿脚不便。咥：咬。武人为于大君：能力不足却强行居大位。","译文":"一只眼却自以为能看，跛脚却自以为能走；踩到虎尾而被咬，凶。像武人强行担当君位。","解说1_经义":"六三的核心是“能力与自我判断不匹配”。弱而居刚位，又想以强势方式行动，危险不在老虎本身，而在误判自己的能力。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：眇能視，不足以有明也；跛能履，不足以與行也；咥人之凶，位不當也；武人為于大君，志剛也。","象传译文":"《象传》说：眇不足以明视，跛不足以行走；被虎咬是因为位置不当；武人想做大君，是志向过刚。","象传解说":"小象把身体缺陷比喻为认知和行动能力不足，警戒“志大才疏”。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **01 乾䷀**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"履虎尾，愬愬，終吉。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 愬愬：恐惧谨慎貌。履虎尾：贴近危险。","译文":"踩到虎尾而战战兢兢，最终吉。","解说1_经义":"九四仍在危险边缘，但与六三不同，它知道害怕。风险意识使强势行动变得可控；能敬畏边界，反而可安全通过。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：愬愬終吉，志行也。","象传译文":"《象传》说：愬愬而终吉，是因为其志最终能够实行。","象传解说":"小象认可的不是恐惧本身，而是把恐惧转化为谨慎，从而完成目标。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **61 中孚䷼**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"夬履，貞厲。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 夬履：决然、刚决地践履。贞厉：即使守正仍有危险。","译文":"刚决地执行自己的道路，守正仍有危险。","解说1_经义":"九五中正而居尊，本来位置极佳，但履卦提醒：权力越大，决断越容易变成刚愎。即便目标正确，也要防止执行方式过强。","解说2_时位":"从时位看，本爻处在上卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：夬履貞厲，位正當也。","象传译文":"《象传》说：夬履守正而有危险，是因为正处在决定性的位置。","象传解说":"“位正当”并不自动消除风险，反而意味着决策后果更大。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **38 睽䷥**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"視履考祥，其旋元吉。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 视履：回看自己的践履。考祥：考察吉凶征兆。旋：周旋一周、善终。","译文":"回顾自己一路的行为，考察其结果；如果循环圆满，则大吉。","解说1_经义":"上九把履卦从“怎么走”提升为“如何复盘”。一个阶段结束时，最重要的是检视整个行动链，而不是只看最后一次得失。","解说2_时位":"从时位看，本爻处在全卦终位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：元吉在上，大有慶也。","象传译文":"《象传》说：元吉出现在最上位，是因为有大的庆成。","象传解说":"终点的吉来自全过程经得起回看。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **58 兌䷹**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"06 訟䷅","二爻":"25 無妄䷘","三爻":"01 乾䷀","四爻":"61 中孚䷼","五爻":"38 睽䷥","上爻":"58 兌䷹"}},{"卦序":11,"卦名":"泰","卦符":"䷊","全名":"地天泰","上卦":"坤","下卦":"乾","卦辞":"泰，小往大來，吉亨。","彖传":"《彖》曰：泰，小往大來，吉亨。則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人；君子道長，小人道消也。","大象":"《象》曰：天地交，泰。后以財成天地之道，輔相天地之宜，以左右民。","互卦":"54 歸妹䷵","错卦":"12 否䷋","综卦":"12 否䷋","爻":[{"爻位":"初九","原文":"拔茅茹，以其彙，征吉。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 征：前往、出行、采取进取行动。 拔茅茹：拔茅草而根系相连。彙：同类。","译文":"拔起茅草而根根相连，与同类一起前进，吉。","解说1_经义":"泰卦天地交，初九表现为同道相引。个人行动不再是孤立突破，而是带动同类共同上升。","解说2_时位":"从时位看，本爻处在全卦发端，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：拔茅征吉，志在外也。","象传译文":"《象传》说：拔茅而征吉，是志向在外、准备有所作为。","象传解说":"“志在外”说明泰时适宜走出封闭，形成协同行动。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **46 升䷭**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"包荒，用馮河，不遐遺，朋亡，得尚于中行。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 包荒：包容荒远。馮河：徒步渡河，喻勇毅。不遐遗：不遗弃远者。朋亡：不结党偏私。中行：行中道。","译文":"能包容荒远，敢于涉险，不遗弃远方的人，也不因朋党而偏私，因而得到中道的尊崇。","解说1_经义":"九二是泰卦治理核心：开放、勇毅、无遗、无党。真正的通泰不是只让熟人获益，而是扩大包容半径，同时保持决断力。","解说2_时位":"从时位看，本爻处在下卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：包荒，得尚于中行，以光大也。","象传译文":"《象传》说：包荒而得尚于中行，是因为德量光大。","象传解说":"小象把九二归于“光大”，强调中道不是折中，而是容量大、视野宽。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **36 明夷䷣**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"無平不陂，無往不復，艱貞無咎。勿恤其孚，于食有福。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 孚：诚信、信实，也有取得信任之义。 陂：倾斜。无往不复：没有只去不返的趋势。恤：忧虑。孚：规律可信。","译文":"没有永远平坦而不倾斜的，也没有只去不回的；在艰难中守正可无咎。不必忧虑规律失信，仍可享有福分。","解说1_经义":"泰至九三已到内卦终点，开始出现由盛转衰的可能。爻辞的重点是接受周期性：通泰不是永久状态，提前在顺境中准备逆转，才是“艰贞无咎”。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：無往不復，天地際也。","象传译文":"《象传》说：“无往不复”，是因为已经到了天地交接的边际。","象传解说":"小象把转折归于“际”，说明任何稳定格局都有边界。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **19 臨䷒**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"翩翩不富，以其鄰，不戒以孚。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 孚：诚信、信实，也有取得信任之义。 翩翩：轻快相从。不富以其邻：不是依靠财富，而是与邻相从。不戒以孚：不待告诫即相互信任。","译文":"轻快地与邻近者相从，不靠财富笼络，也不需戒令便彼此诚信。","解说1_经义":"六四进入上卦坤，泰的交流由下而上继续。理想关系不是利益收买，而是共同秩序建立后的自发合作。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：翩翩不富，皆失實也；不戒以孚，中心願也。","象传译文":"《象传》说：翩翩不富，是都不把实利作为唯一基础；不戒以孚，是内心共同愿意。","象传解说":"“中心愿”比强制命令更能维持泰。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **34 大壯䷡**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"帝乙歸妹，以祉元吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 帝乙归妹：古代王室嫁女典故。祉：福。","译文":"帝乙嫁女，以此得福，大吉。","解说1_经义":"六五以尊位而能下嫁、联结，象征上位者以谦柔建立上下交往。泰的极佳状态来自身份差异不阻断真实联系。","解说2_时位":"从时位看，本爻处在上卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：以祉元吉，中以行願也。","象传译文":"《象传》说：因婚姻而得福、元吉，是居中而实现了自己的愿望。","象传解说":"“中以行愿”说明柔中而联结，是六五之吉的核心。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **05 需䷄**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"城復于隍，勿用師。自邑告命，貞吝。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 隍：城壕。城复于隍：城墙崩回壕沟，象征秩序解体。自邑告命：只能从本邑发布命令。","译文":"城墙倒回城壕，不宜用兵；只能在自己的城邑发布命令，守正亦有遗憾。","解说1_经义":"上六是泰极转否。宏大秩序已经开始坍塌，此时靠武力恢复旧有规模往往适得其反，应收缩范围、保住核心。","解说2_时位":"从时位看，本爻处在全卦终位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：城復于隍，其命亂也。","象传译文":"《象传》说：城复于隍，是因为政令已经混乱。","象传解说":"小象把外在崩塌归因于内部命令失序，说明结构性问题不能只靠强攻解决。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **26 大畜䷙**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"46 升䷭","二爻":"36 明夷䷣","三爻":"19 臨䷒","四爻":"34 大壯䷡","五爻":"05 需䷄","上爻":"26 大畜䷙"}},{"卦序":12,"卦名":"否","卦符":"䷋","全名":"天地否","上卦":"乾","下卦":"坤","卦辞":"否，否之匪人，不利君子貞，大往小來。","彖传":"《彖》曰：否之匪人，不利君子貞，大往小來。則是天地不交而萬物不通也，上下不交而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子；小人道長，君子道消也。","大象":"《象》曰：天地不交，否。君子以儉德辟難，不可榮以祿。","互卦":"53 漸䷴","错卦":"11 泰䷊","综卦":"11 泰䷊","爻":[{"爻位":"初六","原文":"拔茅茹，以其彙，貞吉亨。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 亨：通达、顺畅；古义又与享献相关。 拔茅茹、以其彙：同类相连。否时阴气在内增长。","译文":"拔起茅草而根系相连；与同类守正，则吉而亨。","解说1_经义":"否卦虽闭塞，但初六提示：困难中仍可通过正当同伴关系保存力量。此时不宜贸然争夺外部位置，先把内部同道组织好。","解说2_时位":"从时位看，本爻处在全卦发端，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：拔茅貞吉，志在君也。","象传译文":"《象传》说：拔茅而守正吉，是志向仍在君道。","象传解说":"“志在君”说明退处不是放弃正道。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **25 無妄䷘**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"包承，小人吉，大人否亨。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 大人：有德有位、有能力担当大事之人；不宜简单等同现代某一具体身份。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 吉：吉利；在占辞中表示趋向有利。 亨：通达、顺畅；古义又与享献相关。 包承：包容承受、顺承。大人否亨：大人在否塞中守道反能亨。","译文":"能够包容承受，小人因此得利；大人则安守否塞而保持亨通。","解说1_经义":"六二指出同一种“顺承”对不同人格有不同结果。小人可能借顺承求利，大人则不与闭塞结构同流，而以内在正道保存自己。","解说2_时位":"从时位看，本爻处在下卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大人否亨，不亂群也。","象传译文":"《象传》说：大人在否塞中仍亨，是因为不与小人群体相乱。","象传解说":"“不乱群”突出界限感：闭塞时期最怕为了融入而失去原则。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **06 訟䷅**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"包羞。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 包羞：包藏羞耻、怀着不正而自取羞辱。","译文":"包藏着羞耻。","解说1_经义":"六三处内卦之极，否塞进一步加深。若继续依附不正结构，表面可能暂安，内里却积累羞耻与失正。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的下卦之终、内外转换前位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：包羞，位不當也。","象传译文":"《象传》说：“包羞”，是因为所处位置不当。","象传解说":"小象直接以“不当位”解释其尴尬，提醒角色与行为不相称。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **33 遯䷠**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"有命無咎，疇離祉。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有命：得到正当命令、天命。疇：同类。離：附丽。祉：福。","译文":"有所受命，便可无咎；同类也能依附而共享福祉。","解说1_经义":"九四是从否向泰转机的开始。刚爻进入上卦后，如果行动具有正当授权，就能把个人突破转成群体转机。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：有命無咎，志行也。","象传译文":"《象传》说：有命而无咎，是因为志向能够施行。","象传解说":"“志行”说明转否需要行动，但行动必须有正当性基础。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **20 觀䷓**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"休否，大人吉。其亡其亡，繫于苞桑。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 大人：有德有位、有能力担当大事之人；不宜简单等同现代某一具体身份。 吉：吉利；在占辞中表示趋向有利。 休否：停止、休息否塞。其亡其亡：时时警惕可能灭亡。苞桑：根深丛生的桑树，喻系固。","译文":"使否塞停止，大人吉；仍要不断提醒自己“会不会灭亡”，把根基系在牢固的桑丛上。","解说1_经义":"九五有能力扭转否局，但真正危险在“刚有好转就忘记危机”。爻辞要求在成功时保持失败意识，用制度和根基巩固转机。","解说2_时位":"从时位看，本爻处在上卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大人之吉，位正當也。","象传译文":"《象传》说：大人之吉，是因为位置中正。","象传解说":"中正让九五有能力休否，而“其亡其亡”则防止成功后的松懈。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **35 晉䷢**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"傾否，先否後喜。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 倾否：否塞倾覆。先否后喜：先闭塞，后来喜悦。","译文":"闭塞状态终于被倾覆，先经历否塞，后来转为喜悦。","解说1_经义":"上九到否之终，堵塞已走到极点，变化反而成为必然。这里的吉来自“旧结构无法继续维持”所释放的转机。","解说2_时位":"从时位看，本爻处在全卦终位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：否終則傾，何可長也。","象传译文":"《象传》说：否到了终点就会倾覆，怎么可能永久持续？","象传解说":"与泰上六相对，这里显示极坏状态也不会无限延续；关键是能否抓住转折。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **45 萃䷬**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"25 無妄䷘","二爻":"06 訟䷅","三爻":"33 遯䷠","四爻":"20 觀䷓","五爻":"35 晉䷢","上爻":"45 萃䷬"}},{"卦序":13,"卦名":"同人","卦符":"䷌","全名":"天火同人","上卦":"乾","下卦":"離","卦辞":"同人，同人于野，亨。利涉大川，利君子貞。","彖传":"《彖》曰：同人，柔得位得中而應乎乾，曰同人。同人于野，亨，利涉大川，乾行也。文明以健，中正而應，君子正也。唯君子為能通天下之志。","大象":"《象》曰：天與火，同人。君子以類族辨物。","互卦":"44 姤䷫","错卦":"07 師䷆","综卦":"14 大有䷍","爻":[{"爻位":"初九","原文":"同人于門，無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 门：家门、共同体入口。同人于门：在门口就能与人相同相合。","译文":"走出门户便与人和同，没有灾咎。","解说1_经义":"初九强调开放。真正的“同人”不是封闭小圈子，而是从一开始就把关系指向公共空间。","解说2_时位":"从时位看，本爻处在全卦发端，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦離（明、附丽、文明、火）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：出門同人，又誰咎也。","象传译文":"《象传》说：出门与人同，又有谁会责咎呢？","象传解说":"“出门”是从私域走向公共合作的第一步。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **33 遯䷠**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"同人于宗，吝。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 宗：宗族、宗派。于宗：只在本宗内部求同。","译文":"只在宗族或小圈子中求同，有遗憾。","解说1_经义":"六二虽与九五相应，但如果把“同”缩小为血缘、派系或熟人网络，就违背“同人于野”的开放精神。","解说2_时位":"从时位看，本爻处在下卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的内卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：同人于宗，吝道也。","象传译文":"《象传》说：同人于宗，是走向吝狭的道路。","象传解说":"小象反对把共同体变成排他圈层。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **01 乾䷀**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"伏戎于莽，升其高陵，三歲不興。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 伏戎于莽：把武装埋伏在草莽。升高陵：登高窥伺。三岁不兴：长期不能发动。","译文":"把兵戎埋伏在草丛，又登高窥伺，三年也不敢发动。","解说1_经义":"九三想求同却以敌对、猜疑方式对待他人，结果形成长期对峙。合作关系若以防范为起点，越准备越难真正行动。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦離（明、附丽、文明、火）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：伏戎于莽，敵剛也；三歲不興，安行也。","象传译文":"《象传》说：伏戎于莽，是因为遇到同样刚强的对手；三年不兴，是难以顺利行动。","象传解说":"小象指出“敌刚”导致僵局。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **25 無妄䷘**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"乘其墉，弗克攻，吉。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 墉：城墙。弗克攻：不能攻下。","译文":"登上城墙，却没有继续进攻，吉。","解说1_经义":"九四虽有冲突条件，却在临界点选择不攻。能够放弃不正当的胜利欲，是同人卦的重要转折。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：乘其墉，義弗克也；其吉，則困而反則也。","象传译文":"《象传》说：乘墉而不攻，是因为道义上本就不应攻；能困而反则，所以吉。","象传解说":"“反则”即回到规则。停止错误行动本身就是进步。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **37 家人䷤**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"同人，先號咷而後笑，大師克相遇。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 號咷：大哭。大師：大军。克相遇：终于能够相会。","译文":"同人先哭号，后来欢笑；经历强大阻隔后终于相遇。","解说1_经义":"九五与六二正应，但中间有阻隔，说明真正重要的合作未必一开始顺利。只要目标与诚信成立，穿过冲突后仍能会合。","解说2_时位":"从时位看，本爻处在上卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：同人之先，以中直也；大師相遇，言相克也。","象传译文":"《象传》说：先哭号，是因内心中直；大军相遇，是克服阻隔后终于相会。","象传解说":"小象承认合作成本，却强调中直可维持方向。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **30 離䷝**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"同人于郊，無悔。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔：悔恨，亦指可由反省而改的失误。 郊：城外近郊，比“野”仍稍有距离。无悔：没有悔恨。","译文":"在郊外与人和同，没有悔恨。","解说1_经义":"上九的同人已经远离核心冲突，也因此较少风险，但其公共性仍不及“于野”。这是较为超脱、有限度的和同。","解说2_时位":"从时位看，本爻处在全卦终位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：同人于郊，志未得也。","象传译文":"《象传》说：同人于郊，说明志愿还没有完全实现。","象传解说":"无悔不等于最理想；小象提醒“未得志”，体现《易》判断的层次性。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **49 革䷰**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"33 遯䷠","二爻":"01 乾䷀","三爻":"25 無妄䷘","四爻":"37 家人䷤","五爻":"30 離䷝","上爻":"49 革䷰"}},{"卦序":14,"卦名":"大有","卦符":"䷍","全名":"火天大有","上卦":"離","下卦":"乾","卦辞":"大有，元亨。","彖传":"《彖》曰：大有，柔得尊位大中而上下應之，曰大有。其德剛健而文明，應乎天而時行，是以元亨。","大象":"《象》曰：火在天上，大有。君子以遏惡揚善，順天休命。","互卦":"43 夬䷪","错卦":"08 比䷇","综卦":"13 同人䷌","爻":[{"爻位":"初九","原文":"無交害，匪咎，艱則無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 无交害：尚未与害相交。一说“不与害相交”。艰：以艰难心态谨慎。","译文":"不要与有害因素相交，本无灾咎；能够以艰难心态谨慎处事，就更无咎。","解说1_经义":"大有之初最怕因资源骤增而轻率扩张。初九要求先建立风险边界，不因“有”而忘记“害”。","解说2_时位":"从时位看，本爻处在全卦发端，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大有初九，無交害也。","象传译文":"《象传》说：大有初九尚未与害相交。","象传解说":"小象强调风险尚未形成，正因如此更适合预防。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **50 鼎䷱**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"大車以載，有攸往，無咎。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有攸往：有所前往、有所作为。 往：前往、向外发展。 大车以载：大车装载重物，喻有能力承载财富与责任。","译文":"用大车承载，适宜有所前往，没有灾咎。","解说1_经义":"九二得中，表示资源与承载能力匹配。大有真正的吉，不在“拥有很多”，而在有系统、有能力把资源运转起来。","解说2_时位":"从时位看，本爻处在下卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大車以載，積中不敗也。","象传译文":"《象传》说：大车能够装载，是因为积聚于中而不会败坏。","象传解说":"“积中不败”可理解为容量与稳定性兼具。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **30 離䷝**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"公用亨于天子，小人弗克。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 亨：通达、顺畅；古义又与享献相关。 公用亨于天子：公侯向天子献享。小人弗克：小人承担不起。","译文":"公侯可以向天子献享；若是小人则不能胜任。","解说1_经义":"九三处大有中的高资源、高责任位置。资源越大，对人格与公共责任要求越高；若只以私利心态使用大资源，反而会受害。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：公用亨于天子，小人害也。","象传译文":"《象传》说：公侯献享于天子，小人处此反会受害。","象传解说":"小象把“有”与“德”绑定：承载层级必须与德性相称。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **38 睽䷥**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"匪其彭，無咎。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 彭：盛大、隆盛。匪其彭：不以盛大自居。","译文":"不炫耀自己的盛大富有，没有灾咎。","解说1_经义":"九四接近尊位，最容易因资源、功绩而形成威胁。主动减弱夸张展示，能降低嫉妒和政治风险。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦離（明、附丽、文明、火）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：匪其彭無咎，明辨晢也。","象传译文":"《象传》说：不以盛大自居而无咎，是因为能够明辨事理。","象传解说":"“明辨”意味着懂得何时应该收敛。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **26 大畜䷙**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"厥孚交如，威如，吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 孚：诚信、信实，也有取得信任之义。 厥孚交如：诚信相交。威如：有威仪。","译文":"以诚信相交，同时保持应有威严，吉。","解说1_经义":"六五柔居尊位，领导方式若只有亲和可能失去边界，只有威严又会失去信任。此爻强调“孚”与“威”并用。","解说2_时位":"从时位看，本爻处在上卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的上卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：厥孚交如，信以發志也；威如之吉，易而無備也。","象传译文":"《象传》说：诚信相交，是以信发志；威严而吉，是因平易却不失防范。","象传解说":"柔中领导的关键，是亲而有度。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **01 乾䷀**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"自天祐之，吉無不利。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 祐：助佑。自天祐之：得到天道助成。","译文":"得到上天助佑，吉而无所不利。","解说1_经义":"上九把大有的完成归于顺天与德行，而不是单凭个人占有。资源使用若合于正道，最终形成的支持会超越个人控制。","解说2_时位":"从时位看，本爻处在全卦终位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦離（明、附丽、文明、火）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大有上吉，自天祐也。","象传译文":"《象传》说：大有上爻之吉，是得到天的助佑。","象传解说":"“天祐”可理解为合乎大势与正当性的结果，不宜机械解释为神秘保证。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **34 大壯䷡**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"50 鼎䷱","二爻":"30 離䷝","三爻":"38 睽䷥","四爻":"26 大畜䷙","五爻":"01 乾䷀","上爻":"34 大壯䷡"}},{"卦序":15,"卦名":"謙","卦符":"䷎","全名":"地山謙","上卦":"坤","下卦":"艮","卦辞":"謙，亨，君子有終。","彖传":"《彖》曰：謙，亨。天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可踰，君子之終也。","大象":"《象》曰：地中有山，謙。君子以裒多益寡，稱物平施。","互卦":"40 解䷧","错卦":"10 履䷉","综卦":"16 豫䷏","爻":[{"爻位":"初六","原文":"謙謙君子，用涉大川，吉。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 吉：吉利；在占辞中表示趋向有利。 謙謙：谦而又谦。用涉大川：可以承担重大风险。","译文":"谦而又谦的君子，可以渡越大川，吉。","解说1_经义":"初六位置最低，谦德与其位相合。真正的谦不是自我贬低，而是在高风险行动前降低自满、充分准备，所以反而能做大事。","解说2_时位":"从时位看，本爻处在全卦发端，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦艮（止、界限、山）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：謙謙君子，卑以自牧也。","象传译文":"《象传》说：谦谦君子，是以卑下姿态自我修养。","象传解说":"“自牧”即自我涵养。谦首先是一种自我管理技术。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **36 明夷䷣**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"鳴謙，貞吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 鸣谦：谦德有声名、被他人感知。","译文":"谦德发而有声，守正则吉。","解说1_经义":"六二得中，谦不再只是内在态度，而成为别人可感知的稳定品格。声誉来自长期行为，而非自我宣传。","解说2_时位":"从时位看，本爻处在下卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦艮（止、界限、山）的内卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：鳴謙貞吉，中心得也。","象传译文":"《象传》说：鸣谦而贞吉，是因为内心得其正。","象传解说":"“中心得”把外在名声归因于内在真实。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **46 升䷭**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"勞謙君子，有終吉。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 吉：吉利；在占辞中表示趋向有利。 劳谦：有功劳而仍谦。九三为全卦唯一阳爻。","译文":"有劳有功而仍谦的君子，能够有好结果，吉。","解说1_经义":"九三最有能力、也最容易自恃。此爻把“功劳”与“谦”并列，说明真正难的不是无功时谦，而是有功之后仍不居功。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦艮（止、界限、山）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：勞謙君子，萬民服也。","象传译文":"《象传》说：劳谦君子，万民都会服从。","象传解说":"服众不是靠压制，而是功而不伐形成的信任。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **02 坤䷁**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"無不利，撝謙。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 撝：施行、发挥，也有谦抑之意。","译文":"发挥谦德，无所不利。","解说1_经义":"六四已经进入上卦，不能只“心里谦”，而要把谦落实到权力、资源和行为方式上。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：無不利撝謙，不違則也。","象传译文":"《象传》说：发挥谦德无不利，因为不违背应有法则。","象传解说":"谦必须有原则；不是无条件退让，而是不过度占位。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **62 小過䷽**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"不富，以其鄰，利用侵伐，無不利。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 不富以其邻：不以财富笼络邻者。侵伐：征讨不服从正道者。","译文":"不用财富也能得到邻人的支持；适宜征讨不服者，无所不利。","解说1_经义":"六五说明谦并非软弱。尊位者平时谦下，遇到必须维护秩序的情形仍可果断行动。谦与威并不矛盾。","解说2_时位":"从时位看，本爻处在上卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：利用侵伐，征不服也。","象传译文":"《象传》说：适宜侵伐，是征讨不服从正当秩序者。","象传解说":"小象强调行动对象的正当性，避免把“谦”误解为不能使用力量。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **39 蹇䷦**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"鳴謙，利用行師，征邑國。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 征：前往、出行、采取进取行动。 鸣谦：谦德声闻于外。行师、征邑国：动用力量整顿自身范围。","译文":"谦德声闻于外；适宜用兵，但主要用于整顿自己的邑国。","解说1_经义":"上六谦已至极，却仍有内部秩序需处理。越强调谦和，越不能回避内部责任；力量应先用于自我整顿，而非扩张。","解说2_时位":"从时位看，本爻处在全卦终位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：鳴謙，志未得也；可用行師，征邑國也。","象传译文":"《象传》说：鸣谦说明志愿尚未完全实现；可用兵，是为了治理自己的邑国。","象传解说":"谦卦以“先自治”收尾：外在谦名不能代替内部治理。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **52 艮䷳**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"36 明夷䷣","二爻":"46 升䷭","三爻":"02 坤䷁","四爻":"62 小過䷽","五爻":"39 蹇䷦","上爻":"52 艮䷳"}},{"卦序":16,"卦名":"豫","卦符":"䷏","全名":"雷地豫","上卦":"震","下卦":"坤","卦辞":"豫，利建侯行師。","彖传":"《彖》曰：豫，剛應而志行，順以動，豫。豫順以動，故天地如之，而況建侯行師乎？天地以順動，故日月不過而四時不忒；聖人以順動，則刑罰清而民服。豫之時義大矣哉。","大象":"《象》曰：雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。","互卦":"39 蹇䷦","错卦":"09 小畜䷈","综卦":"15 謙䷎","爻":[{"爻位":"初六","原文":"鳴豫，凶。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 鸣豫：把欢乐、得意显露出来。","译文":"一开始就张扬享乐与得意，凶。","解说1_经义":"豫是和乐，但初六处最下而与九四相应，容易因得到依靠而过早自满。乐若失去节制，就从鼓舞变成放纵。","解说2_时位":"从时位看，本爻处在全卦发端，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：初六鳴豫，志窮凶也。","象传译文":"《象传》说：初六鸣豫，是志向已经走到穷处，所以凶。","象传解说":"问题不在快乐，而在以快乐替代成长。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **51 震䷲**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"介于石，不終日，貞吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 介于石：坚定如石。 不终日：不等到一天结束就能觉察。","译文":"操守坚定如石，不必等到整日便能识别变化；守正则吉。","解说1_经义":"六二得中，能在欢乐环境里保持敏感，不被情绪拖走。它代表一种迅速察觉“乐是否过度”的能力。","解说2_时位":"从时位看，本爻处在下卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不終日貞吉，以中正也。","象传译文":"《象传》说：不待终日便守正而吉，是因为居中且正。","象传解说":"得中使六二成为豫卦的清醒点。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **40 解䷧**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"盱豫，悔。遲有悔。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔：悔恨，亦指可由反省而改的失误。 盱：仰视、讨好地看。盱豫：仰赖他人而求乐。迟：迟疑。","译文":"仰望别人以求安乐，会有悔；若迟疑不改，也会有悔。","解说1_经义":"六三把快乐的来源交给外部权势，导致依赖与患得患失。明知不妥却拖延改变，悔会加重。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的下卦之终、内外转换前位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：盱豫有悔，位不當也。","象传译文":"《象传》说：盱豫有悔，是因为位置不当。","象传解说":"结构上的不当位对应心理上的失去自主。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **62 小過䷽**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"由豫，大有得。勿疑，朋盍簪。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 由豫：由此而产生和乐。朋盍簪：朋友像簪子聚合，意为众人迅速聚集。","译文":"欢乐由此而生，会有很大所得；不要怀疑，朋友会聚集而来。","解说1_经义":"九四是豫卦唯一阳爻，成为全卦的发动中心。它能把个人热情转成群体动力，关键是自信而不疑。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：由豫大有得，志大行也。","象传译文":"《象传》说：由豫而大有得，是志向得到大行。","象传解说":"豫的正面力量在于激励与组织，而非单纯享乐。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **02 坤䷁**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"貞疾，恒不死。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 贞疾：长期有疾。恒不死：虽病而不至灭亡。","译文":"长期带着疾病，但始终不会死亡。","解说1_经义":"六五乘九四之刚，象征处尊位却被强势环境牵制。虽然状态不理想，但得中使其仍能维持。此爻更像“带病运行”，而非彻底失败。","解说2_时位":"从时位看，本爻处在上卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦震（动、发起、震动、雷）的上卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六五貞疾，乘剛也；恒不死，中未亡也。","象传译文":"《象传》说：六五长期有疾，是因为乘刚；始终不死，是因为中道尚未丧失。","象传解说":"小象清楚区分“有问题”和“系统崩溃”。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **45 萃䷬**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"冥豫，成有渝，無咎。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 冥豫：沉迷于乐而昏暗。成有渝：已经形成的状态若能改变。","译文":"沉迷欢乐而昏昧；但即使已经如此，只要能够改变，仍可无咎。","解说1_经义":"上六是豫乐过度，却给出重要出口：错误已经形成并不等于不可挽回，关键在“渝”——改变。","解说2_时位":"从时位看，本爻处在全卦终位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦震（动、发起、震动、雷）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：冥豫在上，何可長也。","象传译文":"《象传》说：冥豫居于最上，怎么能够长久？","象传解说":"极乐必变。小象用“何可长”推动从沉迷中醒来。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **35 晉䷢**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"51 震䷲","二爻":"40 解䷧","三爻":"62 小過䷽","四爻":"02 坤䷁","五爻":"45 萃䷬","上爻":"35 晉䷢"}},{"卦序":17,"卦名":"隨","卦符":"䷐","全名":"澤雷隨","上卦":"兌","下卦":"震","卦辞":"隨，元亨，利貞，無咎。","彖传":"《彖》曰：隨，剛來而下柔，動而說，隨。大亨貞，無咎，而天下隨時。隨之時義大矣哉。","大象":"《象》曰：澤中有雷，隨。君子以向晦入宴息。","互卦":"53 漸䷴","错卦":"18 蠱䷑","综卦":"18 蠱䷑","爻":[{"爻位":"初九","原文":"官有渝，貞吉。出門交有功。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 官：职守、常规身份。渝：改变。出门交：走出门外与人交往。","译文":"职守有所改变，守正则吉；走出门外与人交往，会有功效。","解说1_经义":"随卦初九说明“随”不是无原则跟从，而是因时调整角色后，仍守住正道。变化一旦发生，就应主动进入新的关系网络，而不是固守旧位置。","解说2_时位":"从时位看，本爻处在全卦发端，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦震（动、发起、震动、雷）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：官有渝，從正吉也；出門交有功，不失也。","象传译文":"《象传》说：职守有变而守正则吉；出门交往有功，是因为没有失去正道。","象传解说":"“不失”是此爻核心：变可以很大，但原则不能丢。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **45 萃䷬**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"系小子，失丈夫。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 系小子：牵系于年幼、次要者。失丈夫：因小失大。","译文":"牵系于小者，就会失去更成熟、更重要的对象。","解说1_经义":"六二讲选择性。随从关系不可能什么都抓住；若把精力投在次要目标上，就会错过真正重要的伙伴或机会。","解说2_时位":"从时位看，本爻处在下卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的内卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：系小子，弗兼與也。","象传译文":"《象传》说：牵系小子，是因为不能同时兼得。","象传解说":"小象点出资源有限，随必有取舍。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **58 兌䷹**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"系丈夫，失小子。隨有求得，利居貞。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 系丈夫：追随成熟者。失小子：放下次要者。有求得：有所求可以得到。","译文":"追随成熟可靠者，就会失去小者；如此有所求可得，宜守正。","解说1_经义":"六三与六二相反，强调放弃低层次依附，选择更高质量关系。所谓“得”，并非无条件获利，而是取舍后的结构优化。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦震（动、发起、震动、雷）的下卦之终、内外转换前位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：系丈夫，志舍下也。","象传译文":"《象传》说：系丈夫，是志向舍下而向上。","象传解说":"“舍下”说明成长常伴随主动放弃。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **49 革䷰**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"隨有獲，貞凶。有孚在道，以明，何咎？","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 凶：凶险、不利。 孚：诚信、信实，也有取得信任之义。 随有获：随从而有所得。贞凶：若执着所得反凶。有孚在道：诚信合道。","译文":"随从而有所收获；若执着守住所得反而有凶。若诚信在道、内心明白，则可无咎。","解说1_经义":"九四接近尊位，容易因追随带来的资源而形成私人势力。此爻警告：收获本身不是问题，问题在是否以正道透明地使用。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦兌（说悦、交流、泽）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：隨有獲，其義凶也；有孚在道，明功也。","象传译文":"《象传》说：随而有获，从义理看有凶险；有孚在道，是因为明而有功。","象传解说":"越靠近权力中心，越需要让忠诚与利益关系可被检验。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **03 屯䷂**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"孚于嘉，吉。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 孚：诚信、信实，也有取得信任之义。 嘉：善、美好。","译文":"诚信地追随美善，吉。","解说1_经义":"九五中正，随的最高原则被简化为一句：所随者必须“嘉”。判断对象正确，比盲目强调忠诚更重要。","解说2_时位":"从时位看，本爻处在上卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：孚于嘉吉，位正中也。","象传译文":"《象传》说：诚信于美善之所以吉，是因为位置中正。","象传解说":"中正让九五的随从不是趋附，而是价值选择。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **51 震䷲**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"拘系之，乃從維之。王用亨于西山。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 亨：通达、顺畅；古义又与享献相关。 拘系：紧密系住。维：进一步维系。王用亨于西山：王以此祭享西山。","译文":"先系住，再加以维系；王用此诚敬祭享西山。","解说1_经义":"上六描述随从关系已经极其牢固。走到全卦之终，关系从临时跟随提升为仪式化、共同信念式的联结。","解说2_时位":"从时位看，本爻处在全卦终位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦兌（说悦、交流、泽）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：拘系之，上窮也。","象传译文":"《象传》说：拘系而维之，是随道走到上穷之处。","象传解说":"极强联结既可能是忠诚，也可能是束缚；实占时要结合所问判断其性质。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **25 無妄䷘**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"45 萃䷬","二爻":"58 兌䷹","三爻":"49 革䷰","四爻":"03 屯䷂","五爻":"51 震䷲","上爻":"25 無妄䷘"}},{"卦序":18,"卦名":"蠱","卦符":"䷑","全名":"山風蠱","上卦":"艮","下卦":"巽","卦辞":"蠱，元亨，利涉大川。先甲三日，後甲三日。","彖传":"《彖》曰：蠱，剛上而柔下，巽而止，蠱。蠱元亨，而天下治也。利涉大川，往有事也。先甲三日，後甲三日，終則有始，天行也。","大象":"《象》曰：山下有風，蠱。君子以振民育德。","互卦":"54 歸妹䷵","错卦":"17 隨䷐","综卦":"17 隨䷐","爻":[{"爻位":"初六","原文":"幹父之蠱，有子，考無咎，厲終吉。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 幹：整治、承担。父之蠱：父辈留下的弊病。考：亡父。厉终吉：过程有风险，最终吉。","译文":"整治父辈留下的弊病；有能干的后代，父辈也可免咎。过程虽危险，最终吉。","解说1_经义":"蠱卦讲修复积弊。初六首先面对继承问题：接手旧系统，不应只是维护前人名声，而要敢于修正其遗留错误。修正得当，反而是对前人的真正承继。","解说2_时位":"从时位看，本爻处在全卦发端，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：幹父之蠱，意承考也。","象传译文":"《象传》说：整治父蠱，是意在承继父辈真正的志业。","象传解说":"“承考”不是照搬旧法，而是保存其正当目的。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **26 大畜䷙**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"幹母之蠱，不可貞。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 幹母之蠱：整治母系或柔性、内部积弊。不可貞：不可固执一种办法。","译文":"整治母亲留下的积弊，不可过于执固。","解说1_经义":"九二刚中，面对偏柔、私人化的旧弊时，若用过强方式纠正，容易伤害关系。需要有原则但保留温度。","解说2_时位":"从时位看，本爻处在下卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：幹母之蠱，得中道也。","象传译文":"《象传》说：整治母蠱，是因为九二能够得中道。","象传解说":"得中意味着纠错也要适度。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **52 艮䷳**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"幹父之蠱，小有悔，無大咎。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔：悔恨，亦指可由反省而改的失误。 小有悔，无大咎：会有小遗憾，但无大错。","译文":"整治父辈积弊，会有一点悔，但没有大的灾咎。","解说1_经义":"九三刚而不中，改革力度可能过强，因此“小有悔”；但方向在于纠弊，故不至大咎。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：幹父之蠱，終無咎也。","象传译文":"《象传》说：整治父蠱，最终没有大的灾咎。","象传解说":"此爻说明改革中存在“用力过猛但方向正确”的情形。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **04 蒙䷃**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"裕父之蠱，往見吝。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 往：前往、向外发展。 裕：宽缓、姑息。往见吝：继续如此会见困吝。","译文":"宽纵父辈留下的弊病，继续下去会有遗憾。","解说1_经义":"六四的问题不是改革太猛，而是太宽。对积弊若只求和气、不愿触碰根源，问题会继续放大。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦艮（止、界限、山）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：裕父之蠱，往未得也。","象传译文":"《象传》说：宽纵父蠱，前往不能真正有所得。","象传解说":"小象反对以“宽厚”为名回避必要治理。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **50 鼎䷱**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"幹父之蠱，用譽。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 用誉：因整治得当而有声誉。","译文":"整治父辈积弊，并因此获得赞誉。","解说1_经义":"六五柔中居尊，以温和、正当方式完成系统修复。它不是亲自用强，而是通过合适的人和制度处理旧问题。","解说2_时位":"从时位看，本爻处在上卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦艮（止、界限、山）的上卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：幹父用譽，承以德也。","象传译文":"《象传》说：整治父蠱而有誉，是以德承继。","象传解说":"“承以德”把真正继承定义为德性与治理能力。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **57 巽䷸**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"不事王侯，高尚其事。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 不事王侯：不再从事王侯事务。高尚其事：以高尚之志自处。","译文":"不仕事王侯，而把自己的事业安顿在更高的志趣上。","解说1_经义":"上九处蠱之终，积弊已整治，个体可以退出具体权力争夺，守住独立价值。","解说2_时位":"从时位看，本爻处在全卦终位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦艮（止、界限、山）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不事王侯，志可則也。","象传译文":"《象传》说：不事王侯，其志可作为法则。","象传解说":"退出并非逃避，而可以是完成责任后的价值选择。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **46 升䷭**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"26 大畜䷙","二爻":"52 艮䷳","三爻":"04 蒙䷃","四爻":"50 鼎䷱","五爻":"57 巽䷸","上爻":"46 升䷭"}},{"卦序":19,"卦名":"臨","卦符":"䷒","全名":"地澤臨","上卦":"坤","下卦":"兌","卦辞":"臨，元亨，利貞。至于八月有凶。","彖传":"《彖》曰：臨，剛浸而長。說而順，剛中而應，大亨以正，天之道也。至于八月有凶，消不久也。","大象":"《象》曰：澤上有地，臨。君子以教思無窮，容保民無疆。","互卦":"24 復䷗","错卦":"33 遯䷠","综卦":"20 觀䷓","爻":[{"爻位":"初九","原文":"咸臨，貞吉。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 咸：感应。咸臨：以感通、亲近方式临人。","译文":"以感通之道临人，守正则吉。","解说1_经义":"临卦初九阳长而与六四相应，说明领导、接近别人首先要建立真实感应，而不是只靠命令。","解说2_时位":"从时位看，本爻处在全卦发端，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：咸臨貞吉，志行正也。","象传译文":"《象传》说：咸临守正而吉，是志向行于正道。","象传解说":"临的第一层是“正其志”。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **07 師䷆**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"咸臨，吉無不利。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 咸臨，吉無不利：感通更深。","译文":"以感通之道临人，吉而无所不利。","解说1_经义":"九二得中，既有主动性又不过度。它代表一种能真正进入他人处境的领导方式。","解说2_时位":"从时位看，本爻处在下卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：咸臨吉無不利，未順命也。","象传译文":"《象传》说：咸临吉无不利，是因为尚未完全顺从既有命令。","象传解说":"“未顺命”可理解为不被僵化形式束缚，仍保有主动判断。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **24 復䷗**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"甘臨，無攸利。既憂之，無咎。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 甘臨：以甜言、讨好方式临人。既憂之：若能意识问题而忧惧。","译文":"以讨好方式临人，没有真正利益；若能为此忧惧反省，则可无咎。","解说1_经义":"六三提醒：亲近不等于迎合。靠好听话维持关系，短期舒服，长期失去原则；好在它仍给出反省出口。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦兌（说悦、交流、泽）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：甘臨，位不當也；既憂之，咎不長也。","象传译文":"《象传》说：甘临，是因为位置不当；既能忧惧，灾咎便不会长久。","象传解说":"觉察错误可以改变后续结构。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **11 泰䷊**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"至臨，無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 至臨：亲临其境、接近到位。","译文":"亲自临近、到位处理，没有灾咎。","解说1_经义":"六四进入上卦，强调领导不能只远程判断，而要真正接近现场和对象。与初九相应，也有上下相接之象。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：至臨無咎，位當也。","象传译文":"《象传》说：至临无咎，是因为位置适当。","象传解说":"当位使“亲临”有正当性，不是越界干预。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **54 歸妹䷵**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"知臨，大君之宜，吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 知，通“智”。大君之宜：合乎大君的方式。","译文":"以智慧临人，这是大君应有的方式，吉。","解说1_经义":"六五柔中，最高层的“临”不是事必躬亲，而是知人、知时、知分寸，能用制度和人才治理。","解说2_时位":"从时位看，本爻处在上卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大君之宜，行中之謂也。","象传译文":"《象传》说：大君之宜，就是行中道。","象传解说":"最高领导智慧归于“中”。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **60 節䷻**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"敦臨，吉，無咎。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 敦：厚实、笃厚。","译文":"以敦厚之德临人，吉，无咎。","解说1_经义":"上六把临卦收束为厚德。临近别人到最后，不应形成控制，而应留下可承受、可依赖的厚实关系。","解说2_时位":"从时位看，本爻处在全卦终位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：敦臨之吉，志在內也。","象传译文":"《象传》说：敦临之吉，是志在于内、心意笃实。","象传解说":"“志在内”强调动机比姿态更重要。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **41 損䷨**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"07 師䷆","二爻":"24 復䷗","三爻":"11 泰䷊","四爻":"54 歸妹䷵","五爻":"60 節䷻","上爻":"41 損䷨"}},{"卦序":20,"卦名":"觀","卦符":"䷓","全名":"風地觀","上卦":"巽","下卦":"坤","卦辞":"觀，盥而不薦，有孚顒若。","彖传":"《彖》曰：大觀在上，順而巽，中正以觀天下。觀，盥而不薦，有孚顒若，下觀而化也。觀天之神道而四時不忒，聖人以神道設教而天下服矣。","大象":"《象》曰：風行地上，觀。先王以省方觀民設教。","互卦":"23 剝䷖","错卦":"34 大壯䷡","综卦":"19 臨䷒","爻":[{"爻位":"初六","原文":"童觀，小人無咎，君子吝。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 吝：艰难、遗憾、局促之象。 童觀：儿童式、浅层观看。","译文":"像儿童一样浅看事物，小人无咎，君子则有遗憾。","解说1_经义":"初六不是说儿童有罪，而是区分角色要求。普通人见识浅尚可理解，承担公共责任的君子若仍只看表面，就不够。","解说2_时位":"从时位看，本爻处在全卦发端，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：初六童觀，小人道也。","象传译文":"《象传》说：初六童观，是小人之道。","象传解说":"职位越高，观察深度要求越高。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **42 益䷩**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"窺觀，利女貞。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 窺觀：从缝隙窥看，视野狭窄。女贞：传统语境指适合内守。","译文":"从狭小缝隙观察，对守内之人或特定局部任务尚可。","解说1_经义":"六二得中但视野受限，说明局部观察不一定错误，只是不足以承担宏观判断。","解说2_时位":"从时位看，本爻处在下卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：窺觀女貞，亦可丑也。","象传译文":"《象传》说：窥观而以女贞为利，从大局看仍显局促。","象传解说":"小象用“可丑”提醒不可把局部视野当全局。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **59 渙䷺**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"觀我生，進退。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 觀我生：观察自己的生行、行为。進退：据此决定进退。","译文":"观察自己的行为与处境，再决定进退。","解说1_经义":"六三处内外转换点，观不再只向外，而是回看自身。自我评估是决定是否进入更大舞台的前提。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：觀我生進退，未失道也。","象传译文":"《象传》说：观我生而进退，是尚未失去正道。","象传解说":"能自省，就不易被外在评价牵着走。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **53 漸䷴**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"觀國之光，利用賓于王。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 國之光：国家的文明、制度与成就。賓于王：作为宾客参与王事。","译文":"观察国家的光明文明，适宜作为王者宾客参与其事。","解说1_经义":"六四接近九五，看到的不再是个人，而是制度整体。此时适宜进入公共治理、向优秀秩序学习。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的上卦之始、进入外部阶段位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：觀國之光，尚賓也。","象传译文":"《象传》说：观国之光，是崇尚以宾礼参与王事。","象传解说":"“宾”意味着参与而不失独立判断。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **12 否䷋**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"觀我生，君子無咎。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 觀我生：九五由上位反观自己的治理及其在民间的结果。","译文":"观察自己的行为与治理效果，君子无咎。","解说1_经义":"九五的“我生”不能只理解为私人生活。处尊位者要通过民众状态反观自身政策和德行。","解说2_时位":"从时位看，本爻处在上卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：觀我生，觀民也。","象传译文":"《象传》说：观我生，就是观察民众。","象传解说":"这把领导者的自我评价转化为结果评价：看民，才知道自己。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **23 剝䷖**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"觀其生，君子無咎。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 觀其生：观察他者、天下或整个系统的生行。","译文":"观察整体生命与行为状态，君子无咎。","解说1_经义":"上九已超出具体执政位置，更像站在高处观察时代与社会。其任务是保持反省，不因超脱而自满。","解说2_时位":"从时位看，本爻处在全卦终位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：觀其生，志未平也。","象传译文":"《象传》说：观其生，是志意仍未完全安平。","象传解说":"“未平”使观察保持开放，不把自己的判断当最终结论。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **08 比䷇**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"42 益䷩","二爻":"59 渙䷺","三爻":"53 漸䷴","四爻":"12 否䷋","五爻":"23 剝䷖","上爻":"08 比䷇"}},{"卦序":21,"卦名":"噬嗑","卦符":"䷔","全名":"火雷噬嗑","上卦":"離","下卦":"震","卦辞":"噬嗑，亨。利用獄。","彖传":"《彖》曰：頤中有物，曰噬嗑。噬嗑而亨，剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，利用獄也。","大象":"《象》曰：雷電噬嗑。先王以明罰敕法。","互卦":"39 蹇䷦","错卦":"48 井䷯","综卦":"22 賁䷕","爻":[{"爻位":"初九","原文":"屨校滅趾，無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 屨校：脚戴刑具。滅趾：遮没脚趾，象征小惩。","译文":"脚上戴刑具，遮住脚趾；尚可无咎。","解说1_经义":"噬嗑讲以刑法去除障碍。初九的小惩发生在过错刚开始时，目的在阻止继续前行，而不是重罚。","解说2_时位":"从时位看，本爻处在全卦发端，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦震（动、发起、震动、雷）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：屨校滅趾，不行也。","象传译文":"《象传》说：屨校灭趾，是使其不能继续错误行动。","象传解说":"早期约束能避免更大代价。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **35 晉䷢**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"噬膚滅鼻，無咎。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 噬膚：咬柔软肉，表示处理问题较容易。滅鼻：深入过度而伤及鼻。","译文":"咬食柔肉而没过鼻子，没有大的灾咎。","解说1_经义":"六二处理障碍本较容易，但因乘刚，用力可能偏深。结果虽无咎，仍提醒执行规则要有尺度。","解说2_时位":"从时位看，本爻处在下卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦震（动、发起、震动、雷）的内卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：噬膚滅鼻，乘剛也。","象传译文":"《象传》说：噬肤灭鼻，是因为六二乘刚。","象传解说":"结构压力使执法容易过度。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **38 睽䷥**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"噬臘肉，遇毒；小吝，無咎。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 臘肉：干肉。毒：不良之物，也可指味变。小吝无咎：有小麻烦，无大错。","译文":"咬干腊肉而遇到毒味，会有小遗憾，但没有大的灾咎。","解说1_经义":"六三面对的问题更硬、更复杂，而且自身位置不当。处理积案时出现反噬并不奇怪，重要的是方向仍在清障。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的下卦之终、内外转换前位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：遇毒，位不當也。","象传译文":"《象传》说：遇毒，是因为位置不当。","象传解说":"不当位说明工具、角色与任务匹配度不足。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **30 離䷝**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"噬乾胏，得金矢，利艱貞，吉。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 乾胏：带骨干肉。金矢：金属箭头，象征刚直证据或坚硬之物。艱貞：以困难意识守正。","译文":"咬带骨干肉，得到金矢；在艰难中守正则吉。","解说1_经义":"九四进入噬嗑核心难题，必须具备硬证据、刚直原则和耐力。越难的案件，越不能靠情绪。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦離（明、附丽、文明、火）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：利艱貞吉，未光也。","象传译文":"《象传》说：艰贞之吉，是因为光明尚未完全显现。","象传解说":"未光说明任务虽有进展，仍需审慎。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **27 頤䷚**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"噬乾肉，得黃金，貞厲，無咎。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 乾肉：干肉。黃金：黄为中，金为刚，可象征中正之实。","译文":"咬干肉而得到黄金，守正虽有危险，却可无咎。","解说1_经义":"六五居尊而柔中，处理重大障碍必须中正。位置越高，裁决越要承担风险；“无咎”来自守正，而非没有压力。","解说2_时位":"从时位看，本爻处在上卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦離（明、附丽、文明、火）的上卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：貞厲無咎，得當也。","象传译文":"《象传》说：守正虽危险而无咎，是因为处理得当。","象传解说":"“得当”是司法型判断的核心。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **25 無妄䷘**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"何校滅耳，凶。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 何，通“荷”，负戴。何校：肩负大枷。滅耳：遮没、伤及耳朵。","译文":"肩负重刑具，耳朵被遮没或伤损，凶。","解说1_经义":"上九表示错误累积到重罚阶段。耳象征听，走到这里往往意味着长期不听劝、不接受早期纠正。","解说2_时位":"从时位看，本爻处在全卦终位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：何校滅耳，聰不明也。","象传译文":"《象传》说：肩负重枷而灭耳，是因为听觉不明、不能听取警戒。","象传解说":"噬嗑从初爻小惩到上爻重刑，构成完整的预防性警告链。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **51 震䷲**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"35 晉䷢","二爻":"38 睽䷥","三爻":"30 離䷝","四爻":"27 頤䷚","五爻":"25 無妄䷘","上爻":"51 震䷲"}},{"卦序":22,"卦名":"賁","卦符":"䷕","全名":"山火賁","上卦":"艮","下卦":"離","卦辞":"賁，亨。小利有攸往。","彖传":"《彖》曰：賁，亨。柔來而文剛，故亨；分剛上而文柔，故小利有攸往。天文也。文明以止，人文也。觀乎天文，以察時變；觀乎人文，以化成天下。","大象":"《象》曰：山下有火，賁。君子以明庶政，無敢折獄。","互卦":"40 解䷧","错卦":"47 困䷮","综卦":"21 噬嗑䷔","爻":[{"爻位":"初九","原文":"賁其趾，舍車而徒。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 賁其趾：装饰脚趾。舍車而徒：舍车步行。","译文":"修饰自己的脚步，舍弃车乘而徒步。","解说1_经义":"贲卦初爻强调文饰不能凌驾于真实行动。宁可朴素步行，也不借不合身份的外在工具抬高自己。","解说2_时位":"从时位看，本爻处在全卦发端，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：舍車而徒，義弗乘也。","象传译文":"《象传》说：舍车而徒步，是义理上不应乘坐。","象传解说":"形式必须与身份和正当性匹配。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **52 艮䷳**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"賁其須。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 須：胡须。胡须依附面部而生，象征文饰有所依附。","译文":"修饰胡须。","解说1_经义":"六二说明装饰本身不能独立存在，必须依附于实质。没有内容的包装没有意义。","解说2_时位":"从时位看，本爻处在下卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦離（明、附丽、文明、火）的内卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：賁其須，與上興也。","象传译文":"《象传》说：贲其须，是随着上方一同兴起。","象传解说":"文依质而生，是贲卦基本原则。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **26 大畜䷙**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"賁如濡如，永貞吉。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 濡如：润泽光鲜。永贞：长久守正。","译文":"文饰润泽光鲜；能够长久守正则吉。","解说1_经义":"九三处文明与止的交界，外在表现很美，但越美越要守住内在标准，防止形式压倒内容。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦離（明、附丽、文明、火）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：永貞之吉，終莫之陵也。","象传译文":"《象传》说：永贞之吉，是最终无人能够凌越。","象传解说":"真正可久的美，依赖稳定的原则。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **27 頤䷚**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"賁如皤如，白馬翰如，匪寇婚媾。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 皤如：洁白朴素。翰如：白马飞驰貌。匪寇婚媾：不是敌寇，而是求合者。","译文":"看似白素，白马疾驰而来；来者并非寇敌，而是求婚结合。","解说1_经义":"六四处文质转换处，表面朴素并不等于贫乏。面对突然到来的关系，不要因外观误判为威胁。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦艮（止、界限、山）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六四當位疑也；匪寇婚媾，終無尤也。","象传译文":"《象传》说：六四当位而有疑；不是寇而是婚媾，最终无尤。","象传解说":"“疑”是过渡位置的心理反应，需要用事实校正。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **30 離䷝**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"賁于丘園，束帛戔戔，吝，終吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 吝：艰难、遗憾、局促之象。 丘園：朴素园圃。束帛戔戔：礼物少而薄。","译文":"把文饰用于丘园，以少量帛礼相赠；虽显寒薄而有吝，最终吉。","解说1_经义":"六五居尊却崇尚朴实，礼物不多但诚意足。贲到高位反而回归简素，说明文明的高级形态不是奢华。","解说2_时位":"从时位看，本爻处在上卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦艮（止、界限、山）的上卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六五之吉，有喜也。","象传译文":"《象传》说：六五最终吉，是因为有喜庆。","象传解说":"小而真胜过大而浮。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **37 家人䷤**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"白賁，無咎。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 白賁：以白色为饰，近乎无饰。","译文":"以素白为饰，没有灾咎。","解说1_经义":"上九是贲之终，“饰”走到极致反而返璞归真。形式完成后，应让本质重新显现。","解说2_时位":"从时位看，本爻处在全卦终位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦艮（止、界限、山）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：白賁無咎，上得志也。","象传译文":"《象传》说：白贲无咎，是上位者最终得志。","象传解说":"贲卦以“无饰之饰”收尾，体现文质循环。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **36 明夷䷣**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"52 艮䷳","二爻":"26 大畜䷙","三爻":"27 頤䷚","四爻":"30 離䷝","五爻":"37 家人䷤","上爻":"36 明夷䷣"}},{"卦序":23,"卦名":"剝","卦符":"䷖","全名":"山地剝","上卦":"艮","下卦":"坤","卦辞":"剝，不利有攸往。","彖传":"《彖》曰：剝，剝也，柔變剛也。不利有攸往，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。","大象":"《象》曰：山附于地，剝。上以厚下安宅。","互卦":"02 坤䷁","错卦":"43 夬䷪","综卦":"24 復䷗","爻":[{"爻位":"初六","原文":"剝床以足，蔑貞凶。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 剝床以足：从床脚开始剥蚀。蔑貞：侵蚀正固。","译文":"剥蚀从床脚开始，侵害正道，凶。","解说1_经义":"剥卦初六提示破坏从基础开始。基础结构一旦被侵蚀，若不处理，会逐层向上。","解说2_时位":"从时位看，本爻处在全卦发端，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：剝床以足，以滅下也。","象传译文":"《象传》说：剥床以足，是在消灭最下层的基础。","象传解说":"识别基础风险，是剥时第一要务。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **27 頤䷚**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"剝床以辨，蔑貞凶。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 辨：床身边缘、床板部位。","译文":"剥蚀已经到床身，侵害正道，凶。","解说1_经义":"六二表示问题从根基扩展到主体结构。此时不能再把它看成局部小故障。","解说2_时位":"从时位看，本爻处在下卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：剝床以辨，未有與也。","象传译文":"《象传》说：剥床以辨，是因为尚无有力援助。","象传解说":"缺乏支持会加速结构崩解。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **04 蒙䷃**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"剝之，無咎。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 剝之：处于剥落中。无咎：此爻能与上九相应。","译文":"身处剥落之中，却可无咎。","解说1_经义":"六三虽在群阴中，却与上九阳爻相应，象征在整体坏趋势中仍能保持与正向核心的联系。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：剝之無咎，失上下也。","象传译文":"《象传》说：剥之无咎，是因为与上下群阴有所分离。","象传解说":"逆环境而不随众，是此爻的价值。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **52 艮䷳**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"剝床以膚，凶。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 膚：肌肤。剥床以肤：剥蚀已近身。","译文":"剥蚀已经逼近肌肤，凶。","解说1_经义":"六四说明风险由外部结构进入直接伤害阶段。此前若未止损，此时成本已经很高。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦艮（止、界限、山）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：剝床以膚，切近災也。","象传译文":"《象传》说：剥床以肤，是灾害切近。","象传解说":"“切近灾”是明确的红线信号。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **35 晉䷢**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"貫魚，以宮人寵，無不利。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 貫魚：鱼贯而行。宮人寵：像宫人按序受宠，不争先。","译文":"像鱼贯而行，以宫人次序受宠，无所不利。","解说1_经义":"六五处群阴之首，若能把众阴组织成有序关系并顺从唯一阳刚核心，剥势便可被控制。","解说2_时位":"从时位看，本爻处在上卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦艮（止、界限、山）的上卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：以宮人寵，終無尤也。","象传译文":"《象传》说：以宫人受宠，最终没有过失。","象传解说":"关键由竞争转为秩序。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **20 觀䷓**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"碩果不食，君子得輿，小人剝廬。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 碩果不食：硕大果实没有被吃，保留种子。君子得輿：君子得车。小人剝廬：小人连屋舍都被剥掉。","译文":"硕果没有被吃掉；君子得到车载，小人则连居所也被剥毁。","解说1_经义":"上九是剥中唯一阳爻，如最后一颗种子。大势衰败时，保住核心原则和再生种子，比挽救所有表面结构更重要。","解说2_时位":"从时位看，本爻处在全卦终位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦艮（止、界限、山）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：君子得輿，民所載也；小人剝廬，終不可用也。","象传译文":"《象传》说：君子得舆，是民众所承载；小人剥庐，是最终不可再用。","象传解说":"剥极必复，硕果正是下一轮复生的条件。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **02 坤䷁**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"27 頤䷚","二爻":"04 蒙䷃","三爻":"52 艮䷳","四爻":"35 晉䷢","五爻":"20 觀䷓","上爻":"02 坤䷁"}},{"卦序":24,"卦名":"復","卦符":"䷗","全名":"地雷復","上卦":"坤","下卦":"震","卦辞":"復，亨。出入無疾，朋來無咎。反復其道，七日來復。利有攸往。","彖传":"《彖》曰：復亨。剛反，動而以順行，是以出入無疾，朋來無咎。反復其道，七日來復，天行也。利有攸往，剛長也。復其見天地之心乎。","大象":"《象》曰：雷在地中，復。先王以至日閉關，商旅不行，后不省方。","互卦":"02 坤䷁","错卦":"44 姤䷫","综卦":"23 剝䷖","爻":[{"爻位":"初九","原文":"不遠復，無祇悔，元吉。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 不遠復：离开正道不远就返回。祇：至、致；无祇悔即不至于悔。","译文":"走偏不远便返回，不至于悔恨，大吉。","解说1_经义":"复卦初九是一阳初生。错误并不可怕，最可贵的是在偏离尚小时立即修正。恢复成本最低、效果最好。","解说2_时位":"从时位看，本爻处在全卦发端，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不遠之復，以修身也。","象传译文":"《象传》说：不远而复，是用以修养自身。","象传解说":"复首先是自我纠偏，而不是要求别人改变。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **02 坤䷁**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"休復，吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 休復：美善地返回，也有依善而复之意。","译文":"善美地回归正道，吉。","解说1_经义":"六二得中，能够受到初九正向力量影响而回归。改正有时不必完全依靠个人意志，也可借助好榜样、好环境。","解说2_时位":"从时位看，本爻处在下卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦震（动、发起、震动、雷）的内卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：休復之吉，以下仁也。","象传译文":"《象传》说：休复之吉，是因为能下亲于仁。","象传解说":"靠近善者，是复的一条重要路径。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **19 臨䷒**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"頻復，厲，無咎。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 頻復：频繁偏离又返回。厉无咎：有危险但可免咎。","译文":"反复走偏又反复返回，有危险，但最终可无咎。","解说1_经义":"六三说明改过不是一次完成。虽然频繁犯错并不理想，但仍愿意回头，比固执到底更好。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦震（动、发起、震动、雷）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：頻復之厲，義無咎也。","象传译文":"《象传》说：频复虽危险，从义理上仍可无咎。","象传解说":"《易》允许反复修正，而不要求完美无错。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **36 明夷䷣**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"中行獨復。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 中行獨復：在群阴中独自回归。","译文":"走在中间，却独自回归正道。","解说1_经义":"六四处众阴之间，与初九相应。环境未必支持改变，但个体可以依据内在判断独自转向。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：中行獨復，以從道也。","象传译文":"《象传》说：中行独复，是为了从道而行。","象传解说":"真正的复有时需要摆脱群体惯性。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **51 震䷲**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"敦復，無悔。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔：悔恨，亦指可由反省而改的失误。 敦復：厚实、真诚地返回。","译文":"敦厚真诚地回归，没有悔恨。","解说1_经义":"六五居中，复已经内化为稳定品格，不再是危机中的临时反应。","解说2_时位":"从时位看，本爻处在上卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：敦復無悔，中以自考也。","象传译文":"《象传》说：敦复无悔，是居中而能自我考察。","象传解说":"“自考”说明成熟的复来自持续自省。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **03 屯䷂**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"迷復，凶，有災眚。用行師，終有大敗；以其國君凶，至于十年不克征。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 征：前往、出行、采取进取行动。 迷復：迷失而不能返回。災眚：灾害。行師：用兵。","译文":"迷失而不知复归，凶，会有灾害；若用兵将遭大败，甚至危及国君，十年也难再征。","解说1_经义":"上六错过所有回归节点，偏离已系统化。此时还发动大行动，只会把内部错误放大为外部灾难。","解说2_时位":"从时位看，本爻处在全卦终位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：迷復之凶，反君道也。","象传译文":"《象传》说：迷复之凶，是反背君道。","象传解说":"复卦用极重警语说明：纠错越晚，代价呈非线性增长。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **27 頤䷚**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"02 坤䷁","二爻":"19 臨䷒","三爻":"36 明夷䷣","四爻":"51 震䷲","五爻":"03 屯䷂","上爻":"27 頤䷚"}},{"卦序":25,"卦名":"無妄","卦符":"䷘","全名":"天雷無妄","上卦":"乾","下卦":"震","卦辞":"無妄，元亨，利貞。其匪正有眚，不利有攸往。","彖传":"《彖》曰：無妄，剛自外來而為主于內。動而健，剛中而應，大亨以正，天之命也。其匪正有眚，不利有攸往。無妄之往，何之矣？天命不祐，行矣哉。","大象":"《象》曰：天下雷行，物與無妄。先王以茂對時育萬物。","互卦":"53 漸䷴","错卦":"46 升䷭","综卦":"26 大畜䷙","爻":[{"爻位":"初九","原文":"無妄，往吉。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 往：前往、向外发展。 無妄：无虚妄、不妄为，亦有无妄之灾的语义背景。往吉：顺真实情势而行动。","译文":"不妄为，依真实而行，前往则吉。","解说1_经义":"初九阳刚在下，行动冲动尚未被复杂利益扭曲。无妄之道首先是动机真实、行动不造作；一旦为私欲强作，就偏离卦义。","解说2_时位":"从时位看，本爻处在全卦发端，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦震（动、发起、震动、雷）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：無妄之往，得志也。","象传译文":"《象传》说：无妄而往，是志向能够实现。","象传解说":"志得不是靠投机，而是因为行动与真实情况一致。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **12 否䷋**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"不耕穫，不菑畬，則利有攸往。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有攸往：有所前往、有所作为。 利：适宜、有利。 往：前往、向外发展。 耕穫：耕种与收获。菑畬：初垦之田与熟田。此句历来有不同断读，核心多在“不预设收获而自然耕作”。","译文":"不把耕作只当作求收获的手段，也不预先盘算田地成熟的利益；如此有所前往反而有利。","解说1_经义":"六二强调不以结果欲扭曲过程。真正的无妄，是把应做的事做好，而不是每一步都围绕回报计算。","解说2_时位":"从时位看，本爻处在下卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的内卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不耕穫，未富也。","象传译文":"《象传》说：“不耕而获”的说法，重点是不把富有当作行动动机。","象传解说":"“未富”可理解为不先以私利为目标，过程反而更纯正。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **10 履䷉**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"無妄之災，或繫之牛，行人之得，邑人之災。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 或繫之牛：有人拴牛。行人之得，邑人之災：路人意外得牛，本地人反遭损失。","译文":"有人拴着一头牛，过路人把它得去，却使邑里的人遭灾。","解说1_经义":"六三是著名的“无妄之灾”：有些损失并非当事人主动造成，而是复杂关系中的连带后果。实占时必须区分“可控风险”与“纯外部冲击”。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的下卦之终、内外转换前位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：行人得牛，邑人災也。","象传译文":"《象传》说：行人得牛，却成了邑人的灾。","象传解说":"小象直接保留事件的错位性，说明《易》并不把所有灾害都归因于道德过失。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **13 同人䷌**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"可貞，無咎。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 可貞：可以守正。九四阳居阴位，虽不当位但可自守。","译文":"可以守正，没有灾咎。","解说1_经义":"九四不需要额外做什么壮举。无妄之时，面对不确定性，守住正当边界就是最重要的行动。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：可貞無咎，固有之也。","象传译文":"《象传》说：可贞无咎，是因为正固本来就在自身。","象传解说":"“固有之”把正道放在内在稳定，而非外部奖赏。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **42 益䷩**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"無妄之疾，勿藥有喜。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 無妄之疾：非妄为造成的疾病。勿藥有喜：不宜过度干预。","译文":"出现并非妄为造成的疾病，不必急于用药，会有喜庆。","解说1_经义":"九五居中正，面对自然发生的小问题，过度治疗可能比问题本身更有害。此爻的现代启示是：不要对每个波动都立即强干预。","解说2_时位":"从时位看，本爻处在上卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：無妄之藥，不可試也。","象传译文":"《象传》说：无妄之疾不可轻易试药。","象传解说":"“不可试”强调干预本身也有成本。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **21 噬嗑䷔**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"無妄，行有眚，無攸利。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 行有眚：继续行动会招致灾害。","译文":"无妄之时若仍强行前进，会有灾害，没有什么利益。","解说1_经义":"上九说明即使初心无妄，也不能把“不妄”当成行动通行证。时机已穷，继续作为便从无妄转成妄动。","解说2_时位":"从时位看，本爻处在全卦终位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：無妄之行，窮之災也。","象传译文":"《象传》说：无妄而强行，是走到穷处所致的灾。","象传解说":"善意与正直不能替代时机判断。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **17 隨䷐**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"12 否䷋","二爻":"10 履䷉","三爻":"13 同人䷌","四爻":"42 益䷩","五爻":"21 噬嗑䷔","上爻":"17 隨䷐"}},{"卦序":26,"卦名":"大畜","卦符":"䷙","全名":"山天大畜","上卦":"艮","下卦":"乾","卦辞":"大畜，利貞。不家食吉，利涉大川。","彖传":"《彖》曰：大畜，剛健篤實輝光，日新其德。剛上而尚賢，能止健，大正也。不家食吉，養賢也。利涉大川，應乎天也。","大象":"《象》曰：天在山中，大畜。君子以多識前言往行，以畜其德。","互卦":"54 歸妹䷵","错卦":"45 萃䷬","综卦":"25 無妄䷘","爻":[{"爻位":"初九","原文":"有厲，利已。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 已：止。利已：宜停止。","译文":"前方有危险，适宜停止。","解说1_经义":"大畜初九阳刚欲进，却受上艮止。积蓄阶段的第一课不是多做，而是知道什么时候不做，让力量留下来。","解说2_时位":"从时位看，本爻处在全卦发端，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：有厲利已，不犯災也。","象传译文":"《象传》说：有危险而宜止，是为了不触犯灾害。","象传解说":"止不是失败，而是保存成长空间。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **18 蠱䷑**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"輿說輹。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 輿說輹：车与固定车轴的构件脱开，车暂不能行。","译文":"车子的轴构件脱落，暂时无法前行。","解说1_经义":"九二得中，能接受被“畜止”的状态。车停下来象征主动解除行动能力，让资源先积累。","解说2_时位":"从时位看，本爻处在下卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：輿說輹，中無尤也。","象传译文":"《象传》说：车脱輹，因居中所以没有过失。","象传解说":"得中使停顿成为策略，而不是崩溃。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **22 賁䷕**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"良馬逐，利艱貞。曰閑輿衛，利有攸往。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有攸往：有所前往、有所作为。 利：适宜、有利。 往：前往、向外发展。 良馬逐：良马竞驰。閑輿衛：训练车驾与防卫。曰：一作“日”，日常训练。","译文":"良马驰逐，宜在艰难中守正；日常训练车驾与防卫，适宜有所前往。","解说1_经义":"九三积蓄已足，开始从“止”转为“练”。真正的大畜不是囤积，而是通过训练把资源转化为可用能力。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：利有攸往，上合志也。","象传译文":"《象传》说：适宜有所前往，是与上方志向相合。","象传解说":"准备充分后，行动才能顺势。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **41 損䷨**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"童牛之牿，元吉。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 童牛之牿：给小牛角上加横木，在力量尚小时预防顶撞。","译文":"给幼牛预先加上约束器具，大吉。","解说1_经义":"六四讲预防胜于惩治。问题尚小、习惯尚未固化时建立边界，成本最低。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦艮（止、界限、山）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六四元吉，有喜也。","象传译文":"《象传》说：六四元吉，是有值得庆喜之事。","象传解说":"大畜的“畜”在这里表现为早期教育和制度预防。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **14 大有䷍**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"豶豕之牙，吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 豶豕：阉割后的公猪。牙：猪牙。通过改变根源而降低攻击性。","译文":"把公猪从根本上驯化，即使有牙也不再为患，吉。","解说1_经义":"六五比六四更进一步：不是只在外部加限制，而是改变产生危险行为的内在条件。治理成熟度由“管住”升级为“使其不必被管”。","解说2_时位":"从时位看，本爻处在上卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦艮（止、界限、山）的上卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六五之吉，有慶也。","象传译文":"《象传》说：六五之吉，会带来庆成。","象传解说":"从源头治理比反复压制更有效。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **09 小畜䷈**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"何天之衢，亨。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 亨：通达、顺畅；古义又与享献相关。 何：一说通“荷”，一说语气；天之衢：通天大道。","译文":"大道通达于天，亨通。","解说1_经义":"上九蓄积已完成，阻碍消失，力量进入大通道。前面的止、练、防、化最终都为了让行动更自由。","解说2_时位":"从时位看，本爻处在全卦终位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦艮（止、界限、山）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：何天之衢，道大行也。","象传译文":"《象传》说：何天之衢，是大道得以广泛通行。","象传解说":"真正的自由来自充分准备后的通达。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **11 泰䷊**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"18 蠱䷑","二爻":"22 賁䷕","三爻":"41 損䷨","四爻":"14 大有䷍","五爻":"09 小畜䷈","上爻":"11 泰䷊"}},{"卦序":27,"卦名":"頤","卦符":"䷚","全名":"山雷頤","上卦":"艮","下卦":"震","卦辞":"頤，貞吉。觀頤，自求口實。","彖传":"《彖》曰：頤貞吉，養正則吉也。觀頤，觀其所養也；自求口實，觀其自養也。天地養萬物，聖人養賢以及萬民。頤之時大矣哉。","大象":"《象》曰：山下有雷，頤。君子以慎言語，節飲食。","互卦":"02 坤䷁","错卦":"28 大過䷛","综卦":"27 頤䷚","爻":[{"爻位":"初九","原文":"舍爾靈龜，觀我朵頤，凶。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 靈龜：古人用以占卜，象征自有明鉴。朵頤：鼓动腮颊欲食。","译文":"舍弃自己如灵龟般的明鉴，却看着我鼓腮求食，凶。","解说1_经义":"初九本有阳刚自主能力，却反而向外羡慕、求养，等于放弃自己的判断。颐卦首先问：你依赖什么来养自己？","解说2_时位":"从时位看，本爻处在全卦发端，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：觀我朵頤，亦不足貴也。","象传译文":"《象传》说：看我朵颐，这种状态不足为贵。","象传解说":"有能力却放弃自养，是本爻之凶。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **23 剝䷖**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"顛頤，拂經，于丘頤，征凶。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 征：前往、出行、采取进取行动。 顛頤：颠倒求养，向下求食。拂經：违背常道。丘：高处。","译文":"颠倒求养，违背常道，又向高处求养；前进则凶。","解说1_经义":"六二自身柔弱，正常应从上求养，却又受初九吸引，求养关系倒置。依赖对象选择错误，会让资源和角色都错位。","解说2_时位":"从时位看，本爻处在下卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦震（动、发起、震动、雷）的内卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六二征凶，行失類也。","象传译文":"《象传》说：六二前往之凶，是因为行动失去同类正道。","象传解说":"养的问题首先是关系结构问题。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **41 損䷨**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"拂頤，貞凶，十年勿用，無攸利。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 利：适宜、有利。 拂頤：违背正确养道。十年勿用：长期不可施用，极言后果严重。","译文":"违背养生、养德之道，守此则凶；很长时间都难以施展，没有什么利益。","解说1_经义":"六三欲望与方法都偏离正道。错误的“养”会反过来损害主体，例如只满足即时欲望而忽略长期成长。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：十年勿用，道大悖也。","象传译文":"《象传》说：十年勿用，是因为大大违背了正道。","象传解说":"“道大悖”说明不是小失衡，而是养的方向根本错误。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **22 賁䷕**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"顛頤吉。虎視眈眈，其欲逐逐，無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 顛頤吉：向下求养而吉，此处因与初九正应。虎視眈眈：专注而有威。逐逐：欲求迫切、连续。","译文":"向下求养反而吉；像虎一样专注凝视，欲求持续而明确，无咎。","解说1_经义":"六四居上而能向下取贤、取资，是“反常而合宜”。领导者需要主动从基层吸收养分，只要目标正当、专注明确即可。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦艮（止、界限、山）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：顛頤之吉，上施光也。","象传译文":"《象传》说：颠颐之吉，是上方的施养因此光大。","象传解说":"向下求养最终是为了更好地向下施养。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **21 噬嗑䷔**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"拂經，居貞吉，不可涉大川。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 拂經：偏离通常路径。居貞吉：安居守正则吉。不可涉大川：不宜承担巨大风险。","译文":"虽偏离一般养道，但安居守正则吉；不宜渡大河、做重大冒险。","解说1_经义":"六五居尊却柔弱，需要依赖上九供养，因此不合常规。只要承认能力边界、稳定治理，就可吉；若强行做大事则不足。","解说2_时位":"从时位看，本爻处在上卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦艮（止、界限、山）的上卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：居貞之吉，順以從上也。","象传译文":"《象传》说：居贞之吉，是柔顺地从上九获得支持。","象传解说":"承认依赖并不等于失败，关键是不要超能力行动。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **42 益䷩**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"由頤，厲吉，利涉大川。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利涉大川：适宜渡越大河，常喻适宜承担重大行动或跨越艰险。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 由頤：由此而得到养、成为养人之源。厉吉：有风险而吉。","译文":"众人由此获得养育；虽有危险，但吉，适宜渡越大川。","解说1_经义":"上九成为全卦真正的供养者。承担别人所赖的资源与责任，本身压力巨大，却也因此具备做大事的条件。","解说2_时位":"从时位看，本爻处在全卦终位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦艮（止、界限、山）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：由頤厲吉，大有慶也。","象传译文":"《象传》说：由颐虽厉而吉，是因为会有大的庆成。","象传解说":"颐之终从“求养”转为“养人”。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **24 復䷗**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"23 剝䷖","二爻":"41 損䷨","三爻":"22 賁䷕","四爻":"21 噬嗑䷔","五爻":"42 益䷩","上爻":"24 復䷗"}},{"卦序":28,"卦名":"大過","卦符":"䷛","全名":"澤風大過","上卦":"兌","下卦":"巽","卦辞":"大過，棟橈。利有攸往，亨。","彖传":"《彖》曰：大過，大者過也。棟橈，本末弱也。剛過而中，巽而說行，利有攸往，乃亨。大過之時義大矣哉。","大象":"《象》曰：澤滅木，大過。君子以獨立不懼，遯世無悶。","互卦":"01 乾䷀","错卦":"27 頤䷚","综卦":"28 大過䷛","爻":[{"爻位":"初六","原文":"藉用白茅，無咎。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 藉：垫。白茅：洁白茅草，祭祀常用，象征慎重。","译文":"用洁白茅草垫承物品，没有灾咎。","解说1_经义":"大过是超常负荷之时，初六以极慎重的基础处理开篇。越是非常任务，越要重视最基本的承托。","解说2_时位":"从时位看，本爻处在全卦发端，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：藉用白茅，柔在下也。","象传译文":"《象传》说：用白茅垫承，是柔处最下。","象传解说":"柔下使基础具有缓冲能力。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **43 夬䷪**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"枯楊生稊，老夫得其女妻，無不利。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 枯楊生稊：枯杨重新生出嫩根芽。老夫女妻：年长男子得年轻妻。","译文":"枯杨重新发芽，老夫娶得年轻妻，没有不利。","解说1_经义":"九二刚而得中，与初六柔相亲，表现老与少、枯与新之间的互补。大过不全是灾，也可能在非常组合中产生再生。","解说2_时位":"从时位看，本爻处在下卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：老夫女妻，過以相與也。","象传译文":"《象传》说：老夫得女妻，是因超常而能够相与。","象传解说":"“过以相与”说明非常时期常需要非常组合。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **31 咸䷞**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"棟橈，凶。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 棟橈：栋梁弯曲。","译文":"栋梁弯曲，凶。","解说1_经义":"九三刚过而不中，承担的压力超过结构承受力。能力强不等于可以无限加负荷；失去支撑就会整体性失稳。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：棟橈之凶，不可以有輔也。","象传译文":"《象传》说：栋梁弯曲之凶，是因为不能得到辅助。","象传解说":"大过的风险本质是负荷与支撑不匹配。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **47 困䷮**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"棟隆，吉；有它吝。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 吝：艰难、遗憾、局促之象。 棟隆：栋梁向上隆起，尚能承重。有它：另生私意、旁念。","译文":"栋梁隆起，吉；若另有私心则有遗憾。","解说1_经义":"九四虽同样承担重压，但位置较适，且与初六有应，能获得支撑。最怕因额外目标分散结构资源。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：棟隆之吉，不橈乎下也。","象传译文":"《象传》说：栋隆之吉，是没有向下弯折。","象传解说":"在极限负荷中，保持主结构完整比追求附加利益重要。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **48 井䷯**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"枯楊生華，老婦得其士夫，無咎無譽。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 枯楊生華：枯杨开花但未必结果。老婦士夫：老妇得年轻丈夫。","译文":"枯杨开花，老妇得到年轻丈夫；无灾咎，也没有值得称誉的成果。","解说1_经义":"九五的再生更偏表面：开花虽美，却可能缺乏持久生殖力。非常组合能缓解问题，但不一定创造长期结果。","解说2_时位":"从时位看，本爻处在上卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦兌（说悦、交流、泽）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：枯楊生華，何可久也；老婦士夫，亦可丑也。","象传译文":"《象传》说：枯杨开花，怎么能够长久；老妇与士夫的组合，也难称美。","象传解说":"此爻提醒区分短期繁荣与长期再生。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **32 恆䷟**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"過涉滅頂，凶，無咎。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 過涉滅頂：涉水过深而没顶。无咎：虽凶但动机或责任未必有过。","译文":"渡水过深，水没过头顶，凶；但可说没有道义上的过失。","解说1_经义":"上六把“大过”推到舍身承担的极端。结果可能失败甚至牺牲，但如果是为应当之事承担，并不能简单道德责咎。","解说2_时位":"从时位看，本爻处在全卦终位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：過涉之凶，不可咎也。","象传译文":"《象传》说：过涉之凶，不应一味责咎。","象传解说":"《易》在这里区分结果的凶与行为者的道义责任。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **44 姤䷫**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"43 夬䷪","二爻":"31 咸䷞","三爻":"47 困䷮","四爻":"48 井䷯","五爻":"32 恆䷟","上爻":"44 姤䷫"}},{"卦序":29,"卦名":"坎","卦符":"䷜","全名":"坎為水","上卦":"坎","下卦":"坎","卦辞":"坎，習坎，有孚，維心亨，行有尚。","彖传":"《彖》曰：習坎，重險也。水流而不盈，行險而不失其信。維心亨，乃以剛中也。行有尚，往有功也。天險不可升也，地險山川丘陵也。王公設險以守其國。坎之時用大矣哉。","大象":"《象》曰：水洊至，習坎。君子以常德行，習教事。","互卦":"27 頤䷚","错卦":"30 離䷝","综卦":"29 坎䷜","爻":[{"爻位":"初六","原文":"習坎，入于坎窞，凶。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 習坎：重重坎险。坎窞：坎中深穴。","译文":"一再陷入险境，又掉进险穴，凶。","解说1_经义":"初六在重险最下层，没有找到穿险之道，反而向更深处滑落。面对风险时，错误的第一反应往往比风险本身更危险。","解说2_时位":"从时位看，本爻处在全卦发端，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦坎（险、陷、流行、水）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：習坎入坎，失道凶也。","象传译文":"《象传》说：习坎而入坎，是因为失去了正确道路。","象传解说":"坎的关键不是有没有险，而是如何在险中保持方向。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **60 節䷻**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"坎有險，求小得。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 坎有險：险中仍有阻碍。求小得：只能取得小的成果。","译文":"身处坎险，只能求得一些小的收获。","解说1_经义":"九二刚中，虽然还不能脱险，却已能在险中建立有限控制。此时目标要缩小，先求局部确定性。","解说2_时位":"从时位看，本爻处在下卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦坎（险、陷、流行、水）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：求小得，未出中也。","象传译文":"《象传》说：只能求小得，是因为尚未走出险中。","象传解说":"得中并不等于立即脱险，而是让人在险中不乱。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **08 比䷇**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"來之坎坎，險且枕，入于坎窞，勿用。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 來之坎坎：来去皆险。險且枕：险上又倚险。勿用：不可行动。","译文":"前后来去都是险，险境相叠，又陷入深穴，此时不可有所作为。","解说1_经义":"六三处两坎交界，是风险最高的转换点。无论进退都缺少安全通道时，停止行动比硬选一个方向更理性。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦坎（险、陷、流行、水）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：來之坎坎，終無功也。","象传译文":"《象传》说：来去皆坎，最终不会有功。","象传解说":"“终无功”明确否定在信息与路径都不清时强行推进。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **48 井䷯**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"樽酒簋貳，用缶，納約自牖，終無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 樽酒簋貳：简薄酒食器物。缶：瓦器。納約自牖：从窗户送入简约礼物，象征以诚通达。","译文":"一樽酒、简单饭食，用瓦器盛着，从窗户递入，最终无咎。","解说1_经义":"六四已在险中，却与九五近比。资源匮乏时，形式可简，诚信不可少；建立一条真实沟通通道比豪华礼仪重要。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦坎（险、陷、流行、水）的上卦之始、进入外部阶段位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：樽酒簋貳，剛柔際也。","象传译文":"《象传》说：樽酒簋贰，是刚柔相交之际。","象传解说":"险境中的合作往往从低成本、可信任的小连接开始。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **47 困䷮**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"坎不盈，祇既平，無咎。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 坎不盈：险穴尚未满。祇既平：水接近平面，险将平复。","译文":"险坑尚未完全盈满，但水势已趋于平稳，没有灾咎。","解说1_经义":"九五居中，险情已被控制却尚未完全解除。此时不宜宣布胜利，继续维持稳定直到真正越险。","解说2_时位":"从时位看，本爻处在上卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦坎（险、陷、流行、水）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：坎不盈，中未大也。","象传译文":"《象传》说：坎尚未盈满，说明中道的作用还没有完全发挥。","象传解说":"“中未大”是对过早乐观的提醒。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **07 師䷆**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"繫用徽纆，寘于叢棘，三歲不得，凶。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 徽纆：绳索。寘于叢棘：置于荆棘牢狱。三歲不得：长期不得脱。","译文":"被绳索捆缚，置于丛棘之中，三年不得脱，凶。","解说1_经义":"上六在险中失去自救空间，象征错误累积为制度性约束。到了这一层，靠临时技巧已很难摆脱。","解说2_时位":"从时位看，本爻处在全卦终位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦坎（险、陷、流行、水）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：上六失道，凶三歲也。","象传译文":"《象传》说：上六失道，所以凶而且长期受困。","象传解说":"坎卦以“守信而行险”立义，上六则是完全失去这条路。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **59 渙䷺**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"60 節䷻","二爻":"08 比䷇","三爻":"48 井䷯","四爻":"47 困䷮","五爻":"07 師䷆","上爻":"59 渙䷺"}},{"卦序":30,"卦名":"離","卦符":"䷝","全名":"離為火","上卦":"離","下卦":"離","卦辞":"離，利貞，亨。畜牝牛吉。","彖传":"《彖》曰：離，麗也。日月麗乎天，百穀草木麗乎土。重明以麗乎正，乃化成天下。柔麗乎中正，故亨，是以畜牝牛吉也。","大象":"《象》曰：明兩作，離。大人以繼明照于四方。","互卦":"28 大過䷛","错卦":"29 坎䷜","综卦":"30 離䷝","爻":[{"爻位":"初九","原文":"履錯然，敬之無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 履錯然：脚步交错谨慎，也可理解为行动纷繁之初。敬之：保持敬慎。","译文":"行动刚开始、足迹交错复杂，只要保持敬慎便无咎。","解说1_经义":"离卦主明，但初九提醒：光明刚起时信息也可能纷杂，不能因为“看见”就轻率断定。敬慎是明智的底座。","解说2_时位":"从时位看，本爻处在全卦发端，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦離（明、附丽、文明、火）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：履錯之敬，以辟咎也。","象传译文":"《象传》说：履错而敬，是为了避开灾咎。","象传解说":"真正的明首先表现为谨慎。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **56 旅䷷**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"黃離，元吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 黃離：黄色之明。黄象中，离象明。元吉。","译文":"以中正之明附丽，大吉。","解说1_经义":"六二柔居阴位且得中，是离卦最纯的中明。光明若能中和，不刺目、不偏激，才真正可久。","解说2_时位":"从时位看，本爻处在下卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦離（明、附丽、文明、火）的内卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：黃離元吉，得中道也。","象传译文":"《象传》说：黄离元吉，是因为得到中道。","象传解说":"明而不过，是六二的核心。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **14 大有䷍**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"日昃之離，不鼓缶而歌，則大耋之嗟，凶。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 日昃：太阳西斜。缶：瓦器。大耋：高龄。嗟：叹息。","译文":"太阳已经西斜；若不能鼓缶而歌、安然接受，就只剩对衰老的叹息，凶。","解说1_经义":"九三面对光明由盛转衰。规律无法阻止，重要的是如何面对衰退：能接受周期变化，就不必陷入悲叹。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦離（明、附丽、文明、火）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：日昃之離，何可久也。","象传译文":"《象传》说：日昃之离，怎么可能长久？","象传解说":"小象把衰落正常化：盛明本来就不能永久停在正午。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **21 噬嗑䷔**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"突如其來如，焚如，死如，棄如。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 突如其來如：突然到来。焚如、死如、棄如：火灾、死亡、弃置连续意象。","译文":"突然猛烈而来，像焚烧、死亡、弃置一样。","解说1_经义":"九四阳刚进入上卦，光明若无过渡而骤然爆发，就会成为破坏性的火。此爻警戒突然上位、突然扩张、突然释放力量。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦離（明、附丽、文明、火）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：突如其來如，無所容也。","象传译文":"《象传》说：突然而来，是因为没有适当容身的位置。","象传解说":"“无所容”说明力量与环境不匹配。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **22 賁䷕**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"出涕沱若，戚嗟若，吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 沱若：泪流貌。戚嗟：忧伤叹息。","译文":"泪流满面、忧戚叹息，最终吉。","解说1_经义":"六五居尊而柔中，面对危险能真实忧惧，而不是以强势掩盖。对风险有情感上的警觉，反而促使其谨慎治理。","解说2_时位":"从时位看，本爻处在上卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦離（明、附丽、文明、火）的上卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六五之吉，離王公也。","象传译文":"《象传》说：六五之吉，是因为依附于王公之位而能守中。","象传解说":"忧惧在这里不是软弱，而是责任感。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **13 同人䷌**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"王用出征，有嘉折首，獲匪其丑，無咎。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 征：前往、出行、采取进取行动。 嘉：美善、值得肯定。折首：擒斩首恶。匪其丑：不滥及其同类。","译文":"王者出征，宜擒除首恶，而不滥杀其余同类，无咎。","解说1_经义":"上九的“明”用于辨别责任边界：治理冲突要精准打击核心问题，不能扩大化。","解说2_时位":"从时位看，本爻处在全卦终位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦離（明、附丽、文明、火）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：王用出征，以正邦也。","象传译文":"《象传》说：王用出征，是为了端正邦国。","象传解说":"离之明最终落实为辨明是非、罚当其罪。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **55 豐䷶**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"56 旅䷷","二爻":"14 大有䷍","三爻":"21 噬嗑䷔","四爻":"22 賁䷕","五爻":"13 同人䷌","上爻":"55 豐䷶"}},{"卦序":31,"卦名":"咸","卦符":"䷞","全名":"澤山咸","上卦":"兌","下卦":"艮","卦辞":"咸，亨，利貞。取女吉。","彖传":"《彖》曰：咸，感也。柔上而剛下，二氣感應以相與，止而說，男下女，是以亨利貞，取女吉也。天地感而萬物化生，聖人感人心而天下和平。觀其所感，而天地萬物之情可見矣。","大象":"《象》曰：山上有澤，咸。君子以虛受人。","互卦":"44 姤䷫","错卦":"41 損䷨","综卦":"32 恆䷟","爻":[{"爻位":"初六","原文":"咸其拇。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 拇：大脚趾，最下、最先动之处。","译文":"感应只发生在脚拇趾。","解说1_经义":"咸讲感应。初六的感应刚起，尚停留在微小冲动层面，还没有形成真正行动。","解说2_时位":"从时位看，本爻处在全卦发端，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦艮（止、界限、山）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：咸其拇，志在外也。","象传译文":"《象传》说：咸其拇，是志向已经指向外部。","象传解说":"动机已生，但行动尚浅。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **49 革䷰**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"咸其腓，凶，居吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 凶：凶险、不利。 腓：小腿肚。居吉：停住则吉。","译文":"感应到了小腿，若随之躁动则凶；安居不动则吉。","解说1_经义":"六二身体已更想行动，但得中要求克制。感受强烈并不等于必须马上回应。","解说2_时位":"从时位看，本爻处在下卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦艮（止、界限、山）的内卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：雖凶居吉，順不害也。","象传译文":"《象传》说：虽有凶而居吉，是顺势止住便不会受害。","象传解说":"咸卦强调“感而不失其主”。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **28 大過䷛**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"咸其股，執其隨，往吝。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 往：前往、向外发展。 股：大腿。執其隨：执着跟随别人。","译文":"感应到了大腿，一味执着跟随，前往会有遗憾。","解说1_经义":"九三刚而主动，容易把感应变成追随冲动。若没有自己的判断，感应便退化为随人而动。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦艮（止、界限、山）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：咸其股，亦不處也；志在隨人，所執下也。","象传译文":"《象传》说：咸其股，是不能安处；志在随人，所以所执偏下。","象传解说":"小象批评的是失去主体。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **45 萃䷬**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"貞吉悔亡，憧憧往來，朋從爾思。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 往：前往、向外发展。 憧憧：往来不定、心神纷扰。朋從爾思：朋友随着你的念头而来。","译文":"守正则吉，悔可消；若心思来往不定，朋友也只会随着你的纷乱念头而动。","解说1_经义":"九四处心位象征阶段，感应若有稳定原则可吉；若不停追逐反馈，就会形成情绪和社交回路。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：貞吉悔亡，未感害也；憧憧往來，未光大也。","象传译文":"《象传》说：贞吉悔亡，是尚未被感应所害；憧憧往来，则心志未能光大。","象传解说":"真正的感通需要中心，不是被每个刺激牵走。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **39 蹇䷦**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"咸其脢，無悔。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔：悔恨，亦指可由反省而改的失误。 脢：脊背两侧、近心而不直接受意志驱动之处。","译文":"感应到脊背一带，没有悔恨。","解说1_经义":"九五得中，感应变得深而不躁，不再表现为明显的肢体冲动。成熟关系往往不是高强度刺激，而是稳定默契。","解说2_时位":"从时位看，本爻处在上卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：咸其脢，志末也。","象传译文":"《象传》说：咸其脢，是志意不在末端外显。","象传解说":"“志末”历解不同，但可理解为不被表层感受牵制。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **62 小過䷽**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"咸其輔頰舌。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 輔頰舌：牙床、面颊、舌头，皆与言语有关。","译文":"感应只停在口舌、面颊之间。","解说1_经义":"上六把感应推到最表层的语言。如果关系只靠说辞而缺乏内在真实，就容易浮泛。","解说2_时位":"从时位看，本爻处在全卦终位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：咸其輔頰舌，滕口說也。","象传译文":"《象传》说：咸其辅颊舌，是滕口说、只在口头上活动。","象传解说":"咸以“口说”收尾，是对只说不行的警戒。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **33 遯䷠**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"49 革䷰","二爻":"28 大過䷛","三爻":"45 萃䷬","四爻":"39 蹇䷦","五爻":"62 小過䷽","上爻":"33 遯䷠"}},{"卦序":32,"卦名":"恆","卦符":"䷟","全名":"雷風恆","上卦":"震","下卦":"巽","卦辞":"恆，亨，無咎，利貞。利有攸往。","彖传":"《彖》曰：恆，久也。剛上而柔下，雷風相與，巽而動，剛柔皆應，恆。恆亨無咎利貞，久于其道也，天地之道恆久而不已也。利有攸往，終則有始也。日月得天而能久照，四時變化而能久成，聖人久于其道而天下化成。觀其所恆，而天地萬物之情可見矣。","大象":"《象》曰：雷風，恆。君子以立不易方。","互卦":"43 夬䷪","错卦":"42 益䷩","综卦":"31 咸䷞","爻":[{"爻位":"初六","原文":"浚恆，貞凶，無攸利。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 利：适宜、有利。 浚：深挖。浚恆：一开始便求恒得过深。","译文":"过度深求恒常，守此则凶，没有什么利益。","解说1_经义":"恒不是一开始就把关系、制度锁死。初六尚在开端，若急于要求永久承诺，反而违背发展规律。","解说2_时位":"从时位看，本爻处在全卦发端，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：浚恆之凶，始求深也。","象传译文":"《象传》说：浚恒之凶，是开始就求得太深。","象传解说":"恒需要时间生成，不能用强制制造。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **34 大壯䷡**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"悔亡。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 九二只有“悔亡”，爻辞极简。九二刚居阴位但得中。","译文":"悔恨消失。","解说1_经义":"九二说明处恒之道不必追求形式完美。虽不当位，但能守中，就能修正潜在问题。","解说2_时位":"从时位看，本爻处在下卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：九二悔亡，能久中也。","象传译文":"《象传》说：九二悔亡，是因为能够长久守中。","象传解说":"恒的核心不是僵硬不变，而是长期不失中道。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **62 小過䷽**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"不恆其德，或承之羞，貞吝。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 不恆其德：德行不能持久。承之羞：不断承受羞辱。","译文":"德行不能保持恒久，便可能不断蒙受羞辱；固执如此会有遗憾。","解说1_经义":"九三刚而不中，行动力强却缺乏稳定。才华如果每次都换方向，别人难以形成信任。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不恆其德，無所容也。","象传译文":"《象传》说：不能恒其德，最终无处可容。","象传解说":"社会信任高度依赖可预测性。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **40 解䷧**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"田無禽。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 田無禽：田猎却没有猎物。","译文":"田野中没有可猎之禽。","解说1_经义":"九四努力持续，却位置和方向不合。恒久投入若用在错误场域，时间越长并不会自动产生成果。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：久非其位，安得禽也。","象传译文":"《象传》说：长久处在不合适的位置，哪里能得到禽获？","象传解说":"坚持必须先校验方向。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **46 升䷭**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"恆其德，貞。婦人吉，夫子凶。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 凶：凶险、不利。 婦人吉，夫子凶：古代角色伦理语境中的判断，不能直接照搬为现代性别价值。重点在“从一”与“制义”的角色差异。","译文":"恒守其德、保持正固；在古代文本设定的妇人从一角色中为吉，而对需要裁义应变的丈夫则可能凶。","解说1_经义":"六五强调“恒”不能脱离角色职责。对需要稳定从一的任务，恒是优点；对需要随义裁变的决策者，僵化不变反成问题。","解说2_时位":"从时位看，本爻处在上卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的上卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：婦人貞吉，從一而終也；夫子制義，從婦凶也。","象传译文":"《象传》说：妇人守贞吉，是从一而终；夫子应裁制义理，若只从一则凶。","象传解说":"小象本身就指出：恒不是一律不变，而是守其应守、变其当变。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **28 大過䷛**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"振恆，凶。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 振恆：躁动不休地求恒，或恒常处于振动变化。","译文":"不断躁动，凶。","解说1_经义":"上六把“恒”推到悖论：若把持续变化本身变成常态，就失去真正稳定。不断调整、不断折腾也是一种失恒。","解说2_时位":"从时位看，本爻处在全卦终位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：振恆在上，大無功也。","象传译文":"《象传》说：振恒居上，最终没有大的功效。","象传解说":"恒之终告诫，稳定需要节律，不是持续兴奋。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **50 鼎䷱**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"34 大壯䷡","二爻":"62 小過䷽","三爻":"40 解䷧","四爻":"46 升䷭","五爻":"28 大過䷛","上爻":"50 鼎䷱"}},{"卦序":33,"卦名":"遯","卦符":"䷠","全名":"天山遯","上卦":"乾","下卦":"艮","卦辞":"遯，亨，小利貞。","彖传":"《彖》曰：遯，亨，遯而亨也。剛當位而應，與時行也。小利貞，浸而長也。遯之時義大矣哉。","大象":"《象》曰：天下有山，遯。君子以遠小人，不惡而嚴。","互卦":"44 姤䷫","错卦":"19 臨䷒","综卦":"34 大壯䷡","爻":[{"爻位":"初六","原文":"遯尾，厲，勿用有攸往。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有攸往：有所前往、有所作为。 往：前往、向外发展。 遯尾：退避时落在最后。厉：有危险。勿用有攸往：不宜再向前。","译文":"退避得太晚，落在队尾，危险；此时不宜再有所前往。","解说1_经义":"遯卦的核心是识时而退。初六最怕不是退，而是退得太迟；当不利力量已经逼近，继续进取只会增加暴露。","解说2_时位":"从时位看，本爻处在全卦发端，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦艮（止、界限、山）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：遯尾之厲，不往何災也。","象传译文":"《象传》说：遯尾有危险，只要不再前往，又会有什么灾呢？","象传解说":"小象把补救办法说得很清楚：危险出现后立即停止扩张。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **13 同人䷌**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"執之用黃牛之革，莫之勝說。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 黃牛之革：黄牛皮革，坚韧牢固；黄有中之义。莫之勝說：“说”通“脱”，无人能挣脱。","译文":"用黄牛皮牢牢系住，没有人能够挣脱。","解说1_经义":"六二不主动远遯，而以内在原则把自己系牢。外部环境动荡时，退守首先是价值和立场的稳定。","解说2_时位":"从时位看，本爻处在下卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦艮（止、界限、山）的内卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：執用黃牛，固志也。","象传译文":"《象传》说：用黄牛皮系住，是固守志向。","象传解说":"“固志”说明真正不可丢的是内在方向，而不一定是外在位置。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **44 姤䷫**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"系遯，有疾厲，畜臣妾吉。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 系遯：被牵系而不能顺利退。畜臣妾：处理近身小事尚可。","译文":"退避却受到牵系，会有疾病般的危厉；只适合处理近身的小范围事务。","解说1_经义":"九三想退而仍被关系、利益牵住，退得不彻底。此时不适合承担宏大行动，只宜缩小责任范围。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦艮（止、界限、山）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：系遯之厲，有疾憊也；畜臣妾吉，不可大事也。","象传译文":"《象传》说：系遯之厉，是被牵累而疲惫；畜臣妾吉，是不可做大事。","象传解说":"退的关键在于切断不必要的牵连。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **12 否䷋**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"好遯，君子吉，小人否。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 吉：吉利；在占辞中表示趋向有利。 好遯：合宜、美好的退避。君子吉，小人否。","译文":"善于退避，君子吉，小人做不到。","解说1_经义":"九四阳刚而能主动舍弃利益，是难度很高的退。真正的君子不是没有机会，而是知道有些机会不该拿。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：君子好遯，小人否也。","象传译文":"《象传》说：君子能够好遯，小人则不能。","象传解说":"是否能主动放弃，是人格与判断力的试金石。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **53 漸䷴**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"嘉遯，貞吉。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 嘉遯：美善、适时的退避。九五居中正。","译文":"适时而美善地退避，守正则吉。","解说1_经义":"九五并非失败而退，而是在最有能力时仍能识势止步。能从高位主动退出，避免与衰败结构一同沉没，是成熟判断。","解说2_时位":"从时位看，本爻处在上卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：嘉遯貞吉，以正志也。","象传译文":"《象传》说：嘉遯而守正吉，是为了端正志向。","象传解说":"退可以是一种主动战略，而非被动逃离。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **56 旅䷷**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"肥遯，無不利。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 肥遯：“肥”有宽裕、从容之意。","译文":"从容宽裕地退避，无所不利。","解说1_经义":"上九已经完全脱离牵累，所以退得自由。遯的最高状态不是狼狈逃亡，而是提前完成资源和心理上的脱钩。","解说2_时位":"从时位看，本爻处在全卦终位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：肥遯無不利，無所疑也。","象传译文":"《象传》说：肥遯无不利，是因为已经没有疑虑。","象传解说":"无疑来自边界清楚、决策完成。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **31 咸䷞**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"13 同人䷌","二爻":"44 姤䷫","三爻":"12 否䷋","四爻":"53 漸䷴","五爻":"56 旅䷷","上爻":"31 咸䷞"}},{"卦序":34,"卦名":"大壯","卦符":"䷡","全名":"雷天大壯","上卦":"震","下卦":"乾","卦辞":"大壯，利貞。","彖传":"《彖》曰：大壯，大者壯也。剛以動，故壯。大壯利貞，大者正也。正大而天地之情可見矣。","大象":"《象》曰：雷在天上，大壯。君子以非禮弗履。","互卦":"43 夬䷪","错卦":"20 觀䷓","综卦":"33 遯䷠","爻":[{"爻位":"初九","原文":"壯于趾，征凶，有孚。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 凶：凶险、不利。 征：前往、出行、采取进取行动。 孚：诚信、信实，也有取得信任之义。 壯于趾：强壮表现在脚趾，行动冲动先发。征凶：贸然进取凶。","译文":"力量只冲到脚趾便急着前进，出征会凶；这是可信的警戒。","解说1_经义":"大壮初九说明力量刚起时最容易把“能动”误作“该动”。实力增长并不自动意味着时机成熟。","解说2_时位":"从时位看，本爻处在全卦发端，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：壯于趾，其孚窮也。","象传译文":"《象传》说：壮于趾而贸然前往，其结果必走向困穷。","象传解说":"大壮首先要求控制行动冲动。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **32 恆䷟**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"貞吉。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 九二爻辞仅“贞吉”。得中而不过。","译文":"守正则吉。","解说1_经义":"九二刚中，力量不外露、不逞强，正是大壮中最稳健的用力方式。强大与克制结合，才形成真正可持续的力量。","解说2_时位":"从时位看，本爻处在下卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：九二貞吉，以中也。","象传译文":"《象传》说：九二贞吉，是因为居中。","象传解说":"“中”比“壮”更重要。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **55 豐䷶**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 罔：一说无，一说罔罟；君子用罔可理解为君子不用血气之壮。羝羊：公羊。羸其角：角被篱笆缠住。","译文":"小人凭强力行事，君子不如此；若执意强进会危险。公羊撞篱笆，反把角缠住。","解说1_经义":"九三力量过盛又不中，最容易把问题当作“只需更用力”。结果就是典型的强力陷阱：越撞越被卡住。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：小人用壯，君子罔也。","象传译文":"《象传》说：小人使用强壮，君子则不以蛮力为道。","象传解说":"真正的强者知道力量并非唯一工具。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **54 歸妹䷵**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"貞吉悔亡，藩決不羸，壯于大輿之輹。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 藩決不羸：篱笆打开，不再缠角。大輿之輹：大车轴部件，象征承载力。","译文":"守正则吉、悔亡；篱笆已经打开，不再困住羊角，力量像大车的轴具一样强。","解说1_经义":"九四跨过之前的障碍后，力量终于有通道。此时吉不是因为更猛，而是阻力结构已经改变。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦震（动、发起、震动、雷）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：藩決不羸，尚往也。","象传译文":"《象传》说：篱笆打开而不受困，是可以继续前往。","象传解说":"力量只有进入正确通道才能成为生产力。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **11 泰䷊**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"喪羊于易，無悔。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔：悔恨，亦指可由反省而改的失误。 喪羊于易：“易”有场地、边界等多解；核心是羊之刚壮不再执持。无悔。","译文":"在边界处失去那只好斗的羊，却没有悔恨。","解说1_经义":"六五柔居尊位，主动放下“壮”的姿态。领导位置不必时时显示强硬；能让强力退出，反而避免冲突升级。","解说2_时位":"从时位看，本爻处在上卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的上卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：喪羊于易，位不當也。","象传译文":"《象传》说：丧羊于易，是因为位置不当。","象传解说":"柔居阳位提醒：此时价值不在继续强，而在调节力量。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **43 夬䷪**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"羝羊觸藩，不能退，不能遂，無攸利，艱則吉。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 羝羊觸藩：公羊撞篱。不能退不能遂：进退皆难。艰则吉：承认困难、谨慎处理则可转吉。","译文":"公羊撞篱笆，既退不了也进不成，没有所利；若以艰难戒慎处之，则可吉。","解说1_经义":"上六显示壮到极点的僵局。越用蛮力越卡死，唯一出口是承认困难、停止硬撞、重新设计路径。","解说2_时位":"从时位看，本爻处在全卦终位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不能退不能遂，不詳也；艱則吉，咎不長也。","象传译文":"《象传》说：不能退不能进，是因为不够审慎；知艰则吉，灾咎不会长久。","象传解说":"困局并不可怕，拒绝承认困局才危险。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **14 大有䷍**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"32 恆䷟","二爻":"55 豐䷶","三爻":"54 歸妹䷵","四爻":"11 泰䷊","五爻":"43 夬䷪","上爻":"14 大有䷍"}},{"卦序":35,"卦名":"晉","卦符":"䷢","全名":"火地晉","上卦":"離","下卦":"坤","卦辞":"晉，康侯用錫馬蕃庶，晝日三接。","彖传":"《彖》曰：晉，進也。明出地上，順而麗乎大明，柔進而上行，是以康侯用錫馬蕃庶，晝日三接也。","大象":"《象》曰：明出地上，晉。君子以自昭明德。","互卦":"39 蹇䷦","错卦":"05 需䷄","综卦":"36 明夷䷣","爻":[{"爻位":"初六","原文":"晉如摧如，貞吉。罔孚，裕，無咎。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 孚：诚信、信实，也有取得信任之义。 晉如摧如：想进却受压挫。罔孚：暂未获信。裕：宽缓从容。","译文":"前进时受到挫折，守正则吉；暂时不被信任，只要宽裕从容，可无咎。","解说1_经义":"晋卦初六刚开始上升，认可尚未建立。此时最忌因受挫急于证明自己；持续做对的事，让信任逐步形成。","解说2_时位":"从时位看，本爻处在全卦发端，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：晉如摧如，獨行正也；裕無咎，未受命也。","象传译文":"《象传》说：晋如摧如，是独自行正；宽裕无咎，是尚未正式受命。","象传解说":"没有授权时，克制比抢位更重要。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **21 噬嗑䷔**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"晉如愁如，貞吉。受茲介福，于其王母。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 愁如：忧愁而进。介福：大福。王母：尊长女性象。","译文":"前进中忧愁，守正则吉；会从王母处获得大福。","解说1_经义":"六二得中却无直接应援，前进并不轻松。它说明支持可能来自意料之外的上层或长辈资源。","解说2_时位":"从时位看，本爻处在下卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：受茲介福，以中正也。","象传译文":"《象传》说：得到大福，是因为六二中正。","象传解说":"内在质量先于外部机会。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **64 未濟䷿**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"眾允，悔亡。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 眾允：众人信服、认可。","译文":"得到众人认可，悔恨消失。","解说1_经义":"六三虽不当位，却获得群体信任。晋不仅是个人升迁，也需要社会认同；当共识形成，位置缺陷可被部分修正。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的下卦之终、内外转换前位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：眾允之，志上行也。","象传译文":"《象传》说：众人信服，是志向可以向上实行。","象传解说":"晋升的合法性来自支持基础。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **56 旅䷷**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"晉如鼫鼠，貞厲。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 鼫鼠：大鼠，传统常借喻贪而多惧者。","译文":"前进得像鼫鼠一样贪惧，固守如此会危险。","解说1_经义":"九四接近高位却心态不正，资源越多越怕失去，遂出现贪取与畏惧并存。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：鼫鼠貞厲，位不當也。","象传译文":"《象传》说：鼫鼠而贞厉，是因为位置不当。","象传解说":"上升若只增加焦虑，说明德位不匹配。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **23 剝䷖**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"悔亡，失得勿恤，往吉，無不利。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 利：适宜、有利。 往：前往、向外发展。 失得勿恤：不要患得患失。","译文":"悔恨消失，不必计较一时得失；前往则吉，无所不利。","解说1_经义":"六五柔中居尊，晋到这里最重要的是从个人得失中抽身，专注于应做之事。","解说2_时位":"从时位看，本爻处在上卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦離（明、附丽、文明、火）的上卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：失得勿恤，往有慶也。","象传译文":"《象传》说：不计得失而往，是会有庆成。","象传解说":"成熟的晋升从“我得到什么”转向“位置要求我做什么”。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **12 否䷋**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"晉其角，維用伐邑，厲吉無咎，貞吝。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 吝：艰难、遗憾、局促之象。 晉其角：前进到角尖，已至极端。伐邑：征伐自己的城邑，偏向内部整顿。","译文":"前进到了角端，只适宜用来整治自己的邑地；虽危险而可吉无咎，但执守此道仍有吝。","解说1_经义":"上九晋极，再向外扩张已不合时。剩余力量适合用于内部纠偏，而非继续追求更高。","解说2_时位":"从时位看，本爻处在全卦终位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：維用伐邑，道未光也。","象传译文":"《象传》说：只宜伐邑，是因为晋道还未真正光大。","象传解说":"升到顶点后，真正任务转为内治。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **16 豫䷏**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"21 噬嗑䷔","二爻":"64 未濟䷿","三爻":"56 旅䷷","四爻":"23 剝䷖","五爻":"12 否䷋","上爻":"16 豫䷏"}},{"卦序":36,"卦名":"明夷","卦符":"䷣","全名":"地火明夷","上卦":"坤","下卦":"離","卦辞":"明夷，利艱貞。","彖传":"《彖》曰：明入地中，明夷。內文明而外柔順，以蒙大難，文王以之。利艱貞，晦其明也；內難而能正其志，箕子以之。","大象":"《象》曰：明入地中，明夷。君子以蒞眾，用晦而明。","互卦":"40 解䷧","错卦":"06 訟䷅","综卦":"35 晉䷢","爻":[{"爻位":"初九","原文":"明夷于飛，垂其翼。君子于行，三日不食。有攸往，主人有言。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有攸往：有所前往、有所作为。 君子：有德行、有担当之人；《易传》中常作为修德主体。 往：前往、向外发展。 明夷于飛：光明受伤而飞遁。垂其翼：翼下垂。三日不食：艰苦逃避。主人有言：遭人议论。","译文":"光明受伤而飞，垂下翅膀；君子出行，三日不得食，虽有去处，却会遭主人议论。","解说1_经义":"明夷初九首先选择离开危险中心。隐晦时期，保住自身光明比争取理解更重要；即使因此被误会，也要先脱险。","解说2_时位":"从时位看，本爻处在全卦发端，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：君子于行，義不食也。","象传译文":"《象传》说：君子于行而不食，是义理上不肯以不正方式求食。","象传解说":"离开黑暗结构常伴随短期代价。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **15 謙䷎**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"明夷，夷于左股，用拯馬壯，吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 夷于左股：左腿受伤。拯馬壯：借强壮之马救援。","译文":"光明受伤，伤到左腿；借助强壮的马救出，吉。","解说1_经义":"六二柔中，受伤但未伤核心。此时应快速借助外部工具和支持恢复行动力，不必逞强独撑。","解说2_时位":"从时位看，本爻处在下卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦離（明、附丽、文明、火）的内卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六二之吉，順以則也。","象传译文":"《象传》说：六二之吉，是顺着法则行动。","象传解说":"受伤时会求助，也是顺势。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **11 泰䷊**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"明夷于南狩，得其大首，不可疾貞。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 南狩：向南征猎。大首：首恶、主要目标。不可疾贞：不可急躁地固执推进。","译文":"在南方狩猎，抓到首恶；但不可急于求成地守固推进。","解说1_经义":"九三由内明进入外暗，有能力直击问题核心，但即使胜势明显，治理黑暗也不可能一蹴而就。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：南狩之志，乃大得也。","象传译文":"《象传》说：南狩之志，最终有大的收获。","象传解说":"得首恶只是开始，重建秩序仍需时间。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **24 復䷗**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"入于左腹，獲明夷之心，于出門庭。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 左腹：内部隐秘处。獲明夷之心：掌握伤明的真实内因。出門庭：离开其门庭。","译文":"进入其内部，掌握伤害光明的核心原因，然后走出门庭。","解说1_经义":"六四已经深入黑暗系统内部，看清机制后最重要的是退出，不与之同化。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：入于左腹，獲心意也。","象传译文":"《象传》说：进入左腹，是获得其内心真实意图。","象传解说":"洞察不是为了沉浸其中，而是为了作出清晰离开决策。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **55 豐䷶**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"箕子之明夷，利貞。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 箕子：商末贤人，传统以佯狂自晦保存正道。利贞。","译文":"像箕子那样把光明隐藏起来，适宜守正。","解说1_经义":"六五处黑暗中心，无法公开发挥，只能“晦其明”。这不是放弃原则，而是用隐蔽方式保存原则。","解说2_时位":"从时位看，本爻处在上卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：箕子之貞，明不可息也。","象传译文":"《象传》说：箕子之贞，说明光明本身不可熄灭。","象传解说":"真正的明可以暂时不显，却不能内部灭失。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **63 既濟䷾**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"不明晦，初登于天，後入于地。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 不明晦：不是光明，而是昏暗。初登于天，後入于地：先极盛，后坠落。","译文":"不再光明而陷入昏暗；起初高登于天，后来坠入地下。","解说1_经义":"上六代表造成明夷的黑暗权力。它曾处极高位置，但失去明德后终将坠落。","解说2_时位":"从时位看，本爻处在全卦终位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：初登于天，照四國也；後入于地，失則也。","象传译文":"《象传》说：初登于天，曾照临四方；后来入地，是因为失去法则。","象传解说":"明夷以黑暗自身的覆亡收尾。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **22 賁䷕**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"15 謙䷎","二爻":"11 泰䷊","三爻":"24 復䷗","四爻":"55 豐䷶","五爻":"63 既濟䷾","上爻":"22 賁䷕"}},{"卦序":37,"卦名":"家人","卦符":"䷤","全名":"風火家人","上卦":"巽","下卦":"離","卦辞":"家人，利女貞。","彖传":"《彖》曰：家人，女正位乎內，男正位乎外，男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父、子子、兄兄、弟弟、夫夫、婦婦，而家道正。正家而天下定矣。","大象":"《象》曰：風自火出，家人。君子以言有物而行有恆。","互卦":"64 未濟䷿","错卦":"40 解䷧","综卦":"38 睽䷥","爻":[{"爻位":"初九","原文":"閑有家，悔亡。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 閑：防范、设限。有家：治理家庭。","译文":"在家庭初始就建立界限与规矩，悔恨可免。","解说1_经义":"家人卦把治理起点放在“闲”。规则越早建立，越不需要后期用强制修复。","解说2_时位":"从时位看，本爻处在全卦发端，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：閑有家，志未變也。","象传译文":"《象传》说：闲有家，是因为成员志向尚未变化、最容易立规矩。","象传解说":"教育和制度的黄金期往往在习惯未成之前。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **53 漸䷴**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"無攸遂，在中饋，貞吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 無攸遂：不专断向外求成。在中饋：主持家中饮食、内务。古代角色语境明显。","译文":"不宜自行向外专断，宜把内部事务料理好，守正则吉。","解说1_经义":"六二强调角色分工和稳定运营。不能把古代性别分工原样套用于现代，但可抽象为：组织中基础运营需要有人稳定负责。","解说2_时位":"从时位看，本爻处在下卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的内卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六二之吉，順以巽也。","象传译文":"《象传》说：六二之吉，是柔顺而能巽入。","象传解说":"稳定支持性角色同样是系统不可缺少的力量。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **09 小畜䷈**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"家人嗃嗃，悔厲吉；婦子嘻嘻，終吝。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 吝：艰难、遗憾、局促之象。 嗃嗃：严厉。嘻嘻：嬉笑放纵。","译文":"家人严厉管束，虽有悔厉而最终吉；若妇子嬉笑无度，最终有吝。","解说1_经义":"九三提出家庭治理的尺度难题：过严有伤，过松失序。相比完全放纵，宁可略严，但理想仍是有温度的规则。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦離（明、附丽、文明、火）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：家人嗃嗃，未失也；婦子嘻嘻，失家節也。","象传译文":"《象传》说：嗃嗃虽严，尚未失其原则；嘻嘻无度，则失去家节。","象传解说":"真正标准不是严或松，而是有没有“节”。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **42 益䷩**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"富家，大吉。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 富家：使家庭富足。六四当位。","译文":"使家道富足，大吉。","解说1_经义":"六四把“家”的治理落实为资源管理。财富不是家人卦的全部，却是稳定共同体的重要基础。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：富家大吉，順在位也。","象传译文":"《象传》说：富家大吉，是因为柔顺而处位得当。","象传解说":"家庭资源增长需要合适的管理角色。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **13 同人䷌**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"王假有家，勿恤吉。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 王假有家：王者至于有家之道、以家道治家。勿恤吉。","译文":"王者把家治理得当，不必忧虑，吉。","解说1_经义":"九五中正，与六二相应。最高责任者不必事无巨细控制，而要通过自身关系和德行形成稳定家道。","解说2_时位":"从时位看，本爻处在上卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：王假有家，交相愛也。","象传译文":"《象传》说：王假有家，是成员彼此相爱。","象传解说":"家道最终不能只靠制度，还要有真实的互爱。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **22 賁䷕**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"有孚威如，終吉。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 吉：吉利；在占辞中表示趋向有利。 孚：诚信、信实，也有取得信任之义。 有孚威如：既诚信，又有威仪。","译文":"有诚信而又有威严，最终吉。","解说1_经义":"上九说明家庭秩序若要长久，亲爱之外仍需可信的权威。威来自自律和一致性，而不是恐吓。","解说2_时位":"从时位看，本爻处在全卦终位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：威如之吉，反身之謂也。","象传译文":"《象传》说：威如之吉，是先反求诸己。","象传解说":"真正的家长权威首先建立在自我要求上。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **63 既濟䷾**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"53 漸䷴","二爻":"09 小畜䷈","三爻":"42 益䷩","四爻":"13 同人䷌","五爻":"22 賁䷕","上爻":"63 既濟䷾"}},{"卦序":38,"卦名":"睽","卦符":"䷥","全名":"火澤睽","上卦":"離","下卦":"兌","卦辞":"睽，小事吉。","彖传":"《彖》曰：睽，火動而上，澤動而下，二女同居，其志不同行。說而麗乎明，柔進而上行，得中而應乎剛，是以小事吉。天地睽而其事同也，男女睽而其志通也，萬物睽而其事類也。睽之時用大矣哉。","大象":"《象》曰：上火下澤，睽。君子以同而異。","互卦":"63 既濟䷾","错卦":"39 蹇䷦","综卦":"37 家人䷤","爻":[{"爻位":"初九","原文":"悔亡，喪馬勿逐，自復。見惡人無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 喪馬勿逐自復：马失去不必追，会自行回来。惡人：不喜欢的人。","译文":"马丢了不必追，会自己回来；即使见到自己厌恶的人，也可无咎。","解说1_经义":"睽卦是分歧。初九的策略不是对每个分离都强行追回，也不要因厌恶完全断绝接触；给关系留回旋空间。","解说2_时位":"从时位看，本爻处在全卦发端，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦兌（说悦、交流、泽）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：見惡人，以辟咎也。","象传译文":"《象传》说：见恶人，是为了避开更大的灾咎。","象传解说":"有时最低限度沟通比彻底敌对更安全。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **64 未濟䷿**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"遇主于巷，無咎。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 巷：狭道、非正式场合。遇主：遇到应当相见的主人。","译文":"在巷道中遇见主人，无咎。","解说1_经义":"九二与六五相应，却在睽时不能按正常正式路径相见，只能曲折相遇。形式受阻时，核心连接仍可保留。","解说2_时位":"从时位看，本爻处在下卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：遇主于巷，未失道也。","象传译文":"《象传》说：巷中遇主，并没有失去正道。","象传解说":"非常环境允许非常路径，只要目的正当。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **21 噬嗑䷔**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"見輿曳，其牛掣，其人天且劓，無初有終。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 輿曳：车被拖住。牛掣：牛被牵制。天且劓：古代刑伤意象，文本有异读。无初有终：开始不好，最终有结果。","译文":"车被拖住，牛也受牵制，人又似遭刑伤；开端不顺，最终仍有结果。","解说1_经义":"六三处严重误解和互相牵制中。睽的现实往往不是单一敌意，而是每一方都把对方行为读成伤害。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：見輿曳，位不當也；無初有終，遇剛也。","象传译文":"《象传》说：车被拖住，是因位置不当；虽无好开端，最终因遇刚而有结果。","象传解说":"关系可以从冲突中重新建立，但需要突破最初认知。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **14 大有䷍**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"睽孤，遇元夫，交孚，厲無咎。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 孚：诚信、信实，也有取得信任之义。 睽孤：因分歧而孤立。元夫：可信赖的刚健之人。交孚：以诚信相交。","译文":"在睽离中孤立，却遇到可靠之人，彼此诚信相交；虽有危险而无咎。","解说1_经义":"九四没有正应，容易孤立，但遇初九同类可建立真实关系。分歧环境中，一个可信连接就能大幅降低风险。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦離（明、附丽、文明、火）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：交孚無咎，志行也。","象传译文":"《象传》说：交孚无咎，是志向因此能够施行。","象传解说":"睽中不求所有人一致，先找到可互信者。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **41 損䷨**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"悔亡，厥宗噬膚，往何咎。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 往：前往、向外发展。 厥宗噬膚：同宗咬合柔肉，喻关系障碍容易打通。","译文":"悔恨消失，同宗之间像咬柔肉一样容易打通，前往有什么灾咎？","解说1_经义":"六五与九二相应，之前的隔阂开始化解。关系中只要核心信任仍在，很多表层冲突并没有想象中坚硬。","解说2_时位":"从时位看，本爻处在上卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的上卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：厥宗噬膚，往有慶也。","象传译文":"《象传》说：同宗噬肤，前往会有庆成。","象传解说":"睽不是永恒分裂，正确对应能重新连接。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **10 履䷉**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧；匪寇婚媾，往遇雨則吉。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 往：前往、向外发展。 豕負塗：猪背满泥。載鬼一車：看见一车鬼魅。張弧、說弧：先拉弓后放下。雨：阴阳和合之象。","译文":"孤疑中看见泥猪，又像看见一车鬼，先张弓准备射击，后来又放下；原来不是寇敌而是婚媾，前往遇雨则吉。","解说1_经义":"上九是睽卦最生动的“疑心制造敌人”。在高度疏离时，人会把模糊信息解释成威胁；验证之后才发现可以合作。","解说2_时位":"从时位看，本爻处在全卦终位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：遇雨之吉，群疑亡也。","象传译文":"《象传》说：遇雨之吉，是群疑消散。","象传解说":"睽之终不是强迫一致，而是通过事实让猜疑解除。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **54 歸妹䷵**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"64 未濟䷿","二爻":"21 噬嗑䷔","三爻":"14 大有䷍","四爻":"41 損䷨","五爻":"10 履䷉","上爻":"54 歸妹䷵"}},{"卦序":39,"卦名":"蹇","卦符":"䷦","全名":"水山蹇","上卦":"坎","下卦":"艮","卦辞":"蹇，利西南，不利東北；利見大人，貞吉。","彖传":"《彖》曰：蹇，難也，險在前也。見險而能止，知矣哉。蹇利西南，往得中也；不利東北，其道窮也。利見大人，往有功也；當位貞吉，以正邦也。蹇之時用大矣哉。","大象":"《象》曰：山上有水，蹇。君子以反身修德。","互卦":"64 未濟䷿","错卦":"38 睽䷥","综卦":"40 解䷧","爻":[{"爻位":"初六","原文":"往蹇，來譽。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 往蹇來譽：前往遇难，回来获誉。","译文":"继续前往会更艰难，返回等待反而有声誉。","解说1_经义":"蹇卦初六离险尚有退路。面对明确障碍，及时返回不是怯懦，而是对形势的尊重。","解说2_时位":"从时位看，本爻处在全卦发端，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦艮（止、界限、山）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：往蹇來譽，宜待也。","象传译文":"《象传》说：往蹇来誉，是适宜等待。","象传解说":"“宜待”是此阶段的最佳动作。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **63 既濟䷾**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"王臣蹇蹇，匪躬之故。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 蹇蹇：艰难又艰难。匪躬之故：不是为自己。","译文":"王臣在重重艰难中奔走，并不是为了自己。","解说1_经义":"六二得中，与九五相应。它承担困难是出于公共责任，不以个人安危为首要。","解说2_时位":"从时位看，本爻处在下卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦艮（止、界限、山）的内卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：王臣蹇蹇，終無尤也。","象传译文":"《象传》说：王臣蹇蹇，最终没有过失。","象传解说":"责任型困难与无谓冒险不同。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **48 井䷯**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"往蹇來反。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 往蹇來反：去则难，回来则返回自己的依托。","译文":"向前更艰难，回来反而能恢复。","解说1_经义":"九三前临坎险，回到内卦艮止更合适。面对无法突破的障碍，回到可控范围整顿资源是理性选择。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦艮（止、界限、山）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：往蹇來反，內喜之也。","象传译文":"《象传》说：往蹇来反，是内部联系因此欢喜。","象传解说":"退回内部可以重新获得支持。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **08 比䷇**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"往蹇來連。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 來連：回来与人相连。","译文":"前往艰难，回来则能与同伴连结。","解说1_经义":"六四进入坎险，自身力量不足；解决路径不在单打独斗，而在连接下方伙伴。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦坎（险、陷、流行、水）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：往蹇來連，當位實也。","象传译文":"《象传》说：往蹇来连，是因为所处位置有真实基础。","象传解说":"困难时期，网络比孤勇重要。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **31 咸䷞**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"大蹇朋來。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 大蹇朋來：大难之时朋友到来。","译文":"遭遇大困难，朋友前来相助。","解说1_经义":"九五中正居尊，面对的不是个人小难，而是系统性困难。良好信用与位置会吸引协助者。","解说2_时位":"从时位看，本爻处在上卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大蹇朋來，以中節也。","象传译文":"《象传》说：大蹇朋来，是九五能以中道节制。","象传解说":"危机中最能检验平时积累的信任资本。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **15 謙䷎**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"往蹇來碩，吉；利見大人。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 大人：有德有位、有能力担当大事之人；不宜简单等同现代某一具体身份。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 往：前往、向外发展。 來碩：回来有大收获。利見大人。","译文":"继续前往艰难，回来却有大收获，吉；适宜见大人。","解说1_经义":"上六到蹇之终，不再向外硬闯，转身回到九五中正核心，反而完成困局转化。","解说2_时位":"从时位看，本爻处在全卦终位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：往蹇來碩，志在內也；利見大人，以從貴也。","象传译文":"《象传》说：往蹇来硕，是志在内部；利见大人，是追随尊贵中正者。","象传解说":"蹇的出口不是把所有山险征服，而是回到正确中心。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **53 漸䷴**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"63 既濟䷾","二爻":"48 井䷯","三爻":"08 比䷇","四爻":"31 咸䷞","五爻":"15 謙䷎","上爻":"53 漸䷴"}},{"卦序":40,"卦名":"解","卦符":"䷧","全名":"雷水解","上卦":"震","下卦":"坎","卦辞":"解，利西南。無所往，其來復吉；有攸往，夙吉。","彖传":"《彖》曰：解，險以動，動而免乎險，解。解利西南，往得眾也；其來復吉，乃得中也；有攸往夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之時大矣哉。","大象":"《象》曰：雷雨作，解。君子以赦過宥罪。","互卦":"63 既濟䷾","错卦":"37 家人䷤","综卦":"39 蹇䷦","爻":[{"爻位":"初六","原文":"無咎。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 初六只言“无咎”，处解之始，柔居阳位但与九四相应。","译文":"没有灾咎。","解说1_经义":"解卦刚从险中解脱，初六最重要的是不再制造新问题。危机解除后的第一步常不是扩张，而是让系统恢复平静。","解说2_时位":"从时位看，本爻处在全卦发端，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：剛柔之際，義無咎也。","象传译文":"《象传》说：刚柔相际，合乎义理，所以无咎。","象传解说":"互相接续而不过度行动，是解初的状态。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **54 歸妹䷵**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"田獲三狐，得黃矢，貞吉。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 田獲三狐：田猎捕获狡狐。黃矢：黄色箭，象征中直。","译文":"田猎捕获三只狐狸，又得到黄箭；守正则吉。","解说1_经义":"九二处解之中，需要清除残余隐患。狐象征隐蔽问题，“黄矢”强调处理方式仍须中正直接。","解说2_时位":"从时位看，本爻处在下卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：九二貞吉，得中道也。","象传译文":"《象传》说：九二贞吉，是因为得到中道。","象传解说":"解除危机不是报复，而是精准处理遗留问题。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **16 豫䷏**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"負且乘，致寇至，貞吝。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 負且乘：本应负重者却乘车，比喻身份、资源不相称。致寇至：招来盗寇。","译文":"背负东西的人却乘着车，容易招来盗寇；固执如此会有吝。","解说1_经义":"六三在解困后突然占有超出自身匹配的资源，容易引来觊觎和质疑。危机后的分配不公会制造新危机。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦坎（险、陷、流行、水）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：負且乘，亦可丑也；自我致戎，又誰咎也。","象传译文":"《象传》说：负且乘，本身就可羞；自己招来盗寇，又能责怪谁？","象传解说":"小象把风险归于“自我暴露”和位置错配。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **32 恆䷟**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"解而拇，朋至斯孚。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 孚：诚信、信实，也有取得信任之义。 解而拇：解除脚拇的牵连，传统多释解除小人、低层牵累。朋至斯孚：朋友到来而可信。","译文":"解除脚下的牵累，朋友前来便能彼此信任。","解说1_经义":"九四要真正脱困，需先切断低层次纠缠。旧关系不断，新的可信合作就难建立。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：解而拇，未當位也。","象传译文":"《象传》说：解除其拇，是因为九四位置尚未完全得当。","象传解说":"解的过程也包括关系清理。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **07 師䷆**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"君子維有解，吉；有孚于小人。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 有孚：有诚信、取得信任。 吉：吉利；在占辞中表示趋向有利。 孚：诚信、信实，也有取得信任之义。 維有解：确实能够解除。孚于小人：使小人相信其已解除私系。","译文":"君子能够真正解除牵累，吉；以此使小人也信服。","解说1_经义":"六五的解是公开、可信的。高位者若说“解除旧弊”，必须通过行为让利益相关者相信，而不能只口头宣布。","解说2_时位":"从时位看，本爻处在上卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的上卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：君子有解，小人退也。","象传译文":"《象传》说：君子有解，小人便退。","象传解说":"真正改革会改变行为激励，而非只换说法。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **47 困䷮**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"公用射隼于高墉之上，獲之，無不利。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 隼：猛禽。高墉：高墙。公用射隼：上位者击除高处隐患。","译文":"王公在高墙上射隼，一举获之，无所不利。","解说1_经义":"上六是解卦最终清除高处危险。前面逐步松绑后，最后才适合处理最顽固、位置最高的障碍。","解说2_时位":"从时位看，本爻处在全卦终位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦震（动、发起、震动、雷）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：公用射隼，以解悖也。","象传译文":"《象传》说：公射隼，是为解除悖乱。","象传解说":"解的完成需要精准清除最后的结构性阻碍。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **64 未濟䷿**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"54 歸妹䷵","二爻":"16 豫䷏","三爻":"32 恆䷟","四爻":"07 師䷆","五爻":"47 困䷮","上爻":"64 未濟䷿"}},{"卦序":41,"卦名":"損","卦符":"䷨","全名":"山澤損","上卦":"艮","下卦":"兌","卦辞":"損，有孚，元吉，無咎，可貞，利有攸往。曷之用？二簋可用享。","彖传":"《彖》曰：損，損下益上，其道上行。損而有孚，元吉無咎，可貞，利有攸往。曷之用？二簋可用享。二簋應有時。損剛益柔有時，損益盈虛，與時偕行。","大象":"《象》曰：山下有澤，損。君子以懲忿窒欲。","互卦":"24 復䷗","错卦":"31 咸䷞","综卦":"42 益䷩","爻":[{"爻位":"初九","原文":"已事遄往，無咎，酌損之。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 已事：事情完成。遄：迅速。酌损之：斟酌减少自己的部分。","译文":"完成手头之事后，应迅速前往帮助他人；没有灾咎，但要斟酌自身减损的程度。","解说1_经义":"损卦不是盲目牺牲。初九阳刚有余，可以损己益上，但必须在不破坏自身基本能力的前提下进行。先完成本职，再支援他人，是边界意识。","解说2_时位":"从时位看，本爻处在全卦发端，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：已事遄往，尚合志也。","象传译文":"《象传》说：事情完成后迅速前往，是为了与上方志向相合。","象传解说":"损己必须服务于共同目标，而不是无原则自耗。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **04 蒙䷃**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"利貞，征凶。弗損益之。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 利：适宜、有利。 征：前往、出行、采取进取行动。 弗损益之：不损害自己，反而可以增益对方。","译文":"适宜守正；贸然前往反而凶。不必损伤自己，也能够增益他人。","解说1_经义":"九二得中，强调健康的付出不应以自毁为代价。真正有效的支持，是保有自身稳定后产生外溢价值。","解说2_时位":"从时位看，本爻处在下卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：九二利貞，中以為志也。","象传译文":"《象传》说：九二利贞，是以中道作为志向。","象传解说":"损益之间必须守中，过度牺牲同样失衡。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **27 頤䷚**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"三人行則損一人，一人行則得其友。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 三人行则损一人：三者关系容易形成多余与猜疑。一人行则得其友：独立者反能找到真正对应。","译文":"三人同行往往会减少一人；一个人独行，反而能得到真正的朋友。","解说1_经义":"六三讲关系结构中的“过密”。并非人越多越好；当协作需要清晰配对时，多出的关系可能制造竞争和猜疑。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：一人行，三則疑也。","象传译文":"《象传》说：一个人独行，是因为三人同行容易生疑。","象传解说":"损在这里表现为主动简化关系。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **26 大畜䷙**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"損其疾，使遄有喜，無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 损其疾：减去自身毛病。使遄有喜：让对方快速前来，双方有喜。","译文":"减损自身的弊病，使对方能够迅速靠近，有喜，无咎。","解说1_经义":"六四最值得损的不是财物，而是自身缺点。许多关系障碍来自自己的习惯；先改自己，外部关系自然改善。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦艮（止、界限、山）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：損其疾，亦可喜也。","象传译文":"《象传》说：损其疾，是值得喜悦的。","象传解说":"自我修正是损卦最内在的一层。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **38 睽䷥**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"或益之十朋之龜，弗克違，元吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 十朋之龜：极贵重的大龟，朋为古代贝币单位；喻巨大、不可拒绝的增益。","译文":"有人增益以价值十朋的大龟，无法拒绝，大吉。","解说1_经义":"六五柔中居尊，前面合理的“损下益上”在此形成正向回报。得到大助时，重点不是贪求，而是接受合乎正道的支持。","解说2_时位":"从时位看，本爻处在上卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦艮（止、界限、山）的上卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六五元吉，自上祐也。","象传译文":"《象传》说：六五元吉，是从上得到助佑。","象传解说":"正当关系会形成互惠循环。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **61 中孚䷼**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"弗損益之，無咎，貞吉，利有攸往，得臣無家。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有攸往：有所前往、有所作为。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 往：前往、向外发展。 得臣无家：得到臣属而不据为私家，一说使众人无私家之隔。","译文":"不损人反而增益人，无咎，守正吉，适宜有所前往；能得到臣属而不以私家占有。","解说1_经义":"上九把损转为益。最高层次不是继续抽取，而是创造增益，让众人愿意追随却不被私人化。","解说2_时位":"从时位看，本爻处在全卦终位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦艮（止、界限、山）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：弗損益之，大得志也。","象传译文":"《象传》说：不损而益，大得其志。","象传解说":"损走到极处必须反转为增益，否则体系不可持续。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **19 臨䷒**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"04 蒙䷃","二爻":"27 頤䷚","三爻":"26 大畜䷙","四爻":"38 睽䷥","五爻":"61 中孚䷼","上爻":"19 臨䷒"}},{"卦序":42,"卦名":"益","卦符":"䷩","全名":"風雷益","上卦":"巽","下卦":"震","卦辞":"益，利有攸往，利涉大川。","彖传":"《彖》曰：益，損上益下，民說無疆；自上下下，其道大光。利有攸往，中正有慶；利涉大川，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。","大象":"《象》曰：風雷，益。君子以見善則遷，有過則改。","互卦":"23 剝䷖","错卦":"32 恆䷟","综卦":"41 損䷨","爻":[{"爻位":"初九","原文":"利用為大作，元吉，無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 大作：重大事业。初九阳动在下，有能力承接上益。","译文":"适宜承担重大事业，大吉，无咎。","解说1_经义":"益卦初九得到上方资源，不能只用于个人享受，而应把增益转成能创造公共价值的大行动。","解说2_时位":"从时位看，本爻处在全卦发端，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：元吉無咎，下不厚事也。","象传译文":"《象传》说：元吉无咎，是因为下位者原本不宜承担过重事务，必须确有其能。","象传解说":"得到资源意味着责任同步增加。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **20 觀䷓**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"或益之十朋之龜，弗克違，永貞吉。王用享于帝，吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 十朋之龜：重大增益。永贞：长期守正。王用享于帝：王以此祭享上帝。","译文":"有人赠以价值十朋的大龟，无法拒绝；长久守正则吉。王用以祭享上帝，也吉。","解说1_经义":"六二柔中，能承受外来增益而不失原则。资源越大，越要通过长期正当用途证明其价值。","解说2_时位":"从时位看，本爻处在下卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的内卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：或益之，自外來也。","象传译文":"《象传》说：有人增益，是从外部而来。","象传解说":"增益有时并非自己争取，而是信誉与位置吸引。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **61 中孚䷼**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"益之用凶事，無咎。有孚中行，告公用圭。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 凶：凶险、不利。 孚：诚信、信实，也有取得信任之义。 用凶事：把增益用于处理灾难、非常事件。中行：行中道。告公用圭：以正式信物报告。","译文":"把所得增益用于处理凶险之事，可以无咎；有诚信、行中道，并以圭正式告公。","解说1_经义":"六三不宜把资源用于享乐，而适合投向危机处理。面对非常问题，需要透明报告和正式程序。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦震（动、发起、震动、雷）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：益用凶事，固有之也。","象传译文":"《象传》说：益用于凶事，是本来就应如此。","象传解说":"资源配置应优先解决系统性风险。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **37 家人䷤**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"中行，告公從，利用為依遷國。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 為依遷國：依托支持而迁移国都，指重大战略调整。","译文":"行中道，向公上报告并得到认可，适宜以此作为依托迁国。","解说1_经义":"六四处上下之间，是政策传导者。重大变革必须有沟通、授权和支撑，不能只靠个人判断。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的上卦之始、进入外部阶段位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：告公從，以益志也。","象传译文":"《象传》说：告公而从，是为了增益其志。","象传解说":"益的扩大需要制度化。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **25 無妄䷘**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"有孚惠心，勿問元吉。有孚惠我德。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 有孚：有诚信、取得信任。 吉：吉利；在占辞中表示趋向有利。 孚：诚信、信实，也有取得信任之义。 惠心：施惠之心。勿問元吉：不必占问即可知大吉。惠我德：众人也以德回应。","译文":"有诚信的惠人之心，不必询问便知大吉；众人也会诚信地回报我的德。","解说1_经义":"九五把益的核心从“资源”提升到“惠心”。真正的领导增益会形成信任回路：不是施舍，而是互相成就。","解说2_时位":"从时位看，本爻处在上卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：有孚惠心，勿問之矣；惠我德，大得志也。","象传译文":"《象传》说：有孚惠心，不必再问；惠我德，是大得志。","象传解说":"利他与自身德业在此并不冲突。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **27 頤䷚**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"莫益之，或擊之，立心勿恆，凶。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 莫益之：无人再增益。或擊之：反遭攻击。立心勿恆：立心不恒。","译文":"没有人增益他，反而有人攻击他；立心不能恒久，凶。","解说1_经义":"上九若只想不断获益、心志反复，关系便从支持转为反噬。益若没有稳定价值基础，会被视为索取。","解说2_时位":"从时位看，本爻处在全卦终位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：莫益之，偏辭也；或擊之，自外來也。","象传译文":"《象传》说：无人增益，是偏执之辞；有人攻击，是外部反作用到来。","象传解说":"只求增益而不惠人，最终失去增益来源。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **03 屯䷂**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"20 觀䷓","二爻":"61 中孚䷼","三爻":"37 家人䷤","四爻":"25 無妄䷘","五爻":"27 頤䷚","上爻":"03 屯䷂"}},{"卦序":43,"卦名":"夬","卦符":"䷪","全名":"澤天夬","上卦":"兌","下卦":"乾","卦辞":"夬，揚于王庭，孚號有厲。告自邑，不利即戎，利有攸往。","彖传":"《彖》曰：夬，決也，剛決柔也。健而說，決而和。揚于王庭，柔乘五剛也；孚號有厲，其危乃光也；告自邑不利即戎，所尚乃窮也；利有攸往，剛長乃終也。","大象":"《象》曰：澤上于天，夬。君子以施祿及下，居德則忌。","互卦":"01 乾䷀","错卦":"23 剝䷖","综卦":"44 姤䷫","爻":[{"爻位":"初九","原文":"壯于前趾，往不勝為咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 壯于前趾：脚趾强壮、急于前进。夬是决断，但初位尚未成熟。","译文":"脚趾强壮便急于向前，前往而不能胜，会成为过失。","解说1_经义":"夬卦需要决除问题，但初九提示：正确目标也可能因过早行动而失败。决断前必须有足够力量和联盟。","解说2_时位":"从时位看，本爻处在全卦发端，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不勝而往，咎也。","象传译文":"《象传》说：不能胜却前往，本身就是过失。","象传解说":"勇敢不能代替胜算评估。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **28 大過䷛**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"惕號，莫夜有戎，勿恤。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 惕號：戒惧而呼号警告。莫夜：暮夜。戎：兵患。","译文":"保持警惕并发出警告，即使夜里出现兵患，也不必忧惧。","解说1_经义":"九二得中，面对夬的冲突不靠莽撞，而靠预警与准备。风险被看见、被通报，突然事件就不再突然。","解说2_时位":"从时位看，本爻处在下卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦乾（健、刚健、主动、天）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：莫夜有戎，得中道也。","象传译文":"《象传》说：夜有兵戎而不惧，是因为九二得中。","象传解说":"决断之前的风险沟通非常重要。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **49 革䷰**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"壯于頄，有凶。君子夬夬，獨行遇雨，若濡有慍，無咎。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 凶：凶险、不利。 頄：颧骨、面部。壯于頄：强硬写在脸上。夬夬：坚决。遇雨若濡：与阴相遇被雨淋。慍：被人不满。","译文":"强硬显露在脸上会有凶；君子内心坚决，独自行事，遇雨被淋、遭人不满，却可无咎。","解说1_经义":"九三与上六正应，处在复杂关系中。真正的决断不必外表逞强；可以承担误解和短期不适，但要守住原则。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦乾（健、刚健、主动、天）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：君子夬夬，終無咎也。","象传译文":"《象传》说：君子夬夬，最终无咎。","象传解说":"外柔内决比公开挑衅更成熟。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **58 兌䷹**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"臀無膚，其行次且。牽羊悔亡，聞言不信。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 臀無膚：坐立不安。次且：趑趄难行。牽羊：牵羊随行，喻柔顺。聞言不信：听劝却不信。","译文":"臀部无肤，行走艰难；若能像牵羊那样顺势可悔亡，但听到劝告却不相信。","解说1_经义":"九四刚而不当位，处决断关键却缺乏柔顺，因而进退不适。最需要的正是听取意见、降低刚性。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦兌（说悦、交流、泽）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：其行次且，位不當也；聞言不信，聰不明也。","象传译文":"《象传》说：行次且是位置不当；闻言不信，是听觉不明。","象传解说":"决策失败常不是缺信息，而是不肯听。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **05 需䷄**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"莧陸夬夬，中行無咎。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 莧陸：一种柔脆植物，象征上六阴柔易决。中行：以中道执行。","译文":"像拔除苋陆一样坚决去除问题，行中道则无咎。","解说1_经义":"九五是夬卦主决者，具备位置与能力。但即便处理应当去除的问题，也要保持中道，防止决断变成滥除。","解说2_时位":"从时位看，本爻处在上卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦兌（说悦、交流、泽）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：中行無咎，中未光也。","象传译文":"《象传》说：中行无咎，但中道之光尚未完全彰显。","象传解说":"决断的正当性不仅看目标，还看程序和尺度。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **34 大壯䷡**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"無號，終有凶。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 無號：来不及呼号、无处求告。","译文":"已经无法呼号，最终有凶。","解说1_经义":"上六是夬卦唯一阴爻，被五阳决去。问题拖到众势皆决时，已很难再通过沟通挽回。","解说2_时位":"从时位看，本爻处在全卦终位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：無號之凶，終不可長也。","象传译文":"《象传》说：无号之凶，终究不可长久。","象传解说":"被清除的结构自身已经失去持续条件。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **01 乾䷀**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"28 大過䷛","二爻":"49 革䷰","三爻":"58 兌䷹","四爻":"05 需䷄","五爻":"34 大壯䷡","上爻":"01 乾䷀"}},{"卦序":44,"卦名":"姤","卦符":"䷫","全名":"天風姤","上卦":"乾","下卦":"巽","卦辞":"姤，女壯，勿用取女。","彖传":"《彖》曰：姤，遇也，柔遇剛也。勿用取女，不可與長也。天地相遇，品物咸章也；剛遇中正，天下大行也。姤之時義大矣哉。","大象":"《象》曰：天下有風，姤。后以施命誥四方。","互卦":"01 乾䷀","错卦":"24 復䷗","综卦":"43 夬䷪","爻":[{"爻位":"初六","原文":"繫于金柅，貞吉。有攸往，見凶。羸豕孚蹢躅。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有攸往：有所前往、有所作为。 吉：吉利；在占辞中表示趋向有利。 凶：凶险、不利。 往：前往、向外发展。 孚：诚信、信实，也有取得信任之义。 金柅：金属制动器，止车之具。羸豕：瘦猪。蹢躅：徘徊躁动。初六一阴初生。","译文":"用金属制动器把它系住，守正则吉；若任其前往会见凶。瘦猪虽弱，也已显出躁动徘徊之势。","解说1_经义":"姤卦是一阴突遇五阳。初六象征微小但可能快速扩大的因素，最适合在初期设置硬边界。","解说2_时位":"从时位看，本爻处在全卦发端，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：繫于金柅，柔道牽也。","象传译文":"《象传》说：系于金柅，是为了牵制柔道的扩展。","象传解说":"风险治理越早成本越低。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **01 乾䷀**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"包有魚，無咎，不利賓。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 包有魚：包中有鱼，象征资源在近处。不利賓：不宜扩散给外宾。","译文":"包中有鱼，无咎，但不宜拿去招待外宾。","解说1_经义":"九二与初六近比，能控制新出现的因素。此时适合内部管理，不宜过早外溢。","解说2_时位":"从时位看，本爻处在下卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：包有魚，義不及賓也。","象传译文":"《象传》说：包中有鱼，义理上不应让它影响宾客。","象传解说":"先把边界管理好，再谈扩展。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **33 遯䷠**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"臀無膚，其行次且，厲，無大咎。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 臀無膚、其行次且：与夬九四相似。厉无大咎。","译文":"臀部无肤，行动艰难；虽有危险，但没有大的灾咎。","解说1_经义":"九三想接近初六却隔着九二，欲遇而不得，形成焦躁。没有获得想要的关系未必是坏事，反而避免更大风险。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：其行次且，行未牽也。","象传译文":"《象传》说：行走艰难，是尚未被牵引过去。","象传解说":"未能得到，有时正是保护。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **06 訟䷅**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"包無魚，起凶。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 包無魚：包里没有鱼。起凶：因此引发凶险。","译文":"包中没有鱼，会由此引发凶险。","解说1_经义":"九四与初六正应，却被九二近取，象征应有的基层联系断裂。高位如果失去实际对象和民众基础，危机会突然出现。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦乾（健、刚健、主动、天）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：無魚之凶，遠民也。","象传译文":"《象传》说：无鱼之凶，是因为远离民众。","象传解说":"“远民”是此爻最重要的治理警告。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **57 巽䷸**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"以杞包瓜，含章，有隕自天。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 杞：杞树。包瓜：用杞叶包瓜，瓜柔易坏。含章：含藏文德。有隕自天：有事物从天降下。","译文":"用杞叶包住瓜，含藏美德；会有从天而降的机遇或变化。","解说1_经义":"九五中正，不直接追逐初六，而以德与制度包容、限制柔弱因素。能做好自身，外部转机自然到来。","解说2_时位":"从时位看，本爻处在上卦中位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：九五含章，中正也；有隕自天，志不舍命也。","象传译文":"《象传》说：九五含章，是中正；有陨自天，是志不舍天命。","象传解说":"成熟管理重在容纳与边界，而非占有。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **50 鼎䷱**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"姤其角，吝，無咎。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 姤其角：相遇到了角端，已无柔和接触空间。","译文":"相遇到角上，显得局促遗憾，但没有灾咎。","解说1_经义":"上九处姤之终，与初六距离最远。过度高亢使其难与新因素相遇，虽避免直接风险，也失去关系机会。","解说2_时位":"从时位看，本爻处在全卦终位，属于乾卦之位，乾的基本取象为“健、刚健、主动、天”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦乾（健、刚健、主动、天）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：姤其角，上窮吝也。","象传译文":"《象传》说：姤其角，是上位已经穷尽而有吝。","象传解说":"不接触可以无咎，却未必有成。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **28 大過䷛**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"01 乾䷀","二爻":"33 遯䷠","三爻":"06 訟䷅","四爻":"57 巽䷸","五爻":"50 鼎䷱","上爻":"28 大過䷛"}},{"卦序":45,"卦名":"萃","卦符":"䷬","全名":"澤地萃","上卦":"兌","下卦":"坤","卦辞":"萃，亨。王假有廟，利見大人，亨，利貞。用大牲吉，利有攸往。","彖传":"《彖》曰：萃，聚也。順以說，剛中而應，故聚也。王假有廟，致孝享也；利見大人亨，聚以正也；用大牲吉，利有攸往，順天命也。觀其所聚，而天地萬物之情可見矣。","大象":"《象》曰：澤上于地，萃。君子以除戎器，戒不虞。","互卦":"53 漸䷴","错卦":"26 大畜䷙","综卦":"46 升䷭","爻":[{"爻位":"初六","原文":"有孚不終，乃亂乃萃。若號，一握為笑，勿恤，往無咎。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 往：前往、向外发展。 孚：诚信、信实，也有取得信任之义。 有孚不終：诚信不能持续。乃亂乃萃：先乱后聚。一握為笑：一握之间转笑，形容误会迅速化解。","译文":"有诚信却不能坚持，因而先乱后聚；若真诚呼号，一握之间便可转笑，不必忧虑，前往无咎。","解说1_经义":"萃卦初六表明聚合初期信任不稳，关系容易因误解而散乱。直接表达真实意图，反而能迅速修复。","解说2_时位":"从时位看，本爻处在全卦发端，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：乃亂乃萃，其志亂也。","象传译文":"《象传》说：乃乱乃萃，是因为内心志向混乱。","象传解说":"聚众之前先统一真实意图。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **17 隨䷐**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"引吉，無咎，孚乃利用禴。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 孚：诚信、信实，也有取得信任之义。 引吉：相互牵引而聚。禴：薄祭，重诚不重物。","译文":"彼此牵引而聚合，吉，无咎；有诚信，即使用薄祭也适宜。","解说1_经义":"六二与九五相应，说明真正的聚合靠信任吸引，不靠豪华形式。","解说2_时位":"从时位看，本爻处在下卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦坤（顺、承载、包容、地）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：引吉無咎，中未變也。","象传译文":"《象传》说：引吉无咎，是因为居中而志未改变。","象传解说":"稳定信念使连接可持续。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **47 困䷮**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"萃如嗟如，無攸利，往無咎，小吝。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 利：适宜、有利。 往：前往、向外发展。 萃如嗟如：想聚而叹息。小吝：小有遗憾。","译文":"想聚合却只能叹息，没有明显利益；但前往仍可无咎，只是略有遗憾。","解说1_经义":"六三无正应，处在找不到归属的尴尬位置。与其原地抱怨，不如主动进入新的群体，即使不完美也比孤立好。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦坤（顺、承载、包容、地）的下卦之终、内外转换前位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：往無咎，上巽也。","象传译文":"《象传》说：前往无咎，是因为上方能够接纳。","象传解说":"聚合有时需要主动迈出第一步。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **31 咸䷞**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"大吉，無咎。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 九四“大吉无咎”，但阳居阴位。其吉依赖于聚众为公而非为私。","译文":"大吉，没有灾咎。","解说1_经义":"九四接近九五并承接群阴，处实际组织枢纽。能把众人聚向公共中心则大吉；若形成私人势力则结构上有隐患。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大吉無咎，位不當也。","象传译文":"《象传》说：大吉无咎，但位置本身并不当。","象传解说":"小象保留“不当位”，提醒不能只看吉辞而忽视权力边界。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **08 比䷇**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"萃有位，無咎。匪孚，元永貞，悔亡。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 孚：诚信、信实，也有取得信任之义。 萃有位：因位置而使人聚集。匪孚：尚未完全获信。元永貞：以根本、长久正固建立信任。","译文":"处在聚众之位，无咎；若尚未完全取得信任，就以长久正固去建立它，悔可消。","解说1_经义":"九五有职位不等于有信任。真正的凝聚需要长期一致行动，使“权位”转化为“可信中心”。","解说2_时位":"从时位看，本爻处在上卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：萃有位，志未光也。","象传译文":"《象传》说：萃有位而志未光，是信任尚未完全彰显。","象传解说":"组织归属不能只靠头衔。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **16 豫䷏**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"齎咨涕洟，無咎。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 齎咨：嗟叹。涕洟：流泪流涕。","译文":"叹息流泪，没有灾咎。","解说1_经义":"上六居聚之终却难以进入核心，情感上有孤立感。真实表达悲伤、求联结，至少不会构成过失。","解说2_时位":"从时位看，本爻处在全卦终位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦兌（说悦、交流、泽）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：齎咨涕洟，未安上也。","象传译文":"《象传》说：叹息流泪，是因为在上位仍未安定。","象传解说":"聚合的反面是被排除感，情绪也是真实信号。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **12 否䷋**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"17 隨䷐","二爻":"47 困䷮","三爻":"31 咸䷞","四爻":"08 比䷇","五爻":"16 豫䷏","上爻":"12 否䷋"}},{"卦序":46,"卦名":"升","卦符":"䷭","全名":"地風升","上卦":"坤","下卦":"巽","卦辞":"升，元亨，用見大人，勿恤。南征吉。","彖传":"《彖》曰：柔以時升，巽而順，剛中而應，是以大亨。用見大人勿恤，有慶也；南征吉，志行也。","大象":"《象》曰：地中生木，升。君子以順德，積小以高大。","互卦":"54 歸妹䷵","错卦":"25 無妄䷘","综卦":"45 萃䷬","爻":[{"爻位":"初六","原文":"允升，大吉。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 允升：确实可以上升。","译文":"诚信而顺势上升，大吉。","解说1_经义":"升卦初六虽为阴爻，却得到上方阳爻认可，说明起点不必强，只要方向与环境相合即可获得上升通道。","解说2_时位":"从时位看，本爻处在全卦发端，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：允升大吉，上合志也。","象传译文":"《象传》说：允升大吉，是与上方志向相合。","象传解说":"上升首先来自匹配，而非蛮力。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **11 泰䷊**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"孚乃利用禴，無咎。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 孚：诚信、信实，也有取得信任之义。 禴：薄祭，重诚。九二刚中。","译文":"有诚信，即使用薄祭也适宜，没有灾咎。","解说1_经义":"九二能力强但处升卦，不必用过度形式证明自己。真实、简洁的诚意足以取得信任。","解说2_时位":"从时位看，本爻处在下卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：九二之孚，有喜也。","象传译文":"《象传》说：九二之孚，会有喜庆。","象传解说":"升迁或发展中，可信比包装重要。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **15 謙䷎**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"升虛邑。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 虛邑：无人阻挡的城邑。","译文":"上升进入空虚无阻的城邑。","解说1_经义":"九三前方坤柔，无强阻，形成快速上升机会。机会顺畅时反而要防止把通道误认为永久能力。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：升虛邑，無所疑也。","象传译文":"《象传》说：升虚邑，没有什么可疑。","象传解说":"此阶段确实可进，但仍需为后续环境变化准备。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **07 師䷆**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"王用亨于岐山，吉無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 亨：通达、顺畅；古义又与享献相关。 王用亨于岐山：王在岐山祭享，象征得到秩序与神人认可。","译文":"王者在岐山举行祭享，吉而无咎。","解说1_经义":"六四上升到公共责任层，需要通过正当仪式、制度和授权获得合法性。升不只是个人能力增长，也是身份被共同体承认。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦坤（顺、承载、包容、地）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：王用亨于岐山，順事也。","象传译文":"《象传》说：王享于岐山，是顺应事理。","象传解说":"合法性使上升稳定。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **32 恆䷟**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"貞吉，升階。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 升階：一级一级登阶。","译文":"守正则吉，逐级登上台阶。","解说1_经义":"六五居尊而柔中，最理想的上升不是跳跃，而是有序递进。每一级都建立相应能力和责任，位置才稳。","解说2_时位":"从时位看，本爻处在上卦中位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：貞吉升階，大得志也。","象传译文":"《象传》说：守正而升阶，是大得其志。","象传解说":"长期成长重在可持续阶梯。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **48 井䷯**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"冥升，利于不息之貞。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 冥升：在昏暗中仍不停上升。不息之貞：把“不停”用于守正而非追位。","译文":"在昏暗中仍想上升；若把不息之力用于守正，才有利。","解说1_经义":"上六已经看不清前方，却仍有上升惯性。此时应把进取欲从外在位置转向内在修养。","解说2_时位":"从时位看，本爻处在全卦终位，属于坤卦之位，坤的基本取象为“顺、承载、包容、地”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦坤（顺、承载、包容、地）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：冥升在上，消不富也。","象传译文":"《象传》说：冥升在上，是消耗而不能真正富足。","象传解说":"上升若没有终点意识，会从增长变成耗损。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **18 蠱䷑**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"11 泰䷊","二爻":"15 謙䷎","三爻":"07 師䷆","四爻":"32 恆䷟","五爻":"48 井䷯","上爻":"18 蠱䷑"}},{"卦序":47,"卦名":"困","卦符":"䷮","全名":"澤水困","上卦":"兌","下卦":"坎","卦辞":"困，亨，貞，大人吉，無咎。有言不信。","彖传":"《彖》曰：困，剛掩也。險以說，困而不失其所，亨，其唯君子乎。貞大人吉，以剛中也；有言不信，尚口乃窮也。","大象":"《象》曰：澤無水，困。君子以致命遂志。","互卦":"37 家人䷤","错卦":"22 賁䷕","综卦":"48 井䷯","爻":[{"爻位":"初六","原文":"臀困于株木，入于幽谷，三歲不覿。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 株木：树桩。幽谷：幽暗山谷。三岁不觌：长久见不到人。","译文":"臀部困在树桩上，又进入幽谷，很久不能见人。","解说1_经义":"困卦初六柔弱无援，最大风险是因困难而进一步自我孤立。陷入困境后若切断信息与支持，困会加深。","解说2_时位":"从时位看，本爻处在全卦发端，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：入于幽谷，幽不明也。","象传译文":"《象传》说：进入幽谷，是幽暗不明。","象传解说":"困境中的第一任务是恢复可见性与连接。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **58 兌䷹**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"困于酒食，朱紱方來，利用亨祀，征凶，無咎。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 利：适宜、有利。 征：前往、出行、采取进取行动。 亨：通达、顺畅；古义又与享献相关。 困于酒食：物质并不匮乏，却困在享用或应酬。朱紱：高位礼服。亨祀：祭享。","译文":"困在酒食之中，身着朱绂者将来；适宜祭祀，若贸然出征则凶，但无咎。","解说1_经义":"九二的困不是贫乏，而是资源多却行动受限。此时应等待合适授权和时机，而非用资源强推。","解说2_时位":"从时位看，本爻处在下卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦坎（险、陷、流行、水）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：困于酒食，中有慶也。","象传译文":"《象传》说：困于酒食，居中仍有庆成。","象传解说":"“有资源但不能动”也是一种困。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **45 萃䷬**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"困于石，據于蒺藜，入于其宮，不見其妻，凶。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 困于石：受硬障碍压迫。据于蒺藜：坐在带刺植物上。入宫不见妻：内外皆无安处。","译文":"被石头困住，又坐在蒺藜上；回家也见不到妻子，凶。","解说1_经义":"六三选择了错误支点：上压、下刺、内无应。困难时若每一步都基于焦躁而非判断，会把局部问题变成全方位困局。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦坎（险、陷、流行、水）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：據于蒺藜，乘剛也；入于其宮不見其妻，不祥也。","象传译文":"《象传》说：据于蒺藜，是因乘刚；入宫不见妻，是不祥。","象传解说":"结构无应、位置不当，使此爻几乎没有缓冲。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **28 大過䷛**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"來徐徐，困于金車，吝，有終。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 金車：华贵或坚固之车。來徐徐：救援来得慢。","译文":"来得缓慢，又受金车牵困，虽有遗憾，最终仍有结果。","解说1_经义":"九四与初六相应，却被九二阻隔。帮助并非没有，只是路径受权力与资源结构限制。耐心穿过阻碍，仍可有终。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：來徐徐，志在下也；雖不當位，有與也。","象传译文":"《象传》说：来徐徐，是志在下方；虽不当位，却有应援。","象传解说":"困中最重要的是确认支持是否真实存在。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **29 坎䷜**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"劓刖，困于赤紱，乃徐有說，利用祭祀。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 劓刖：割鼻断足，极言受制。赤紱：高位服饰。說：通“脱”，解除。","译文":"像遭割鼻断足般受困，又受赤绂之位牵制；但会逐渐解脱，适宜祭祀。","解说1_经义":"九五居尊也会困：职位越高，责任与制度束缚越多。此爻不是立刻突破，而是徐徐解除。","解说2_时位":"从时位看，本爻处在上卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦兌（说悦、交流、泽）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：劓刖，志未得也；乃徐有說，以中直也；利用祭祀，受福也。","象传译文":"《象传》说：劓刖是志未得；徐有说，是因中直；祭祀可受福。","象传解说":"中直是高压位置中的恢复机制。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **40 解䷧**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"困于葛藟，于臲卼，曰動悔。有悔，征吉。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 征：前往、出行、采取进取行动。 葛藟：蔓藤缠绕。臲卼：动摇不安。曰动悔：一动就怕后悔。有悔征吉：意识到悔而行动反吉。","译文":"被藤蔓缠绕，又处摇摇欲坠之地；若总说“一动就后悔”，便更困。真正有悔悟而采取行动，前往反吉。","解说1_经义":"上六的困已到极点，心理恐惧成为最后锁链。外部条件未必能先改变，必须先打破“我不能动”的认知。","解说2_时位":"从时位看，本爻处在全卦终位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦兌（说悦、交流、泽）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：困于葛藟，未當也；動悔有悔，吉行也。","象传译文":"《象传》说：困于葛藟，是位置未当；因悔而行动，便可吉。","象传解说":"困极之变往往从心理决定开始。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **06 訟䷅**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"58 兌䷹","二爻":"45 萃䷬","三爻":"28 大過䷛","四爻":"29 坎䷜","五爻":"40 解䷧","上爻":"06 訟䷅"}},{"卦序":48,"卦名":"井","卦符":"䷯","全名":"水風井","上卦":"坎","下卦":"巽","卦辞":"井，改邑不改井，無喪無得。往來井井。汔至亦未繘井，羸其瓶，凶。","彖传":"《彖》曰：巽乎水而上水，井。井養而不窮也。改邑不改井，乃以剛中也。汔至亦未繘井，未有功也；羸其瓶，是以凶也。","大象":"《象》曰：木上有水，井。君子以勞民勸相。","互卦":"38 睽䷥","错卦":"21 噬嗑䷔","综卦":"47 困䷮","爻":[{"爻位":"初六","原文":"井泥不食，舊井無禽。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 井泥：井底淤泥。不食：水不能饮。舊井無禽：连鸟兽也不来。","译文":"井中全是淤泥，水不可饮；旧井荒废，连禽鸟也不来。","解说1_经义":"井卦讲公共资源。初六表示资源本在，却因维护不足失去功能。价值不是“拥有井”，而是井能持续提供清水。","解说2_时位":"从时位看，本爻处在全卦发端，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：井泥不食，下也；舊井無禽，時舍也。","象传译文":"《象传》说：井泥不食，是位置最低而废；旧井无禽，是被时代舍弃。","象传解说":"资源若不维护，会从资产变负担。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **05 需䷄**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"井谷射鮒，甕敝漏。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 井谷射鮒：井底小水仅够小鱼。甕敝漏：汲水器破漏。","译文":"井底的水只够小鱼活动，汲水的瓦罐又破漏。","解说1_经义":"九二有水却无法有效输出，说明能力存在但工具、渠道失效。组织常不是缺资源，而是输送系统坏了。","解说2_时位":"从时位看，本爻处在下卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：井谷射鮒，無與也。","象传译文":"《象传》说：井谷射鲋，是因为没有相应支持。","象传解说":"改善基础设施比继续增加资源更重要。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **39 蹇䷦**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"井渫不食，為我心惻，可用汲。王明，並受其福。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 井渫：井已清理。心惻：心中惋惜。王明：有明主识用。","译文":"井已淘清却无人饮用，令人惋惜；若能汲取使用，明王与众人都会受福。","解说1_经义":"九三象征“有能力而未被使用”。最重要的不是继续证明水有多清，而是找到能够识别和调用它的制度。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：井渫不食，行惻也；求王明，受福也。","象传译文":"《象传》说：井渫不食，使人心惻；若王明而用之，众皆受福。","象传解说":"人才和资源被看见，是治理问题。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **29 坎䷜**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"井甃，無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 甃：用砖石修井壁。","译文":"修砌井壁，没有灾咎。","解说1_经义":"六四不急着取水，而先修基础结构。井的可持续性依赖维护。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦坎（险、陷、流行、水）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：井甃無咎，修井也。","象传译文":"《象传》说：井甃无咎，是在修整井。","象传解说":"基础工程看似不产出，却决定长期产出。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **28 大過䷛**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"井冽，寒泉食。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 井冽：井水清冽。寒泉食：清凉泉水可饮。","译文":"井水清冽，寒泉可供饮用。","解说1_经义":"九五中正，井的功能终于完整发挥。公共资源的理想状态是质量可靠、人人可用。","解说2_时位":"从时位看，本爻处在上卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦坎（险、陷、流行、水）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：寒泉之食，中正也。","象传译文":"《象传》说：寒泉可以饮用，是因为九五中正。","象传解说":"位置、质量与公共使用在此统一。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **46 升䷭**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"井收勿幕，有孚元吉。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 有孚：有诚信、取得信任。 吉：吉利；在占辞中表示趋向有利。 孚：诚信、信实，也有取得信任之义。 井收：井口修成或汲水完成。勿幕：不要覆盖。元吉。","译文":"井已修成，不要把井口盖住；有诚信，大吉。","解说1_经义":"上六强调资源成熟后必须开放。把优质公共资源封闭起来，违背井卦“养而不穷”的意义。","解说2_时位":"从时位看，本爻处在全卦终位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：元吉在上，大成也。","象传译文":"《象传》说：元吉在上，是井道大成。","象传解说":"井的最终价值不在所有权，而在持续可获得性。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **57 巽䷸**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"05 需䷄","二爻":"39 蹇䷦","三爻":"29 坎䷜","四爻":"28 大過䷛","五爻":"46 升䷭","上爻":"57 巽䷸"}},{"卦序":49,"卦名":"革","卦符":"䷰","全名":"澤火革","上卦":"兌","下卦":"離","卦辞":"革，己日乃孚，元亨利貞，悔亡。","彖传":"《彖》曰：革，水火相息，二女同居，其志不相得，曰革。己日乃孚，革而信也。文明以說，大亨以正，革而當，其悔乃亡。天地革而四時成；湯武革命，順乎天而應乎人。革之時大矣哉。","大象":"《象》曰：澤中有火，革。君子以治曆明時。","互卦":"44 姤䷫","错卦":"04 蒙䷃","综卦":"50 鼎䷱","爻":[{"爻位":"初九","原文":"鞏用黃牛之革。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 鞏：牢固约束。黃牛之革：坚韧牛皮，黄取中义。革卦初爻尚不到可以正式变革之时。","译文":"先用黄牛皮把它牢牢约束起来。","解说1_经义":"改革之初最怕“为了改革而改革”。初九要求先把冲动约束住，确认问题、时机和合法性；尚未形成广泛信任前，不宜轻动旧制。","解说2_时位":"从时位看，本爻处在全卦发端，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦離（明、附丽、文明、火）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：鞏用黃牛，不可以有為也。","象传译文":"《象传》说：用黄牛之革牢固约束，是此时还不可以有所作为。","象传解说":"真正的革从克制开始，而不是从破坏开始。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **31 咸䷞**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"己日乃革之，征吉，無咎。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 征：前往、出行、采取进取行动。 己日：变革条件成熟、取得信任之后的时日；历来对“己”有多种训释。乃革之：然后实行改革。","译文":"到了可以取得信任的时机，再进行变革；前进则吉，无咎。","解说1_经义":"六二得中正，说明改革必须等到理由、时机和支持都成熟。不是越快越好，而是“己日乃革”。","解说2_时位":"从时位看，本爻处在下卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的内卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：己日革之，行有嘉也。","象传译文":"《象传》说：到了适当时日实行变革，行动会有嘉庆。","象传解说":"改革的正当性包括时机正当。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **43 夬䷪**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"征凶，貞厲。革言三就，有孚。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 凶：凶险、不利。 征：前往、出行、采取进取行动。 孚：诚信、信实，也有取得信任之义。 革言三就：改革主张经过多次讨论、确认而成立。征凶：贸然推进凶。","译文":"急着推进改革会凶，固执也危险；改革意见经过反复论证、形成共识后，才有诚信基础。","解说1_经义":"九三刚而不中，最容易把正确方向推成过激行动。重大改变必须经过多轮验证、沟通和修正。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：革言三就，又何之矣。","象传译文":"《象传》说：革言三就，已经反复形成共识，又还能随意往哪里改呢？","象传解说":"改革一旦充分论证，就从个人主张变成公共承诺。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **17 隨䷐**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"悔亡，有孚改命，吉。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 有孚：有诚信、取得信任。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 孚：诚信、信实，也有取得信任之义。 改命：改变旧有命令、制度。九四已进入上卦，时机成熟。","译文":"悔恨消失；有诚信地改变旧命，吉。","解说1_经义":"九四的“革”已经有行动条件。与九三相比，关键差别不只是位置，而是“有孚”：变革开始被相信。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦兌（说悦、交流、泽）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：改命之吉，信志也。","象传译文":"《象传》说：改命之吉，是因为变革志向取得信任。","象传解说":"制度变化要先建立可信的理由和执行预期。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **63 既濟䷾**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"大人虎變，未占有孚。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 大人：有德有位、有能力担当大事之人；不宜简单等同现代某一具体身份。 有孚：有诚信、取得信任。 孚：诚信、信实，也有取得信任之义。 虎變：虎毛秋季更新而纹理鲜明，喻大人变革显著、有章法。未占有孚：不用占问也可获信。","译文":"大人像虎纹焕新一样实行明显变革，不必占问便能取得信任。","解说1_经义":"九五中正，是革卦完成度最高的位置。成熟改革不靠口号，而是结果、制度和人格都清楚可见。","解说2_时位":"从时位看，本爻处在上卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：大人虎變，其文炳也。","象传译文":"《象传》说：大人虎变，是其文采制度炳然可见。","象传解说":"“文炳”说明改革必须形成清晰的新秩序，而非只摧毁旧秩序。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **55 豐䷶**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"君子豹變，小人革面，征凶，居貞吉。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 吉：吉利；在占辞中表示趋向有利。 凶：凶险、不利。 征：前往、出行、采取进取行动。 豹變：豹纹变化，较虎细密。革面：只改变外在面貌。征凶：革已成，不宜继续推进。","译文":"君子像豹纹一样完成细致变化，小人也改变面貌；再继续征进则凶，安居守正则吉。","解说1_经义":"上六是改革完成后的巩固期。君子已内外更新，小人可能只表面适应；此时重点是稳定新秩序，而非继续制造运动。","解说2_时位":"从时位看，本爻处在全卦终位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦兌（说悦、交流、泽）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：君子豹變，其文蔚也；小人革面，順以從君也。","象传译文":"《象传》说：君子豹变，文采蔚然；小人革面，是顺从新秩序。","象传解说":"变革成功后要从“破”切换到“守”。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **13 同人䷌**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"31 咸䷞","二爻":"43 夬䷪","三爻":"17 隨䷐","四爻":"63 既濟䷾","五爻":"55 豐䷶","上爻":"13 同人䷌"}},{"卦序":50,"卦名":"鼎","卦符":"䷱","全名":"火風鼎","上卦":"離","下卦":"巽","卦辞":"鼎，元吉，亨。","彖传":"《彖》曰：鼎，象也。以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎剛，是以元亨。","大象":"《象》曰：木上有火，鼎。君子以正位凝命。","互卦":"43 夬䷪","错卦":"03 屯䷂","综卦":"49 革䷰","爻":[{"爻位":"初六","原文":"鼎顛趾，利出否。得妾以其子，無咎。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 鼎顛趾：鼎倒置、足朝上。出否：倒出鼎中秽物。得妾以其子：因子而纳妾，古代家族语境。","译文":"鼎倒过来，反而便于倒出污物；如因子而纳妾，虽非常却可无咎。","解说1_经义":"鼎卦讲更新与养贤。初六先清空旧污，形式上的颠倒未必是坏事；只要有明确功能，打破常态可以成为重建前提。","解说2_时位":"从时位看，本爻处在全卦发端，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：鼎顛趾，未悖也；利出否，以從貴也。","象传译文":"《象传》说：鼎顛趾并不悖理；倒出污物，是为了接续更有价值的事物。","象传解说":"更新往往先经历一次“倒置”。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **14 大有䷍**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"鼎有實，我仇有疾，不我能即，吉。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 鼎有實：鼎中有实物。我仇有疾：与我相对者有问题。不我能即：不能接近、侵扰我。","译文":"鼎中有充实之物；对方虽有疾患，也不能接近我，吉。","解说1_经义":"九二得中，内部资源充实，外部负面因素便难以侵入。鼎之“实”不仅是物质，也可指能力、德行与系统稳定。","解说2_时位":"从时位看，本爻处在下卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦巽（入、顺入、渗透、风木）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：鼎有實，慎所之也；我仇有疾，終無尤也。","象传译文":"《象传》说：鼎中有实，应谨慎选择前往方向；对方有疾，最终不能造成过失。","象传解说":"内部充实是抵御外扰的最好方法。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **56 旅䷷**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"鼎耳革，其行塞，雉膏不食。方雨虧悔，終吉。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 鼎耳革：鼎耳变形，无法用铉提起。雉膏：美食。方雨：将雨，阴阳调和。","译文":"鼎耳出了问题，行动受阻，美好的雉膏也吃不到；待到阴阳和合如雨降，悔可减，最终吉。","解说1_经义":"九三有内容却缺接口，典型的“资源好、调用机制坏”。解决方法不是继续增加内容，而是修复连接与使用机制。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：鼎耳革，失其義也。","象传译文":"《象传》说：鼎耳革，是失去了应有的配合之义。","象传解说":"系统价值取决于能否被有效调用。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **64 未濟䷿**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"鼎折足，覆公餗，其形渥，凶。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 折足：鼎足折断。公餗：王公鼎中食物。形渥：污秽狼藉，古注有不同训释。","译文":"鼎足折断，王公的食物倾覆，弄得狼藉，凶。","解说1_经义":"九四处实际承载位置却能力、结构不匹配。承担重大公共任务时，基础部件失败会造成整体事故。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：覆公餗，信如何也。","象传译文":"《象传》说：倾覆公餗，信用和责任该如何交代？","象传解说":"“信如何”把工程失败提升为责任伦理。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **18 蠱䷑**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"鼎黃耳金鉉，利貞。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 黃耳金鉉：黄色鼎耳、金属鼎杠，皆美而中正。","译文":"鼎有黄色的耳和金铉，适宜守正。","解说1_经义":"六五柔中居尊，已经具备良好接口，并能由上九之刚来提举。治理成熟体现为资源、工具、人才配合。","解说2_时位":"从时位看，本爻处在上卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的上卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：鼎黃耳，中以為實也。","象传译文":"《象传》说：鼎黄耳，是以中道为其实质。","象传解说":"中而可用，比单纯华美更重要。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **44 姤䷫**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"鼎玉鉉，大吉，無不利。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 利：适宜、有利。 玉鉉：玉制鼎杠，刚柔相济、贵而不失温润。","译文":"鼎配上玉铉，大吉，无所不利。","解说1_经义":"上九以刚居柔位，刚而能温，是鼎卦理想完成态。工具不只强，还要与所承之物相适配。","解说2_时位":"从时位看，本爻处在全卦终位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦離（明、附丽、文明、火）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：玉鉉在上，剛柔節也。","象传译文":"《象传》说：玉铉在上，是刚柔得到节制调和。","象传解说":"鼎最终完成于“刚柔节”，而非一味刚强。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **32 恆䷟**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"14 大有䷍","二爻":"56 旅䷷","三爻":"64 未濟䷿","四爻":"18 蠱䷑","五爻":"44 姤䷫","上爻":"32 恆䷟"}},{"卦序":51,"卦名":"震","卦符":"䷲","全名":"震為雷","上卦":"震","下卦":"震","卦辞":"震，亨。震來虩虩，笑言啞啞。震驚百里，不喪匕鬯。","彖传":"《彖》曰：震亨。震來虩虩，恐致福也；笑言啞啞，後有則也。震驚百里，驚遠而懼邇也。出可以守宗廟社稷，以為祭主也。","大象":"《象》曰：洊雷，震。君子以恐懼修省。","互卦":"39 蹇䷦","错卦":"57 巽䷸","综卦":"52 艮䷳","爻":[{"爻位":"初九","原文":"震來虩虩，後笑言啞啞，吉。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 虩虩：恐惧不安貌。啞啞：笑声。震来先惧后安。","译文":"雷震到来时先恐惧警惕，后来才能从容谈笑，吉。","解说1_经义":"震卦的价值不在“毫无恐惧”，而在恐惧触发正确准备。能被风险唤醒的人，事后才有真正从容。","解说2_时位":"从时位看，本爻处在全卦发端，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦震（动、发起、震动、雷）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：震來虩虩，恐致福也；笑言啞啞，後有則也。","象传译文":"《象传》说：震来虩虩，是恐惧带来福；后来笑言，是行为恢复法则。","象传解说":"适度恐惧是一种保护机制。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **16 豫䷏**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"震來厲，億喪貝，躋于九陵，勿逐，七日得。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 億喪貝：大量财物似将丧失；“億”古义训释不一。躋于九陵：登高避险。七日得：之后复得。","译文":"震动来得危险，似乎丧失财货，应登上高陵避险；不必追逐，过后会重新得到。","解说1_经义":"六二面对突发事件，优先级是人身与系统安全，而非立刻追回资产。先避险，损失有机会恢复。","解说2_时位":"从时位看，本爻处在下卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦震（动、发起、震动、雷）的内卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：震來厲，乘剛也。","象传译文":"《象传》说：震来厉，是因为六二乘刚。","象传解说":"危机中最忌为财物返回危险现场。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **54 歸妹䷵**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"震蘇蘇，震行無眚。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 蘇蘇：惊惧不安、神气散乱。一说苏醒貌。","译文":"震动使人惶惶不安；若因此及时行动调整，可以无灾。","解说1_经义":"六三虽受惊较重，但恐惧若能转化为行动，就具有积极意义。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦震（动、发起、震动、雷）的下卦之终、内外转换前位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：震蘇蘇，位不當也。","象传译文":"《象传》说：震苏苏，是因位置不当。","象传解说":"位置不稳时，更需把情绪转成具体应对。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **55 豐䷶**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"震遂泥。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 遂泥：陷入泥中，震动之力受阻。","译文":"震动陷在泥里，难以振作。","解说1_经义":"九四阳动却被上下柔爻包围，行动力被环境吸收。危机响应若缺少通道，再强的动力也会陷住。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦震（动、发起、震动、雷）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：震遂泥，未光也。","象传译文":"《象传》说：震遂泥，是其作用未能光大。","象传解说":"行动系统需要清除阻塞。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **24 復䷗**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"震往來厲，億無喪，有事。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 往來厲：来去都有危险。億無喪：大体没有真正损失。有事：仍有事务可办。","译文":"震动来去都带危险，但不会造成根本损失，仍有事情可以处理。","解说1_经义":"六五居中，危机反复却不至失控。领导者的任务是在持续震荡中维持核心功能。","解说2_时位":"从时位看，本爻处在上卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦震（动、发起、震动、雷）的上卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：震往來厲，危行也；其事在中，大無喪也。","象传译文":"《象传》说：往来皆厉，是行动危险；核心事务仍在，所以没有大的丧失。","象传解说":"韧性不是无震荡，而是震荡中不中断关键功能。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **17 隨䷐**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"震索索，視矍矍，征凶。震不于其躬，于其鄰，無咎。婚媾有言。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 征：前往、出行、采取进取行动。 索索：恐惧颤栗。矍矍：惊视不安。震不于其躬于其鄰：灾还未到自身，已发生在邻近。","译文":"震得人颤抖、惊视；若贸然前往凶。震尚未到自己而已到邻居，能提前戒备则无咎；婚姻关系可能有议论。","解说1_经义":"上六虽然恐惧过度，却提供重要的“邻灾预警”思维：别人发生的问题可以成为自己的演练信号。","解说2_时位":"从时位看，本爻处在全卦终位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦震（动、发起、震动、雷）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：震索索，未得中也；雖凶無咎，畏鄰戒也。","象传译文":"《象传》说：震索索，是未得中；虽凶可无咎，是能从邻近事件取得戒惧。","象传解说":"从别人的事故学习，是低成本风险管理。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **21 噬嗑䷔**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"16 豫䷏","二爻":"54 歸妹䷵","三爻":"55 豐䷶","四爻":"24 復䷗","五爻":"17 隨䷐","上爻":"21 噬嗑䷔"}},{"卦序":52,"卦名":"艮","卦符":"䷳","全名":"艮為山","上卦":"艮","下卦":"艮","卦辞":"艮，艮其背，不獲其身；行其庭，不見其人，無咎。","彖传":"《彖》曰：艮，止也。時止則止，時行則行，動靜不失其時，其道光明。艮其止，止其所也。上下敵應，不相與也。是以不獲其身，行其庭不見其人，無咎也。","大象":"《象》曰：兼山，艮。君子以思不出其位。","互卦":"40 解䷧","错卦":"58 兌䷹","综卦":"51 震䷲","爻":[{"爻位":"初六","原文":"艮其趾，無咎，利永貞。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 艮其趾：止住脚趾。永贞：长久守正。","译文":"止住脚步，不再妄进，无咎；宜长久守正。","解说1_经义":"艮卦初六在行动刚起时就止。很多错误若能在第一步停下，几乎没有纠错成本。","解说2_时位":"从时位看，本爻处在全卦发端，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦艮（止、界限、山）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：艮其趾，未失正也。","象传译文":"《象传》说：艮其趾，是还没有失去正道。","象传解说":"止得早，所以无需付出更大代价。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **22 賁䷕**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"艮其腓，不拯其隨，其心不快。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 腓：小腿肚。不拯其隨：不能救助所随之人或不能止住上部行动。","译文":"止住小腿，却不能挽救自己跟随的对象，内心不快。","解说1_经义":"六二自己能停，却受九三主导结构影响，无法改变整体。个人克制不一定立即改变团队方向。","解说2_时位":"从时位看，本爻处在下卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦艮（止、界限、山）的内卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不拯其隨，未退聽也。","象传译文":"《象传》说：不能拯其所随，是因为上方尚未退而听从。","象传解说":"止还需要组织层级配合。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **18 蠱䷑**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"艮其限，列其夤，厲薰心。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 限：腰部。夤：脊背肌肉。列：裂。薰心：痛迫于心。","译文":"止在腰际，像脊肉被裂开，危险之感熏灼内心。","解说1_经义":"九三刚止过度，把本来应流动的身体硬截断，形成内部撕裂。艮不是僵死；该动处强止，同样危险。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦艮（止、界限、山）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：艮其限，危薰心也。","象传译文":"《象传》说：艮其限，危险足以熏心。","象传解说":"止必须合乎身体与系统自然节律。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **23 剝䷖**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"艮其身，無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 艮其身：止住自身，不扩及他人。","译文":"止住自己的身体，没有灾咎。","解说1_经义":"六四开始把“止”转为自我边界管理。与其控制他人，不如先管住自己能管的部分。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦艮（止、界限、山）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：艮其身，止諸躬也。","象传译文":"《象传》说：艮其身，是止于自身。","象传解说":"这是非常现代的边界原则：先控制可控变量。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **56 旅䷷**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"艮其輔，言有序，悔亡。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 輔：口颊。言有序：言语有条理、次序。","译文":"止住口舌，使言语有次序，悔恨消失。","解说1_经义":"六五得中，艮进一步落实为言语节制。很多风险不是行动造成，而是失言造成。","解说2_时位":"从时位看，本爻处在上卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦艮（止、界限、山）的上卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：艮其輔，以中正也。","象传译文":"《象传》说：艮其辅，是因为居中而正。","象传解说":"说话前的“止”是理性表达的前提。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **53 漸䷴**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"敦艮，吉。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 敦艮：厚实地止、安止。","译文":"敦厚安止，吉。","解说1_经义":"上九走到艮之终，止不再是临时制动，而成为稳定人格：知道边界、接受边界、安于边界。","解说2_时位":"从时位看，本爻处在全卦终位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦艮（止、界限、山）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：敦艮之吉，以厚終也。","象传译文":"《象传》说：敦艮之吉，是以厚德完成终局。","象传解说":"最高层次的止不是压抑，而是内在安定。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **15 謙䷎**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"22 賁䷕","二爻":"18 蠱䷑","三爻":"23 剝䷖","四爻":"56 旅䷷","五爻":"53 漸䷴","上爻":"15 謙䷎"}},{"卦序":53,"卦名":"漸","卦符":"䷴","全名":"風山漸","上卦":"巽","下卦":"艮","卦辞":"漸，女歸吉，利貞。","彖传":"《彖》曰：漸之進也，女歸吉也。進得位，往有功也；進以正，可以正邦也。其位剛得中也。止而巽，動不窮也。","大象":"《象》曰：山上有木，漸。君子以居賢德善俗。","互卦":"64 未濟䷿","错卦":"54 歸妹䷵","综卦":"54 歸妹䷵","爻":[{"爻位":"初六","原文":"鴻漸于干，小子厲。有言，無咎。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 鴻：大雁，渐卦六爻均以鸿雁迁徙为喻。干：水岸。小子厉：年幼者有危险。有言：有议论。","译文":"鸿雁渐渐来到水岸，年轻者有危险；虽有议论，仍无咎。","解说1_经义":"渐强调按次序推进。初六刚上岸，环境陌生，弱小者风险较高；有些不理解和议论是早期成本。","解说2_时位":"从时位看，本爻处在全卦发端，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦艮（止、界限、山）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：小子之厲，義無咎也。","象传译文":"《象传》说：小子之厉，从义理上仍无咎。","象传解说":"起步慢、受质疑不等于方向错误。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **37 家人䷤**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"鴻漸于磐，飲食衎衎，吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 磐：大石。衎衎：和乐从容。","译文":"鸿雁渐进到磐石，饮食和乐，吉。","解说1_经义":"六二得中并与九五相应，找到较稳定平台。渐进过程中需要阶段性停留、补充资源，而不是持续赶路。","解说2_时位":"从时位看，本爻处在下卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦艮（止、界限、山）的内卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：飲食衎衎，不素飽也。","象传译文":"《象传》说：饮食衎衎，不是白白吃饱。","象传解说":"休整是为了更长远的进程。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **57 巽䷸**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"鴻漸于陸，夫征不復，婦孕不育，凶；利禦寇。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 利：适宜、有利。 征：前往、出行、采取进取行动。 陸：高平地。夫征不復、婦孕不育：关系与生育失序。禦寇：防御外患。","译文":"鸿雁渐到陆地；丈夫出征不回，妻子怀孕却难育，凶；适宜防御寇患。","解说1_经义":"九三刚而过进，渐进节奏被打破，内部关系遂失衡。此时不适合继续扩张，应把力量转向防守。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦艮（止、界限、山）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：夫征不復，離群丑也；婦孕不育，失其道也；利用禦寇，順相保也。","象传译文":"《象传》说：夫征不复，是离开群类；妇孕不育，是失其道；利御寇，是顺势相保。","象传解说":"渐卦最忌跳级。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **20 觀䷓**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"鴻漸于木，或得其桷，無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 木：树木。桷：平直树枝，可供栖息。","译文":"鸿雁渐到树上，若找到平直枝桷栖息，可无咎。","解说1_经义":"六四进入上卦，环境未必天然适合，但可以通过寻找合适支点适应。渐进并不要求完美条件。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：或得其桷，順以巽也。","象传译文":"《象传》说：或得其桷，是能顺势而入。","象传解说":"适应能力让过渡阶段可持续。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **33 遯䷠**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"鴻漸于陵，婦三歲不孕，終莫之勝，吉。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 陵：高丘。三歲不孕：长期阻隔。終莫之勝：最终没有什么能阻挡。","译文":"鸿雁渐到高陵；妇人多年不孕，但最终无人能阻挡其结果，吉。","解说1_经义":"九五中正，目标已高，但与六二之间有阻隔。真正的长期关系或事业可能经历延迟，只要结构正当，最终仍可成。","解说2_时位":"从时位看，本爻处在上卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：終莫之勝吉，得所願也。","象传译文":"《象传》说：最终无人能胜，是终于实现所愿。","象传解说":"渐的时间尺度往往比即时欲望更长。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **52 艮䷳**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"鴻漸于陸，其羽可用為儀，吉。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 上九传统多本作“鴻漸于陸”，王弼本等亦有异文讨论；其羽可用為儀：羽毛可作礼仪装饰。","译文":"鸿雁渐进至极高之处，它的羽毛可以用作礼仪典范，吉。","解说1_经义":"上九已超出个人进退，长期渐进形成的品格本身成为他人可以仿效的“仪”。","解说2_时位":"从时位看，本爻处在全卦终位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：其羽可用為儀吉，不可亂也。","象传译文":"《象传》说：其羽可用为仪而吉，是因为不可被扰乱。","象传解说":"渐之终由个人成长转为文化示范。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **39 蹇䷦**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"37 家人䷤","二爻":"57 巽䷸","三爻":"20 觀䷓","四爻":"33 遯䷠","五爻":"52 艮䷳","上爻":"39 蹇䷦"}},{"卦序":54,"卦名":"歸妹","卦符":"䷵","全名":"雷澤歸妹","上卦":"震","下卦":"兌","卦辞":"歸妹，征凶，無攸利。","彖传":"《彖》曰：歸妹，天地之大義也。天地不交而萬物不興。歸妹，人之終始也。說以動，所歸妹也。征凶，位不當也；無攸利，柔乘剛也。","大象":"《象》曰：澤上有雷，歸妹。君子以永終知敝。","互卦":"63 既濟䷾","错卦":"53 漸䷴","综卦":"53 漸䷴","爻":[{"爻位":"初九","原文":"歸妹以娣，跛能履，征吉。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 征：前往、出行、采取进取行动。 娣：古代随嫁之妹。跛能履：虽跛尚能行。","译文":"归妹以娣从嫁，就像跛者尚能行走；前往仍可吉。","解说1_经义":"初九位置较低、角色受限，但并非完全无能力。只要承认条件限制，在适合范围内行动仍能有所成。","解说2_时位":"从时位看，本爻处在全卦发端，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦兌（说悦、交流、泽）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：歸妹以娣，以恆也；跛能履吉，相承也。","象传译文":"《象传》说：归妹以娣，是守其常分；跛能履吉，是能相承接。","象传解说":"有限能力若用在合适位置，也有价值。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **40 解䷧**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"眇能視，利幽人之貞。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 眇能視：一目虽弱仍可视。幽人：安静自守者。","译文":"一眼有损却仍能看，宜像幽人一样守正。","解说1_经义":"九二有能力却受环境限制，最适合内守清醒，不因外部关系不完美而失去自我。","解说2_时位":"从时位看，本爻处在下卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：利幽人之貞，未變常也。","象传译文":"《象传》说：幽人之贞，是没有改变常道。","象传解说":"关系受限时，保持内在完整更重要。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **51 震䷲**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"歸妹以須，反歸以娣。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 須：有等待、妾媵等异释。反歸以娣：退回到较低位的娣身份。","译文":"归妹的安排不合适，只能退回来以娣的较低身份出嫁。","解说1_经义":"六三欲求位置高于自身条件，最终必须降格调整。与其勉强占据不合适的角色，不如接受较现实的安排。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦兌（说悦、交流、泽）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：歸妹以須，未當也。","象传译文":"《象传》说：归妹以须，是位置不当。","象传解说":"角色匹配是归妹卦核心问题之一。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **34 大壯䷡**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"歸妹愆期，遲歸有時。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 愆期：错过婚期。遲歸有時：迟一些反有合适时机。","译文":"归妹错过了日期，但延迟出嫁自有合适时机。","解说1_经义":"九四说明错过预定节点不一定坏。真正合适的关系不能只由日程推动；宁迟勿错。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦震（动、发起、震动、雷）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：愆期之志，有待而行也。","象传译文":"《象传》说：愆期之志，是有所等待而后行动。","象传解说":"延迟可以是主动质量控制。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **19 臨䷒**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"帝乙歸妹，其君之袂不如其娣之袂良。月幾望，吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 君之袂：正妻衣袖。娣之袂：从嫁者衣袖。月幾望：月近圆满。","译文":"帝乙嫁妹，正妻的衣袖反不如娣华美；月亮将近满，吉。","解说1_经义":"六五尊而能降，不以外在服饰争胜。婚姻或合作中，身份真正价值不靠表面排场。","解说2_时位":"从时位看，本爻处在上卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的上卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：帝乙歸妹，不如其娣之袂良也；其位在中，以貴行也。","象传译文":"《象传》说：帝乙归妹而不如其娣之袂华美，是因六五居中，以尊贵而行谦下。","象传解说":"“贵行”而不尚饰，体现内在价值高于形式。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **58 兌䷹**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"女承筐無實，士刲羊無血，無攸利。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 承筐無實：女方捧筐却无实物。刲羊無血：男方宰羊却无血。仪式有形无实。","译文":"女子捧筐却没有实物，男子宰羊却没有血，没有什么利益。","解说1_经义":"上六把不合宜关系推到空壳状态：礼仪看似齐全，实质内容却不存在。形式不能替代真实承诺。","解说2_时位":"从时位看，本爻处在全卦终位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦震（动、发起、震动、雷）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：上六無實，承虛筐也。","象传译文":"《象传》说：上六无实，是承着空筐。","象传解说":"归妹以“形式空洞”收尾，是对关系真实性的警告。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **38 睽䷥**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"40 解䷧","二爻":"51 震䷲","三爻":"34 大壯䷡","四爻":"19 臨䷒","五爻":"58 兌䷹","上爻":"38 睽䷥"}},{"卦序":55,"卦名":"豐","卦符":"䷶","全名":"雷火豐","上卦":"震","下卦":"離","卦辞":"豐，亨。王假之，勿憂，宜日中。","彖传":"《彖》曰：豐，大也。明以動，故豐。王假之，尚大也；勿憂宜日中，宜照天下也。日中則昃，月盈則食，天地盈虛與時消息，而況于人乎，況于鬼神乎。","大象":"《象》曰：雷電皆至，豐。君子以折獄致刑。","互卦":"28 大過䷛","错卦":"59 渙䷺","综卦":"56 旅䷷","爻":[{"爻位":"初九","原文":"遇其配主，雖旬無咎，往有尚。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 配主：匹配的主人、伙伴。旬：均等、十日，也有“相等”解释。往有尚：前往可获尊尚。","译文":"遇到与自己相配的伙伴，即使彼此势均力敌也无咎；前往会有所成。","解说1_经义":"丰卦初九的繁盛来自正确合作。强者与强者相遇不一定冲突，只要目标相配，反而能共同放大成果。","解说2_时位":"从时位看，本爻处在全卦发端，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦離（明、附丽、文明、火）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：雖旬無咎，過旬災也。","象传译文":"《象传》说：虽相当而无咎，但若超过适当限度就会有灾。","象传解说":"合作也需要边界，丰不可过满。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **62 小過䷽**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"豐其蔀，日中見斗。往得疑疾，有孚發若，吉。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 吉：吉利；在占辞中表示趋向有利。 往：前往、向外发展。 孚：诚信、信实，也有取得信任之义。 蔀：遮蔽光明的草席、帷幕。日中見斗：正午却见北斗，极言昏暗。疑疾：被怀疑。","译文":"遮蔽很厚，正午竟能见到北斗；贸然前往会被怀疑。若以诚信逐步发明真相，则吉。","解说1_经义":"六二本有离明，却被上方遮蔽。信息环境黑暗时，越急于证明越可能加深怀疑；诚信与透明才是突破方式。","解说2_时位":"从时位看，本爻处在下卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦離（明、附丽、文明、火）的内卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：有孚發若，信以發志也。","象传译文":"《象传》说：有孚而发若，是以诚信发动志向。","象传解说":"丰盛系统也可能出现信息遮蔽。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **34 大壯䷡**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"豐其沛，日中見沬。折其右肱，無咎。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 沛，一作“沬”等异文，皆指更深遮蔽。折右肱：右臂受损，行动力受限。","译文":"遮蔽更深，正午仿佛见到微星；右臂折断，但无咎。","解说1_经义":"九三虽有能力，却遭环境严重遮蔽，导致行动工具受损。不是所有“无成果”都应归责个人。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：豐其沛，不可大事也；折其右肱，終不可用也。","象传译文":"《象传》说：遮蔽如此严重，不能做大事；折右肱，最终确实无法施用。","象传解说":"环境约束可能让正确能力暂时失效。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **51 震䷲**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"豐其蔀，日中見斗。遇其夷主，吉。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 夷主：相匹配、平等的主人。与初九相应。","译文":"同样处于厚蔀遮蔽、正午见斗的环境，却遇到相合的伙伴，吉。","解说1_经义":"九四仍在黑暗信息环境，但通过正确伙伴关系获得突破。丰卦中，合作是穿透遮蔽的重要通道。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦震（动、发起、震动、雷）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：豐其蔀，位不當也；日中見斗，幽不明也；遇其夷主，吉行也。","象传译文":"《象传》说：丰其蔀，是位置不当；遇其夷主，则行动可吉。","象传解说":"在复杂系统里，可信伙伴比单点判断更可靠。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **36 明夷䷣**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"來章，有慶譽，吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 來章：美德、文采前来。慶譽：庆福和声誉。","译文":"光明美好的力量前来，会有庆福和声誉，吉。","解说1_经义":"六五居尊柔中，能够吸引人才与光明而不是独自逞能。繁盛阶段的领导重点是让优秀者进来。","解说2_时位":"从时位看，本爻处在上卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦震（动、发起、震动、雷）的上卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：六五之吉，有慶也。","象传译文":"《象传》说：六五之吉，是有庆。","象传解说":"丰盛要靠开放人才维持。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **49 革䷰**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"豐其屋，蔀其家，闚其戶，闃其無人，三歲不覿，凶。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 豐其屋：把屋子建得极大。蔀其家：反把家遮暗。闚戶闃無人：窥门寂无人。三歲不覿：长期不见。","译文":"把房屋做得极盛，却把家遮蔽；从门缝看进去寂静无人，长久见不到人，凶。","解说1_经义":"上六是“丰而自蔽”的悖论：外在规模巨大，内部关系却空洞。组织越成功，越要警惕孤立、封闭和自我遮蔽。","解说2_时位":"从时位看，本爻处在全卦终位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：豐其屋，天際翔也；闚其戶闃其無人，自藏也。","象传译文":"《象传》说：丰其屋，仿佛飞到天际；窥户无人，是自我隐藏封闭。","象传解说":"繁盛若失去连接，最终变成空壳。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **30 離䷝**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"62 小過䷽","二爻":"34 大壯䷡","三爻":"51 震䷲","四爻":"36 明夷䷣","五爻":"49 革䷰","上爻":"30 離䷝"}},{"卦序":56,"卦名":"旅","卦符":"䷷","全名":"火山旅","上卦":"離","下卦":"艮","卦辞":"旅，小亨，旅貞吉。","彖传":"《彖》曰：旅，小亨。柔得中乎外而順乎剛，止而麗乎明，是以小亨旅貞吉也。旅之時義大矣哉。","大象":"《象》曰：山上有火，旅。君子以明慎用刑而不留獄。","互卦":"28 大過䷛","错卦":"60 節䷻","综卦":"55 豐䷶","爻":[{"爻位":"初六","原文":"旅瑣瑣，斯其所取災。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 瑣瑣：细碎、猥琐、过分计较。","译文":"旅途中若斤斤计较、琐碎失度，这是自己招来的灾。","解说1_经义":"旅卦处陌生环境，初六资源和地位都低，最重要的是简洁、守礼。把注意力耗在小利小怨上，最容易得罪环境。","解说2_时位":"从时位看，本爻处在全卦发端，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦艮（止、界限、山）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：旅瑣瑣，志窮災也。","象传译文":"《象传》说：旅瑣瑣，是志向困穷而自取灾。","象传解说":"旅行与寄居首先考验格局和适应力。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **30 離䷝**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"旅即次，懷其資，得童僕貞。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 即次：到旅舍安顿。懷其資：保有财物。童僕貞：得到可靠仆从。","译文":"旅人找到住处，保有资财，又有可靠的随从，吉。","解说1_经义":"六二得中，旅居的三项基础都稳：住所、资源、协助者。陌生环境中先建立这些基础，比急于扩张更重要。","解说2_时位":"从时位看，本爻处在下卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦艮（止、界限、山）的内卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：得童僕貞，終無尤也。","象传译文":"《象传》说：得到可靠童仆，最终没有过失。","象传解说":"旅行安全依赖可控的小系统。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **50 鼎䷱**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"旅焚其次，喪其童僕，貞厲。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 焚其次：旅舍被焚。喪童僕：失去帮助。貞厲：即使守正也危险。","译文":"旅舍被烧，随从也失去，处境危险。","解说1_经义":"九三刚而不中，对下过刚，容易因强势破坏寄居关系，最后同时失去场所与支持者。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦艮（止、界限、山）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：旅焚其次，亦以傷矣；以旅與下，其義喪也。","象传译文":"《象传》说：旅舍被焚，已经很受伤；以旅人身份苛待下属，义理上会失去他们。","象传解说":"身处客位更应克制权力感。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **35 晉䷢**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"旅于處，得其資斧，我心不快。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 處：暂居之所。資斧：旅资与防身工具。","译文":"旅人在暂居处停下，得到资财和工具，但内心仍不快。","解说1_经义":"九四条件有所改善，却尚未真正归属。资源齐全不等于心理安定；旅的本质仍是“非其所”。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：旅于處，未得位也；得其資斧，心未快也。","象传译文":"《象传》说：旅于处，是尚未得到应有位置；虽得资斧，心仍不快。","象传解说":"安全感既来自物质，也来自归属。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **52 艮䷳**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"射雉一矢亡，終以譽命。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 射雉一矢亡：射雉损失一箭。終以譽命：最终获得荣誉与任命。","译文":"射雉虽失去一支箭，最终却获得声誉与任命。","解说1_经义":"六五在旅途中愿意付出小成本展示能力，最终换来更大认可。寄居者要获得新环境接纳，常需先投入。","解说2_时位":"从时位看，本爻处在上卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦離（明、附丽、文明、火）的上卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：終以譽命，上逮也。","象传译文":"《象传》说：最终得到誉命，是上方认可及于自身。","象传解说":"合理投入可以转化为身份升级。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **33 遯䷠**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"鳥焚其巢，旅人先笑後號咷。喪牛于易，凶。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 鳥焚其巢：鸟巢被焚。先笑後號咷：先喜后悲。喪牛于易：在边界处失去牛，喻失去柔顺。","译文":"鸟的巢被烧毁，旅人先笑后哭；又失去牛，凶。","解说1_经义":"上九高亢失柔，把临时成功误当永久归属，最终连栖身之处也失去。旅卦最忌忘记自己仍处客位。","解说2_时位":"从时位看，本爻处在全卦终位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦離（明、附丽、文明、火）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：以旅在上，其義焚也；喪牛于易，終莫之聞也。","象传译文":"《象传》说：以旅人身份居高，其义必至焚巢；失牛而终无人闻，是彻底失去柔顺。","象传解说":"陌生环境中的傲慢成本尤其高。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **62 小過䷽**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"30 離䷝","二爻":"50 鼎䷱","三爻":"35 晉䷢","四爻":"52 艮䷳","五爻":"33 遯䷠","上爻":"62 小過䷽"}},{"卦序":57,"卦名":"巽","卦符":"䷸","全名":"巽為風","上卦":"巽","下卦":"巽","卦辞":"巽，小亨，利有攸往，利見大人。","彖传":"《彖》曰：重巽以申命。剛巽乎中正而志行，柔皆順乎剛，是以小亨，利有攸往，利見大人。","大象":"《象》曰：隨風，巽。君子以申命行事。","互卦":"38 睽䷥","错卦":"51 震䷲","综卦":"58 兌䷹","爻":[{"爻位":"初六","原文":"進退，利武人之貞。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利：适宜、有利。 進退：进退犹疑。武人：以果决行动见长者。巽卦初六柔在下，易过度顺从。","译文":"进退犹疑；宜采用武人般坚定守正的态度。","解说1_经义":"巽本为顺入，但顺到失去决定力便成为软弱。初六所缺的是边界和决断，因此反而要借“武人之贞”补足柔弱。","解说2_时位":"从时位看，本爻处在全卦发端，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：進退，志疑也；利武人之貞，志治也。","象传译文":"《象传》说：进退，是志意疑惑；利武人之贞，是为了整治其志。","象传解说":"巽不是无条件服从，而是有方向地进入。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **09 小畜䷈**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"巽在床下，用史巫紛若，吉無咎。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 床下：低下隐微之处。史巫：掌祭祀卜祝者。紛若：频繁、众多的样子。","译文":"深入到床下般隐微处，需要像史巫那样反复审察沟通，吉而无咎。","解说1_经义":"九二刚中却处巽入之卦，要求深入调查隐情。面对复杂组织或心理问题，表面判断不够，需要多渠道核实。","解说2_时位":"从时位看，本爻处在下卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：紛若之吉，得中也。","象传译文":"《象传》说：史巫纷若而吉，是因为九二得中。","象传解说":"深入不等于疑神疑鬼，得中可防止调查走向偏执。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **53 漸䷴**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"頻巽，吝。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 頻巽：反复卑巽、一次次退让。","译文":"反复表现卑巽，最终会有遗憾。","解说1_经义":"九三刚而不中，表面不断退让，内心却不真正接受，容易形成反复和失信。巽必须出于真实判断，而非策略性讨好。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻同类，无正应。它处于下卦巽（入、顺入、渗透、风木）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：頻巽之吝，志窮也。","象传译文":"《象传》说：频巽之吝，是志向走到穷处。","象传解说":"过度迎合会耗尽主体性。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **59 渙䷺**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"悔亡，田獲三品。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 田獲三品：田猎取得多种猎获，象征成果丰富。","译文":"悔恨消失，田猎获得三类猎物。","解说1_经义":"六四柔顺得位，能够把巽入转成实际成果。顺势、深入、细致执行，在此不再是姿态而是生产力。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：田獲三品，有功也。","象传译文":"《象传》说：田获三品，是确有功效。","象传解说":"正确的巽最终必须落到结果。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **44 姤䷫**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"貞吉悔亡，無不利。無初有終。先庚三日，後庚三日，吉。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 利：适宜、有利。 先庚三日、後庚三日：庚有更革之义，前后皆须准备、复盘。無初有終：开端未必好，结局可成。","译文":"守正则吉，悔亡，无所不利；开头虽不理想，最终有成。变更之前三日充分准备，之后三日继续检验，吉。","解说1_经义":"九五中正，把巽的细致贯彻到变革管理：行动前要准备，行动后要复盘。真正的改革不是宣布完就结束。","解说2_时位":"从时位看，本爻处在上卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：九五之吉，位正中也。","象传译文":"《象传》说：九五之吉，是位置中正。","象传解说":"巽入的最高形态是把命令变成可执行、可反馈的过程。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **18 蠱䷑**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"巽在床下，喪其資斧，貞凶。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 巽在床下：过度卑下。喪其資斧：失去资产和行动工具。","译文":"卑巽到床下，甚至失去自己的资财与工具；固守如此则凶。","解说1_经义":"上九把巽推到极端：为了迎合而交出资源、能力和自主权。顺从如果导致自我空心化，就已违背巽的本义。","解说2_时位":"从时位看，本爻处在全卦终位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：巽在床下，上窮也；喪其資斧，正乎凶也。","象传译文":"《象传》说：巽在床下，是走到上穷；丧其资斧，继续守此正是凶。","象传解说":"任何合作都必须保留基本主体能力。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **48 井䷯**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"09 小畜䷈","二爻":"53 漸䷴","三爻":"59 渙䷺","四爻":"44 姤䷫","五爻":"18 蠱䷑","上爻":"48 井䷯"}},{"卦序":58,"卦名":"兌","卦符":"䷹","全名":"兌為澤","上卦":"兌","下卦":"兌","卦辞":"兌，亨，利貞。","彖传":"《彖》曰：兌，說也。剛中而柔外，說以利貞，是以順乎天而應乎人。說以先民，民忘其勞；說以犯難，民忘其死。說之大，民勸矣哉。","大象":"《象》曰：麗澤，兌。君子以朋友講習。","互卦":"37 家人䷤","错卦":"52 艮䷳","综卦":"57 巽䷸","爻":[{"爻位":"初九","原文":"和兌，吉。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 和兌：和悦、平和地交流。","译文":"以和悦相待，吉。","解说1_经义":"兑卦初九没有复杂利益牵连，最适合以自然、平等的愉悦建立关系。快乐若不带操控，最容易产生信任。","解说2_时位":"从时位看，本爻处在全卦发端，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻同类，无正应。它处于下卦兌（说悦、交流、泽）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：和兌之吉，行未疑也。","象传译文":"《象传》说：和兑之吉，是行动尚无疑虑。","象传解说":"真诚的愉悦不需要过度算计。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **47 困䷮**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"孚兌，吉，悔亡。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 孚：诚信、信实，也有取得信任之义。 孚兌：以诚信产生悦。","译文":"有诚信的和悦，吉，悔恨消失。","解说1_经义":"九二得中，说明愉悦必须建立在可信基础上。讨好可以短暂令人愉快，诚信才能长期。","解说2_时位":"从时位看，本爻处在下卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦兌（说悦、交流、泽）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：孚兌之吉，信志也。","象传译文":"《象传》说：孚兑之吉，是内心有真实信念。","象传解说":"悦的质量取决于其真实性。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **17 隨䷐**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"來兌，凶。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 來兌：主动来求悦、迎合取悦。","译文":"主动迎合求悦，凶。","解说1_经义":"六三不当位，向上下求取认可，容易失去原则。若快乐依赖他人的即时反馈，关系很快变成讨好。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦兌（说悦、交流、泽）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：來兌之凶，位不當也。","象传译文":"《象传》说：来兑之凶，是位置不当。","象传解说":"悦若没有主体性，就会转为依附。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **43 夬䷪**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"商兌未寧，介疾有喜。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 商兌：商量、权衡何种悦。未寧：尚未安定。介疾有喜：隔绝有害诱惑则有喜。","译文":"对取悦之道反复权衡，尚未安定；若能隔开有害因素，会有喜。","解说1_经义":"九四处近君位置，需要判断什么样的愉悦值得接受。不是所有让人舒服的东西都有益。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻同类，无正应。它处于上卦兌（说悦、交流、泽）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：九四之喜，有慶也。","象传译文":"《象传》说：九四之喜，是会有庆成。","象传解说":"成熟的悦包含筛选和节制。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **60 節䷻**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"孚于剝，有厲。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 孚：诚信、信实，也有取得信任之义。 孚于剝：信任会侵蚀自己的对象。“剝”可指上六之阴柔诱惑。","译文":"对会剥蚀自己的人或事产生信任，会有危险。","解说1_经义":"九五虽中正，也可能因喜欢悦耳、顺从之物而降低警觉。高位者尤其容易被迎合包围。","解说2_时位":"从时位看，本爻处在上卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦兌（说悦、交流、泽）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：孚于剝，位正當也。","象传译文":"《象传》说：孚于剥而有危险，九五本来位置正当。","象传解说":"好位置不能免疫信息泡沫。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **54 歸妹䷵**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"引兌。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 引兌：牵引、诱导别人追求悦。","译文":"引诱、牵引别人来取悦。","解说1_经义":"上六自己不必强迫，只靠吸引就能让人沉溺于悦。爻辞不直接判吉凶，正因为结果取决于下方是否有判断力。","解说2_时位":"从时位看，本爻处在全卦终位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦兌（说悦、交流、泽）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：上六引兌，未光也。","象传译文":"《象传》说：上六引兑，其作用尚未光明。","象传解说":"“引悦”提示注意平台、舆论、社交关系中诱导机制的力量。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **10 履䷉**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"47 困䷮","二爻":"17 隨䷐","三爻":"43 夬䷪","四爻":"60 節䷻","五爻":"54 歸妹䷵","上爻":"10 履䷉"}},{"卦序":59,"卦名":"渙","卦符":"䷺","全名":"風水渙","上卦":"巽","下卦":"坎","卦辞":"渙，亨。王假有廟，利涉大川，利貞。","彖传":"《彖》曰：渙亨。剛來而不窮，柔得位乎外而上同。王假有廟，王乃在中也；利涉大川，乘木有功也。","大象":"《象》曰：風行水上，渙。先王以享于帝立廟。","互卦":"27 頤䷚","错卦":"55 豐䷶","综卦":"60 節䷻","爻":[{"爻位":"初六","原文":"用拯馬壯，吉。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 拯：救援。馬壯：借助强壮行动力。","译文":"用强壮的马去救援，吉。","解说1_经义":"涣卦初六在离散刚开始时就迅速救援。组织松散初期最容易恢复，必须使用足够强的行动力。","解说2_时位":"从时位看，本爻处在全卦发端，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与四爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻同类，无正应。它处于下卦坎（险、陷、流行、水）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：初六之吉，順也。","象传译文":"《象传》说：初六之吉，是顺势而行。","象传解说":"涣散越早处理越容易。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **61 中孚䷼**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"渙奔其机，悔亡。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 悔：悔恨，亦指可由反省而改的失误。 奔其机：奔向可凭依的几案、支点。“机”通“几”。","译文":"涣散之中迅速奔向可以依靠的支点，悔恨消失。","解说1_经义":"九二身处涣散，第一要务是找到稳定锚点：可信的人、制度、资源或基本事实。没有支点就无法重组。","解说2_时位":"从时位看，本爻处在下卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦坎（险、陷、流行、水）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：渙奔其机，得願也。","象传译文":"《象传》说：涣奔其机，是得到自己所愿的依托。","象传解说":"面对离散，先建立最低稳定结构。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **20 觀䷓**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"渙其躬，無悔。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔：悔恨，亦指可由反省而改的失误。 涣其躬：散去自身执着、私我。","译文":"把对自身的固执消散掉，没有悔恨。","解说1_经义":"六三说明涣不只针对组织，也针对自我。过强的自我中心会妨碍协作，必要时要先“散其躬”。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：渙其躬，志在外也。","象传译文":"《象传》说：涣其躬，是志向放在外部公共目标。","象传解说":"去私是重建共同体的前提。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **57 巽䷸**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"渙其群，元吉。渙有丘，匪夷所思。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 元吉：大吉、根本性的吉祥。 吉：吉利；在占辞中表示趋向有利。 涣其群：打散小群体、派系。涣有丘：散而后重新聚成大丘。匪夷所思：非平常思维可及。","译文":"打散原有小群体，大吉；散开之后反能形成更大的聚合，这是常人不易想到的。","解说1_经义":"六四是涣卦最典型的“先散后聚”：打破派系不是为了原子化，而是为了重建更大公共结构。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与初爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的上卦之始、进入外部阶段位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：渙其群元吉，光大也。","象传译文":"《象传》说：涣其群而元吉，是因为作用光大。","象传解说":"真正的改革常要先拆除局部利益壁垒。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **06 訟䷅**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"渙汗其大號，渙王居，無咎。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 涣汗其大號：号令像汗液遍布全身。涣王居：散布王者积聚或使政令遍及。","译文":"发布如汗液遍布的大号令，并调整王者所居所聚，无咎。","解说1_经义":"九五中正，以公开命令重建分散系统。危机沟通必须清晰、广泛、不可收回，如汗出于身。","解说2_时位":"从时位看，本爻处在上卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：王居無咎，正位也。","象传译文":"《象传》说：王居无咎，是因为居于正位。","象传解说":"高位在涣时的责任是建立全局信息一致性。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **04 蒙䷃**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"渙其血，去逖出，無咎。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 涣其血：散去伤害、血灾。一说“血”通“恤”指忧惧。去逖出：远离而出。","译文":"散去伤害与忧惧，远离危险而出，没有灾咎。","解说1_经义":"上九在涣之终，不再尝试重组危险本身，而是彻底离开伤害源。","解说2_时位":"从时位看，本爻处在全卦终位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：渙其血，遠害也。","象传译文":"《象传》说：涣其血，是远离危害。","象传解说":"并非所有关系都值得重新聚合；有些最好的涣就是离开。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **29 坎䷜**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"61 中孚䷼","二爻":"20 觀䷓","三爻":"57 巽䷸","四爻":"06 訟䷅","五爻":"04 蒙䷃","上爻":"29 坎䷜"}},{"卦序":60,"卦名":"節","卦符":"䷻","全名":"水澤節","上卦":"坎","下卦":"兌","卦辞":"節，亨。苦節不可貞。","彖传":"《彖》曰：節亨。剛柔分而剛得中。苦節不可貞，其道窮也。說以行險，當位以節，中正以通。天地節而四時成。節以制度，不傷財，不害民。","大象":"《象》曰：澤上有水，節。君子以制數度，議德行。","互卦":"27 頤䷚","错卦":"56 旅䷷","综卦":"59 渙䷺","爻":[{"爻位":"初九","原文":"不出戶庭，無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 戶庭：自家门户庭院。初九有知止之象。","译文":"不走出自家户庭，没有灾咎。","解说1_经义":"节卦初爻强调在该止时止。外部通道未开，先把行动限制在安全边界内。","解说2_时位":"从时位看，本爻处在全卦发端，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不出戶庭，知通塞也。","象传译文":"《象传》说：不出户庭，是知道通与塞的时势。","象传解说":"节制不是胆小，而是判断通塞。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **29 坎䷜**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"不出門庭，凶。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 門庭：比户庭更外一层。九二当出而不出。","译文":"连门庭都不走出去，凶。","解说1_经义":"九二与初九相反：时机已经可以行动，继续自我限制便成为过度节制。节的智慧不在“越少越好”，而在适时开关。","解说2_时位":"从时位看，本爻处在下卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦兌（说悦、交流、泽）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不出門庭凶，失時極也。","象传译文":"《象传》说：不出门庭之凶，是错失时机到了极点。","象传解说":"限制也有机会成本。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **03 屯䷂**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"不節若，則嗟若，無咎。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 不節若：不能节制。嗟若：事后叹息。","译文":"若不能自我节制，就会叹息；但责任在己，能改仍可无咎。","解说1_经义":"六三的困境来自内部失控，而非外部强迫。看到后果并愿意承担，是恢复节制的开始。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与上爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻同类，无正应。它处于下卦兌（说悦、交流、泽）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不節之嗟，又誰咎也。","象传译文":"《象传》说：不节而嗟，又能责怪谁呢？","象传解说":"小象强调个人责任。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **05 需䷄**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"安節，亨。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 亨：通达、顺畅；古义又与享献相关。 安節：安然、自然而有节。","译文":"安于合宜的节制，亨通。","解说1_经义":"六四当位，节已经从外部规则变成自然习惯。最有效的制度不是让人时时感到压迫，而是形成舒适边界。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的上卦之始、进入外部阶段位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：安節之亨，承上道也。","象传译文":"《象传》说：安节之亨，是承接上方正道。","象传解说":"良好节制具有低摩擦特征。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **58 兌䷹**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"甘節，吉。往有尚。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 往：前往、向外发展。 甘節：甘美、乐意接受的节制。往有尚：推行会受尊崇。","译文":"以甘美、合理的方式节制，吉；推行会得到尊崇。","解说1_经义":"九五中正，能设计让人愿意遵守的规则。最高水平的治理不是惩罚多，而是规则合理、可接受。","解说2_时位":"从时位看，本爻处在上卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦坎（险、陷、流行、水）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：甘節之吉，居位中也。","象传译文":"《象传》说：甘节之吉，是居位中正。","象传解说":"好规则兼顾目标与人性。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **19 臨䷒**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"苦節，貞凶，悔亡。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 凶：凶险、不利。 悔：悔恨，亦指可由反省而改的失误。 苦節：过苦、过严的节制。悔亡：若意识到问题可消悔，但固守则凶。","译文":"过度苛苦的节制，固执坚持则凶；能够及时调整，悔可消。","解说1_经义":"上六把节推到极端。规则如果让系统长期无法承受，就会失去正当性和可持续性。","解说2_时位":"从时位看，本爻处在全卦终位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与三爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻同类，无正应。它处于上卦坎（险、陷、流行、水）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：苦節貞凶，其道窮也。","象传译文":"《象传》说：苦节守固之凶，是这条道路已经走穷。","象传解说":"节制的极限由可持续性决定。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **61 中孚䷼**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"29 坎䷜","二爻":"03 屯䷂","三爻":"05 需䷄","四爻":"58 兌䷹","五爻":"19 臨䷒","上爻":"61 中孚䷼"}},{"卦序":61,"卦名":"中孚","卦符":"䷼","全名":"風澤中孚","上卦":"巽","下卦":"兌","卦辞":"中孚，豚魚吉，利涉大川，利貞。","彖传":"《彖》曰：中孚，柔在內而剛得中。說而巽，孚乃化邦也。豚魚吉，信及豚魚也；利涉大川，乘木舟虛也；中孚以利貞，乃應乎天也。","大象":"《象》曰：澤上有風，中孚。君子以議獄緩死。","互卦":"27 頤䷚","错卦":"62 小過䷽","综卦":"61 中孚䷼","爻":[{"爻位":"初九","原文":"虞吉，有它不燕。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 虞：安、预虑；有它：另有旁心。不燕：不安。","译文":"能够安定、预作准备则吉；若另有旁心，就不得安宁。","解说1_经义":"中孚讲内在诚信。初九最怕心有两端，一边承诺、一边另作盘算，信任便不能建立。","解说2_时位":"从时位看，本爻处在全卦发端，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：初九虞吉，志未變也。","象传译文":"《象传》说：初九虞吉，是志向尚未改变。","象传解说":"信用首先来自内在一致性。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **59 渙䷺**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"鳴鶴在陰，其子和之。我有好爵，吾與爾靡之。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 鶴在陰：鹤在隐蔽处鸣叫。子和之：幼鹤应和。好爵：美酒杯，也象征美好资源。靡：共享。","译文":"鹤在幽阴处鸣叫，幼鹤便应和；我有美酒，愿与你共同分享。","解说1_经义":"九二说明真正的信任不靠大声宣传。内在真实会产生自然回应，好资源也因此愿意共享。","解说2_时位":"从时位看，本爻处在下卦中位，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻同类，无正应。它处于下卦兌（说悦、交流、泽）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：其子和之，中心願也。","象传译文":"《象传》说：其子应和，是中心愿意相应。","象传解说":"信任具有共振效应。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **42 益䷩**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"得敵，或鼓或罷，或泣或歌。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 得敵：遇到对手。鼓罷泣歌：情绪行为反复。","译文":"遇到对手，一会鼓进、一会停止，一会哭、一会歌。","解说1_经义":"六三失中，内在缺少稳定中心，所以对外部关系高度反应。信任体系若依赖对方每一次反馈，就会情绪震荡。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于兌卦之位，兌的基本取象为“说悦、交流、泽”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦兌（说悦、交流、泽）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：或鼓或罷，位不當也。","象传译文":"《象传》说：或鼓或罢，是位置不当。","象传解说":"中孚要求先有自己的稳定内核。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **09 小畜䷈**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"月幾望，馬匹亡，無咎。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 月幾望：月将圆。馬匹亡：成对的马失去一匹，喻舍弃私党、独立向上。","译文":"月亮接近圆满，马匹失去一匹，没有灾咎。","解说1_经义":"六四接近九五，为进入更大信任结构，需要放下原来的小圈层配对。舍小私，才能从公共中心。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的上卦之始、进入外部阶段位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：馬匹亡，絕類上也。","象传译文":"《象传》说：马匹亡，是断开同类私系而向上。","象传解说":"忠于公共原则有时要求退出私人联盟。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **10 履䷉**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"有孚攣如，無咎。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 孚：诚信、信实，也有取得信任之义。 攣如：紧密相连。九五居中正，是全卦信任核心。","译文":"以诚信把众人紧密联结，没有灾咎。","解说1_经义":"九五的孚不是个人美德而已，而是能形成制度性连接。真正的信用中心使各方愿意长期协作。","解说2_时位":"从时位看，本爻处在上卦中位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻同类，无正应。它处于上卦巽（入、顺入、渗透、风木）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：有孚攣如，位正當也。","象传译文":"《象传》说：有孚攣如，是位置正当。","象传解说":"信任与权位相称，才能稳定扩散。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **41 損䷨**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"翰音登于天，貞凶。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 翰音：鸡鸣，翰飞高音；登于天：声音虚高。贞凶。","译文":"鸡鸣之声高到天上，若固守这种虚声则凶。","解说1_经义":"上九的信只剩“声音”，实际承载不足。信用若变成品牌、口号、声量而脱离事实，就走向反面。","解说2_时位":"从时位看，本爻处在全卦终位，属于巽卦之位，巽的基本取象为“入、顺入、渗透、风木”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦巽（入、顺入、渗透、风木）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：翰音登于天，何可長也。","象传译文":"《象传》说：翰音登天，怎么能够长久？","象传解说":"诚信最终必须落地，不能靠声誉自我循环。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **60 節䷻**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"59 渙䷺","二爻":"42 益䷩","三爻":"09 小畜䷈","四爻":"10 履䷉","五爻":"41 損䷨","上爻":"60 節䷻"}},{"卦序":62,"卦名":"小過","卦符":"䷽","全名":"雷山小過","上卦":"震","下卦":"艮","卦辞":"小過，亨，利貞。可小事，不可大事。飛鳥遺之音，不宜上宜下，大吉。","彖传":"《彖》曰：小過，小者過而亨也。過以利貞，與時行也。柔得中，是以小事吉也；剛失位而不中，是以不可大事也。有飛鳥之象焉。飛鳥遺之音，不宜上宜下，大吉，上逆而下順也。","大象":"《象》曰：山上有雷，小過。君子以行過乎恭，喪過乎哀，用過乎儉。","互卦":"28 大過䷛","错卦":"61 中孚䷼","综卦":"62 小過䷽","爻":[{"爻位":"初六","原文":"飛鳥以凶。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 飛鳥以凶：小过卦有飞鸟之象；初爻不宜上飞。","译文":"飞鸟急于上飞，会有凶险。","解说1_经义":"小过强调“小事可过、宜下不宜上”。初六一开始就向上冒进，与全卦时势相逆。","解说2_时位":"从时位看，本爻处在全卦发端，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦艮（止、界限、山）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：飛鳥以凶，不可如何也。","象传译文":"《象传》说：飞鸟以凶，已经无可如何。","象传解说":"错误方向若从起点就过度，修正空间很小。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **55 豐䷶**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"過其祖，遇其妣；不及其君，遇其臣；無咎。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 過其祖遇其妣：越过祖父而遇祖母。不及其君遇其臣：未达到君而遇到臣。无咎。","译文":"越过祖父而遇到祖母；没有达到君主，却遇到臣下；无咎。","解说1_经义":"六二柔中，以“不过高”获得适当对象。小过之时不求最高层级，选择可达、合适的关系反而正确。","解说2_时位":"从时位看，本爻处在下卦中位，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位、得中，并且与五爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻同类，无正应。它处于下卦艮（止、界限、山）的内卦中位位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：不及其君，臣不可過也。","象传译文":"《象传》说：不及其君，是臣不应越过本分。","象传解说":"克制层级欲，是小过的重要原则。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **32 恆䷟**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"弗過防之，從或戕之，凶。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 弗過防之：没有过度防备。從或戕之：若顺从疏忽，可能被伤。","译文":"若不过度防备却也没有应有防范，随意行事可能遭人伤害，凶。","解说1_经义":"九三刚强，容易低估小风险。小过之时恰恰应在细节上“稍过于谨慎”，否则小问题可造成实害。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于艮卦之位，艮的基本取象为“止、界限、山”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦艮（止、界限、山）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：從或戕之，凶如何也。","象传译文":"《象传》说：从而被戕，其凶可知。","象传解说":"小风险需要略高于平常的安全余量。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **16 豫䷏**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"無咎，弗過遇之。往厲必戒，勿用永貞。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 往：前往、向外发展。 弗過遇之：不越过而相遇。往厲必戒：前往有危险必须戒。勿用永貞：不可把停守绝对化为永久。","译文":"不过分而能遇合，无咎；若前往则有危险，必须警戒；也不可把一种做法永久固守。","解说1_经义":"九四处进退节点，既不能过进，也不能把谨慎变成永远不动。小过的“过”是临时校准，不是永久策略。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：弗過遇之，位不當也；往厲必戒，終不可長也。","象传译文":"《象传》说：弗过遇之，是位置不当；往厉必戒，是这种状态不可长久。","象传解说":"风险策略也要随环境更新。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **15 謙䷎**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"密雲不雨，自我西郊。公弋取彼在穴。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 密雲不雨：云厚却未下雨。公弋取彼在穴：公用箭取得藏于穴中的目标。","译文":"密云不雨，从西郊而来；公应射取藏在穴中的对象。","解说1_经义":"六五居尊但阴柔，小过时大范围施泽条件未成，宜把注意力放在低处、隐蔽、具体的小目标。","解说2_时位":"从时位看，本爻处在上卦中位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻不当位、得中，并且与二爻无正应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻同类，无正应。它处于上卦震（动、发起、震动、雷）的上卦中位位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：密雲不雨，已上也。","象传译文":"《象传》说：密云不雨，是力量已经过高。","象传解说":"越想做大，越可能失去落地能力。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **31 咸䷞**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"弗遇過之，飛鳥離之，凶，是謂災眚。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 凶：凶险、不利。 弗遇過之：没有遇到合适点却越过去。離：罹，遭遇。","译文":"没有相遇反而越得过头，飞鸟遭到灾害，凶，这叫灾眚。","解说1_经义":"上六彻底违背“宜下不宜上”，小过变成大过。适度校准若没有边界，就会转化为灾难。","解说2_时位":"从时位看，本爻处在全卦终位，属于震卦之位，震的基本取象为“动、发起、震动、雷”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦震（动、发起、震动、雷）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：弗遇過之，已亢也。","象传译文":"《象传》说：弗遇而过，是已经过于高亢。","象传解说":"小过的终极警告是“微调不可无限化”。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **56 旅䷷**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"55 豐䷶","二爻":"32 恆䷟","三爻":"16 豫䷏","四爻":"15 謙䷎","五爻":"31 咸䷞","上爻":"56 旅䷷"}},{"卦序":63,"卦名":"既濟","卦符":"䷾","全名":"水火既濟","上卦":"坎","下卦":"離","卦辞":"既濟，亨小，利貞。初吉終亂。","彖传":"《彖》曰：既濟亨，小者亨也。利貞，剛柔正而位當也。初吉，柔得中也；終止則亂，其道窮也。","大象":"《象》曰：水在火上，既濟。君子以思患而豫防之。","互卦":"64 未濟䷿","错卦":"64 未濟䷿","综卦":"64 未濟䷿","爻":[{"爻位":"初九","原文":"曳其輪，濡其尾，無咎。","注释":"初九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 曳其輪：拖住车轮。濡其尾：渡水尾巴沾湿。无咎。","译文":"拖住车轮，过水时只沾湿尾巴，没有灾咎。","解说1_经义":"既济看似完成，初九却强调完成后的第一动作是减速。系统刚成功时最容易因兴奋继续冲，主动制动车轮才能保成果。","解说2_时位":"从时位看，本爻处在全卦发端，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阳爻，居阳位，当位；与四爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的发端位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：曳其輪，義無咎也。","象传译文":"《象传》说：曳其轮，从义理上无咎。","象传解说":"完成之后先稳住，是既济的基本智慧。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为9（老阳），则此爻发动，单爻之卦为 **39 蹇䷦**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六二","原文":"婦喪其茀，勿逐，七日得。","注释":"六二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 茀：妇人车蔽、首饰，古义有别。七日得：失而复得。","译文":"妇人失去车蔽，不必追赶，七日后自然复得。","解说1_经义":"六二中正，短期损失不必过度干预。既济系统整体已稳，小波动可通过自身机制恢复。","解说2_时位":"从时位看，本爻处在下卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阴爻，居阴位，当位，并且得中；与五爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的内卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：七日得，以中道也。","象传译文":"《象传》说：七日得，是因为守中道。","象传解说":"稳定系统需要允许自我修复。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为6（老阴），则此爻发动，单爻之卦为 **05 需䷄**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九三","原文":"高宗伐鬼方，三年克之，小人勿用。","注释":"九三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 小人：与君子相对，多指德行、见识或担当不足者，并非单纯社会身份。 高宗伐鬼方：商王高宗征伐边方故事。三年克之：长期方成。小人勿用。","译文":"高宗征伐鬼方，经过三年才取胜；小人不可任用。","解说1_经义":"九三说明即便条件已“既济”，大工程仍可能长期艰苦。胜利后尤其要防把关键资源交给德能不足者。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阳爻，居阳位，当位；与上爻阴阳相反，有应。它处于下卦離（明、附丽、文明、火）的下卦之终、内外转换前位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：三年克之，憊也。","象传译文":"《象传》说：三年克之，是非常疲惫的事。","象传解说":"成功成本必须被真实计入，不可浪漫化。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为9（老阳），则此爻发动，单爻之卦为 **03 屯䷂**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六四","原文":"繻有衣袽，終日戒。","注释":"六四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 繻有衣袽：丝帛破处用旧衣絮塞补；文本古义有异说。终日戒：全天警戒。","译文":"衣物、舟漏已有可补之处，应整日保持警戒。","解说1_经义":"六四进入既济后半段，细小裂缝已经出现。成功系统的风险往往不是大敌，而是维护缺口。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阴爻，居阴位，当位；与初爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的上卦之始、进入外部阶段位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：終日戒，有所疑也。","象传译文":"《象传》说：终日戒，是因为已有可疑之处。","象传解说":"维护期需要比建设期更敏感于小异常。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为6（老阴），则此爻发动，单爻之卦为 **49 革䷰**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九五","原文":"東鄰殺牛，不如西鄰之禴祭，實受其福。","注释":"九五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 東鄰殺牛：厚祭。西鄰禴祭：薄祭。實受其福：真正得福。","译文":"东邻杀牛厚祭，不如西邻以薄祭合时，反而真正得到福。","解说1_经义":"九五中正强调“合时与诚信”胜过资源堆砌。仪式规模大不等于效果好，精准、适时、真诚更重要。","解说2_时位":"从时位看，本爻处在上卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阳爻，居阳位，当位，并且得中；与二爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的上卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：東鄰殺牛，不如西鄰之時也；實受其福，吉大來也。","象传译文":"《象传》说：东邻杀牛不如西邻合时；真正受福，是吉庆实至。","象传解说":"既济之时尤其忌用规模感替代真实质量。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为9（老阳），则此爻发动，单爻之卦为 **36 明夷䷣**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上六","原文":"濡其首，厲。","注释":"上六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 濡其首：涉水过深，头也湿了。厉。","译文":"过水湿到头顶，危险。","解说1_经义":"上六在已完成之后仍继续向前，最终把自己重新置入险中。既济不是永远完成，过度延伸会破坏完成状态。","解说2_时位":"从时位看，本爻处在全卦终位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阴爻，居阴位，当位；与三爻阴阳相反，有应。它处于上卦坎（险、陷、流行、水）的全卦之终位置；下乘阳刚，有“乘刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：濡其首厲，何可久也。","象传译文":"《象传》说：濡其首而危险，怎么可能长久？","象传解说":"完成之后最大的风险常是“不知道结束”。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为6（老阴），则此爻发动，单爻之卦为 **37 家人䷤**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"39 蹇䷦","二爻":"05 需䷄","三爻":"03 屯䷂","四爻":"49 革䷰","五爻":"36 明夷䷣","上爻":"37 家人䷤"}},{"卦序":64,"卦名":"未濟","卦符":"䷿","全名":"火水未濟","上卦":"離","下卦":"坎","卦辞":"未濟，亨。小狐汔濟，濡其尾，無攸利。","彖传":"《彖》曰：未濟亨，柔得中也。小狐汔濟，未出中也；濡其尾，無攸利，不續終也。雖不當位，剛柔應也。","大象":"《象》曰：火在水上，未濟。君子以慎辨物居方。","互卦":"63 既濟䷾","错卦":"63 既濟䷾","综卦":"63 既濟䷾","爻":[{"爻位":"初六","原文":"濡其尾，吝。","注释":"初六：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吝：艰难、遗憾、局促之象。 濡其尾：小狐渡水尾巴沾湿。吝。","译文":"小狐渡水，尾巴先被沾湿，有遗憾。","解说1_经义":"未济初六尚未具备过河能力，却急于开始。未完成阶段最重要的是评估能力与水势，而非靠热情抢跑。","解说2_时位":"从时位看，本爻处在全卦发端，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与四爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第1爻为阴爻，居阳位，不当位；与四爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的发端位置；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：濡其尾，亦不知極也。","象传译文":"《象传》说：濡其尾，是还不知道事情的极限。","象传解说":"不知边界，是未济初期的主要风险。","大衍实占":"若以大衍筮法占得本卦，而初爻所得为6（老阴），则此爻发动，单爻之卦为 **38 睽䷥**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九二","原文":"曳其輪，貞吉。","注释":"九二：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 吉：吉利；在占辞中表示趋向有利。 曳其輪：拖住车轮。九二在坎中得中。","译文":"拖住车轮，守正则吉。","解说1_经义":"九二有行动力，但主动制动。未济不是不能前进，而是在关键条件未成熟时先控制速度。","解说2_时位":"从时位看，本爻处在下卦中位，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位、得中，并且与五爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第2爻为阳爻，居阴位，不当位，并且得中；与五爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的内卦中位位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：九二貞吉，中以行正也。","象传译文":"《象传》说：九二贞吉，是居中而行于正道。","象传解说":"自我制动让能力保存到真正需要的时候。","大衍实占":"若以大衍筮法占得本卦，而二爻所得为9（老阳），则此爻发动，单爻之卦为 **35 晉䷢**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六三","原文":"未濟，征凶，利涉大川。","注释":"六三：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 利涉大川：适宜渡越大河，常喻适宜承担重大行动或跨越艰险。 凶：凶险、不利。 利：适宜、有利。 征：前往、出行、采取进取行动。 未濟征凶：条件未完成时直接进取凶。利涉大川：却又说适宜涉大川，显示必须在充分准备后承担关键跨越。","译文":"事情尚未完成，贸然征进会凶；但若具备条件，则最终必须渡越大川。","解说1_经义":"六三处内外转换，不能停在“永远准备”。它同时给出警告与使命：现在硬闯不行，但跨越本身终究要做。","解说2_时位":"从时位看，本爻处在下卦终位、内外转折前，属于坎卦之位，坎的基本取象为“险、陷、流行、水”。本爻不当位，并且与上爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第3爻为阴爻，居阳位，不当位；与上爻阴阳相反，有应。它处于下卦坎（险、陷、流行、水）的下卦之终、内外转换前位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：未濟征凶，位不當也。","象传译文":"《象传》说：未济而征凶，是因为位置不当。","象传解说":"时机不对不等于目标错误。","大衍实占":"若以大衍筮法占得本卦，而三爻所得为6（老阴），则此爻发动，单爻之卦为 **50 鼎䷱**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"九四","原文":"貞吉，悔亡。震用伐鬼方，三年有賞于大國。","注释":"九四：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 悔亡：悔恨或不利因素消除。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 震用伐鬼方：以雷厉行动征伐鬼方。三年有賞于大國：长期努力后受赏。","译文":"守正则吉，悔恨消失；奋力征伐鬼方，经过三年，在大国获得奖赏。","解说1_经义":"九四进入上卦离明，终于到了可以长期执行的阶段。未济转向济，需要的不只是一次冲刺，而是多年持续投入。","解说2_时位":"从时位看，本爻处在上卦初位、外部阶段开始，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与初爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第4爻为阳爻，居阴位，不当位；与初爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的上卦之始、进入外部阶段位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：貞吉悔亡，志行也。","象传译文":"《象传》说：贞吉悔亡，是志向得到施行。","象传解说":"从准备期进入执行期，节奏由谨慎转为持续。","大衍实占":"若以大衍筮法占得本卦，而四爻所得为9（老阳），则此爻发动，单爻之卦为 **04 蒙䷃**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"六五","原文":"貞吉，無悔。君子之光，有孚，吉。","注释":"六五：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 君子：有德行、有担当之人；《易传》中常作为修德主体。 有孚：有诚信、取得信任。 吉：吉利；在占辞中表示趋向有利。 悔：悔恨，亦指可由反省而改的失误。 孚：诚信、信实，也有取得信任之义。 君子之光：君子德业光明。有孚：有诚信。","译文":"守正则吉，没有悔恨；君子的光明因诚信而显现，吉。","解说1_经义":"六五居中，虽阴居阳位却以柔明统合。未济接近完成时，真正的标志不是外在宣布“成功”，而是信用与价值已经可见。","解说2_时位":"从时位看，本爻处在上卦中位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位、得中，并且与二爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第5爻为阴爻，居阳位，不当位，并且得中；与二爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的上卦中位位置；下乘阳刚，有“乘刚”关系；上承阳刚，有“承刚”关系。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：君子之光，其暉吉也。","象传译文":"《象传》说：君子之光，其光辉带来吉。","象传解说":"接近完成时，德性与公信力比速度更重要。","大衍实占":"若以大衍筮法占得本卦，而五爻所得为6（老阴），则此爻发动，单爻之卦为 **06 訟䷅**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"},{"爻位":"上九","原文":"有孚于飲酒，無咎。濡其首，有孚失是。","注释":"上九：爻题。“九”为阳爻，“六”为阴爻；“初、二、三、四、五、上”表示自下而上的爻位次序。 有孚：有诚信、取得信任。 孚：诚信、信实，也有取得信任之义。 有孚于飲酒：有诚信而饮酒庆贺。濡其首：饮乐失节，如渡水没首。有孚失是：即使有孚也失去正确。","译文":"有诚信而饮酒庆贺，无咎；但若沉溺以至濡首，即使原本有诚信，也会失去正确尺度。","解说1_经义":"上九已经跨过最困难阶段，可以庆祝，但未济以“不可失节”收尾。任何成功都不是终局，失去节制会立刻开启新的未济。","解说2_时位":"从时位看，本爻处在全卦终位，属于離卦之位，離的基本取象为“明、附丽、文明、火”。本爻不当位，并且与三爻有应。这些结构条件不是机械决定吉凶，而是说明本爻的力量是否容易得到合适位置、中心性与关系支持；实际解释仍须回到本卦主题及本条爻辞。","结构分析":"第6爻为阳爻，居阴位，不当位；与三爻阴阳相反，有应。它处于上卦離（明、附丽、文明、火）的全卦之终位置。因此判断本爻不能只看“阴/阳好坏”，而要同时看爻性、爻位、是否得中、是否有应以及全卦所处阶段。","象传":"《象》曰：飲酒濡首，亦不知節也。","象传译文":"《象传》说：饮酒以至濡首，也是因为不知节制。","象传解说":"六十四卦最后不是“完美完成”，而是以开放的节制意识进入下一轮变化。","大衍实占":"若以大衍筮法占得本卦，而上爻所得为9（老阳），则此爻发动，单爻之卦为 **40 解䷧**。实占时应先以本卦把握处境，再以本爻爻辞作为变化焦点，最后结合之卦判断变化后的结构；不可只抓“吉/凶”一字作机械结论。"}],"单爻发动之卦":{"初爻":"38 睽䷥","二爻":"35 晉䷢","三爻":"50 鼎䷱","四爻":"04 蒙䷃","五爻":"06 訟䷅","上爻":"40 解䷧"}}];
